import { Suspense, useEffect, useState } from "react";
import { useRoutes, useLocation, useNavigate } from "react-router-dom";
import "./components/ChatArea/markdown-theme.css";
import Sidebar, { MobileBottomNav } from "./components/Sidebar/Sidebar";
import Header from "./components/common/Header";
import Footer from "./components/common/Footer";
import ConfigPanel from "./components/ConfigPanel/ConfigPanel";
import ToastContainer from "./components/common/ToastContainer";
import KeyboardShortcutsHelp from "./components/common/KeyboardShortcutsHelp";
import { FirstRunWizard } from "./components/views/FirstRunWizard";
import { LLMSetupGuide } from "./components/views/LLMSetupGuide";
import { ErrorBoundary } from "./components/common/ErrorBoundary";
import { OperationStatusBar } from "./components/common/OperationStatusBar";
import { TooltipProvider } from "./components/ui/tooltip";
import routes from "./routes";
import { useConfigStore } from "./stores/configStore";
import { useChatStore } from "./stores/chat";
import { useSessionStore } from "./stores/sessionStore";
import { useNavigationStore } from "./stores/navigationStore";
import { useRootStore } from "./stores/root-store";
import { registerBuiltinModules } from "./stores/root-store/moduleRegistry";
import { useKeyboard } from "./hooks/useKeyboard";
import { useBuddyNotification } from "./hooks/useBuddyNotification";
import { useNotificationSSE } from "./hooks/useNotificationSSE";
import NotificationPanel from "./components/views/NotificationPanel";
import { useInitApp } from "./hooks/useInitApp";
import { useAutoCreateSession } from "./hooks/useAutoCreateSession";

function App() {
  const setActivePage = useNavigationStore((s) => s.setActivePage);
  const _setNavigate = useNavigationStore((s) => s._setNavigate);
  const { config } = useConfigStore();
  const location = useLocation();
  const navigate = useNavigate();
  const { initState, completeWizard } = useInitApp();

  // LLM 閰嶇疆寮曞锛歳eady 鍚庢娴嬫槸鍚﹀凡閰嶇疆 AI 妯″瀷
  const [showLLMGuide, setShowLLMGuide] = useState(false);
  const [llmGuideChecked, setLlmGuideChecked] = useState(false);

  useEffect(() => {
    if (initState.phase === "ready" && !llmGuideChecked) {
      setShowLLMGuide(true);
      setLlmGuideChecked(true);
    }
  }, [initState.phase, llmGuideChecked]);

  // Root Store: 宸ヤ綔绌洪棿鍒濆鍖栵紙涓庣幇鏈?stores 骞惰锛塡n  const rootCurrentWorktreeId = useRootStore((s) => s.currentWorktreeId);
  const rootCreateWorktree = useRootStore((s) => s.createWorktree);
  const rootSwitchWorktree = useRootStore((s) => s.switchWorktree);

  // 鈿狅笍 useRoutes 蹇呴』鏃犳潯浠惰皟鐢紝鏀惧湪鏉′欢 return 涔嬪墠
  // 鍚﹀垯鍒濆鍖栭樁娈佃蛋 early return 鏃朵笉璋冪敤 useRoutes锛孿n  // 鍒濆鍖栧畬鎴愬悗鎵嶈皟鐢紝浼氬鑷?React Hooks 椤哄簭鍙樺寲 鈫?鐧藉睆/宕╂簝
  const routeElement = useRoutes(routes);

  useKeyboard();
  useBuddyNotification();
  useNotificationSSE();
  useAutoCreateSession(); // Phase 7: URL 瀵艰埅 鈫?SessionHub 鑷姩鍒涘缓妯″潡 session
  // useSessionBridge / useWorktreeSync 宸茬Щ闄わ細鍚屾閫昏緫宸插唴缃埌 sessionStore / workspaceStore 涓璡n
  // 涓婚鍒囨崲
  useEffect(() => {
    if (config.theme === "dark") {
      document.documentElement.classList.add("dark");
    } else {
      document.documentElement.classList.remove("dark");
    }
  }, [config.theme]);

  // 瀵艰埅鍚屾
  useEffect(() => {
    _setNavigate(navigate);
  }, [_setNavigate, navigate]);

  // 璺敱鍚屾鍒?activePage
  useEffect(() => {
    const path = location.pathname.replace("/", "");
    const page = path === "" ? "home" : path;
    setActivePage(page as any);
  }, [location.pathname, setActivePage]);

  // 鐭ヨ瘑搴揬

浜嬩欢鐩戝惉
  useEffect(() => {
    function handleAppendKnowledge(e: Event) {
      const detail = (e as CustomEvent).detail as
        { title: string; content: string } | undefined;
      if (!detail?.content) return;

      const sessionState = useSessionStore.getState();
      const sessionId = sessionState.currentSession?.id;
      if (!sessionId) {
        // 鏃犲綋鍓嶄細璇濇椂锛屽厛瀵艰埅鍒拌亰澶╅〉璁╃郴缁熻嚜鍔ㄥ垱寤轰細璇漒n        navigate("/");
        return;
      }

      const chatState = useChatStore.getState();
      const systemMsg = {
        id: crypto.randomUUID(),
        role: "system" as const,
        content: `[鐭ヨ瘑搴撴枃妗? ${detail.title}]\n\n${detail.content}`,
        timestamp: Date.now(),
        session_id: sessionId,
      };
      chatState.addMessage(systemMsg);

      // 瀵艰埅鍒拌亰澶╅〉
      navigate("/");
    }

    window.addEventListener("liri:append-knowledge", handleAppendKnowledge);
    return () =>
      window.removeEventListener(
        "liri:append-knowledge",
        handleAppendKnowledge,
      );
  }, [navigate]);

  // Root Store: 棣栨鍚姩鏃惰嚜鍔ㄥ垱寤洪粯璁ゅ伐浣滅┖闂?+ 娉ㄥ唽妯″潡
  useEffect(() => {
    if (initState.phase !== "ready") return;

    // 娉ㄥ唽鍐呯疆妯″潡瑙嗗浘缁勪欢
    registerBuiltinModules();

    if (rootCurrentWorktreeId) return;

    // 鍒涘缓榛樿宸ヤ綔绌洪棿
    const wtId = rootCreateWorktree({ name: "榛樿宸ヤ綔绌洪棿", path: "." });
    rootSwitchWorktree(wtId);
  }, [
    initState.phase,
    rootCurrentWorktreeId,
    rootCreateWorktree,
    rootSwitchWorktree,
  ]);

  // 鍒濆鍖栨湭瀹屾垚 / 鍔犺浇澶辫触鏃舵樉绀鸿繃娓℃€乗n  if (initState.phase !== "ready" && initState.phase !== "first_run_wizard") {
    return (
      <div className="flex h-screen items-center justify-center bg-gray-100 dark:bg-gray-900">
        {initState.phase === "error" ? (
          <div className="text-center">
            <div className="text-red-500 text-lg mb-2">鍒濆鍖栧け璐?/div>
            <div className="text-sm text-gray-500">{initState.error}</div>
          </div>
        ) : (
          <div className="text-gray-400 text-sm">姝ｅ湪鍒濆鍖?..</div>
        )}
      </div>
    );
  }

  return (
    <TooltipProvider>
      <div className="flex flex-col h-screen bg-gray-100 dark:bg-gray-900">
        <Header />
        <OperationStatusBar />
        <ToastContainer />
        <NotificationPanel />
        <div className="flex flex-1 overflow-hidden">
          <div className="hidden lg:block">
            <Sidebar />
          </div>
          <div className="flex-1 flex page-transition-enter overflow-hidden">
            <ErrorBoundary>
              <Suspense fallback={null}>{routeElement}</Suspense>
            </ErrorBoundary>
          </div>
        </div>
        <Footer />
        <MobileBottomNav />
        <ConfigPanel />
        <KeyboardShortcutsHelp />
        {initState.phase === "first_run_wizard" && (
          <FirstRunWizard onComplete={completeWizard} />
        )}
        {showLLMGuide && (
          <LLMSetupGuide onDismiss={() => setShowLLMGuide(false)} />
        )}
      </div>
    </TooltipProvider>
  );
}

export default App;

import { useTranslation } from "react-i18next";
import { useState, useEffect } from "react";
import { httpLegacy as http } from "../../services/httpClient";
import { handleClientError } from "../../utils/handleError";

interface ReviewIssue {
  severity: string;
  description: string;
  suggestion?: string;
}

interface PlanReview {
  stepId: string;
  pass: boolean;
  score: number;
  issues: ReviewIssue[];
  summary: string;
}

interface PlanStep {
  id: string;
  description: string;
  status: string;
  acceptanceCriteria?: string;
  reviewResult?: PlanReview;
  retryCount: number;
  maxRetries: number;
  decision?: string;
  result?: string;
  error?: string;
}

interface Plan {
  id: string;
  description: string;
  steps: PlanStep[];
  status: string;
}

interface PdcaStatus {
  taskId: string;
  planId: string;
  phase: string;
  plan?: Plan;
  progress?: {
    total: number;
    pending: number;
    running: number;
    completed: number;
    failed: number;
    cancelled: number;
    percent: number;
  };
  currentStep?: PlanStep;
  audit?: {
    completedSteps: number;
    failedSteps: number;
    totalSteps: number;
    totalDurationMs: number;
    totalRetries: number;
    summary: string;
  };
}

interface PdcaPipelineProps {
  taskId: string;
}

const PHASE_ICONS: Record<string, string> = {
  plan: "馃搵",
  execute: "馃彈",
  review: "馃攳",
  decide: "鉁匼

馃帀",
};

const PHASE_NAMES: Record<string, string> = {
  plan: "agent.plan",
  execute: "agent.execute",
  review: "agent.review",
  decide: "agent.decide",
  completed: "agent.completed",
};

const STATUS_COLOR: Record<string, string> = {
  pending: "bg-yellow-400",
  running: "bg-blue-400 animate-pulse",
  completed: "bg-green-400",
  failed: "bg-red-400",
  cancelled: "bg-gray-400",
};

const STATUS_TEXT: Record<string, string> = {
  pending: "agent.idle",
  running: "agent.running",
  completed: "agent.completed",
  failed: "agent.error",
  cancelled: "common.cancel",
};

const DECISION_TEXT: Record<string, string> = {
  approved: "鉁?閫氳繃",
  retry: "馃攧 閲嶈瘯",
  skip: "鈴?璺宠繃",
  escalate: "鈿?涓婃姤",
};

export default function PdcaPipeline({ taskId }: PdcaPipelineProps) {
  const [status, setStatus] = useState<PdcaStatus | null>(null);
  const [loading, setLoading] = useState(true);
  const [notFound, setNotFound] = useState(false);
  const [expandedStep, setExpandedStep] = useState<string | null>(null);
  const [actionLoading, setActionLoading] = useState<string | null>(null);
  const { t } = useTranslation();

  const load = async () => {
    setLoading(true);
    try {
      const res = await http.get<PdcaStatus>(`/v1/pdca/${taskId}`);
      if (typeof res === "object" && res !== null && "taskId" in res) {
        setStatus(res as PdcaStatus);
        setNotFound(false);
      }
    } catch (e) {
      handleClientError(e, {
        module: "components:agent:PdcaPipeline",
        action: "load",
      });
      // 404/500 鈥?鏃?PDCA 浠诲姟鍏宠仈锛屽仠姝㈣疆璇n      setNotFound(true);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    load();
  }, [taskId]);

  // 浠呭湪鐘舵€侀潪绌轰笖闈?404 鏃跺惎鍔ㄨ疆璇n  useEffect(() => {
    if (notFound || !status) return;
    const timer = setInterval(load, 5000);
    return () => clearInterval(timer);
  }, [notFound, status, taskId]);

  const handleReview = async (stepId: string) => {
    setActionLoading(stepId);
    try {
      await http.post(`/v1/pdca/${taskId}/step/${stepId}/review`);
      load();
    } catch (e) {
      handleClientError(e, {
        module: "components:agent:PdcaPipeline",
        action: "handleReview",
      });
    } finally {
      setActionLoading(null);
    }
  };

  const handleDecide = async (stepId: string, decision: string) => {
    setActionLoading(stepId);
    try {
      await http.post(`/v1/pdca/${taskId}/step/${stepId}/decide`, { decision });
      load();
    } catch (e) {
      handleClientError(e, {
        module: "components:agent:PdcaPipeline",
        action: "handleDecide",
      });
    } finally {
      setActionLoading(null);
    }
  };

  if (loading && !status) {
    return (
      <div className="flex items-center justify-center py-6">
        <div className="w-4 h-4 border-2 border-blue-500 border-t-transparent rounded-full animate-spin" />
      </div>
    );
  }

  if (!status || !status.plan) {
    return (
      <div className="space-y-3">
        <div className="text-center py-4">
          <p className="text-xs text-gray-400">{t("agent.noAgents")}</p>
          <button
            onClick={load}
            className="mt-2 text-xs text-blue-600 hover:text-blue-800"
          >
            鍒锋柊
          </button>
        </div>
      </div>
    );
  }

  const { plan, progress, phase, audit } = status;

  return (
    <div className="space-y-3 max-h-[400px] overflow-y-auto">
      {/* Phase 鎸囩ず鍣?*/}
      <div className="flex items-center gap-1.5">
        {(["plan", "execute", "review", "decide", "completed"] as const).map(
          (p) => (
            <div
              key={p}
              className={`flex-1 flex flex-col items-center ${
                phase === p ? "opacity-100" : "opacity-40"
              }`}
            >
              <span className="text-sm">{PHASE_ICONS[p]}</span>
              <span className="text-[9px] text-gray-500 dark:text-gray-400 mt-0.5">
                {PHASE_NAMES[p].split(" ")[0]}
              </span>
              {phase === p && (
                <div className="w-full h-0.5 bg-blue-500 mt-1 rounded" />
              )}
            </div>
          ),
        )}
      </div>

      {/* 鎬讳綋杩涘害 */}
      {progress && (
        <div>
          <div className="flex items-center justify-between mb-1">
            <span className="text-xs text-gray-500">鎬讳綋杩涘害</span>
            <span className="text-xs font-medium text-gray-700 dark:text-gray-300">
              {progress.percent}%
            </span>
          </div>
          <div className="w-full h-1.5 bg-gray-200 dark:bg-gray-700 rounded-full overflow-hidden">
            <div
              className="h-full bg-blue-500 rounded-full transition-all duration-300"
              style={{ width: `${progress.percent}%` }}
            />
          </div>
          <div className="flex justify-between mt-1 text-[10px] text-gray-400">
            <span>鉁?{progress.completed}</span>
            <span>馃攧 {progress.running}</span>
            <span>鈴?{progress.pending}</span>
            <span>鉂?{progress.failed}</span>
          </div>
        </div>
      )}

      {/* 姝ラ鍒楄〃 */}
      <div>
        <span className="text-xs font-medium text-gray-500 dark:text-gray-400 mb-1.5 block">
          姝ラ ({plan.steps.length})
        </span>
        <div className="space-y-1.5">
          {plan.steps.map((step, si) => (
            <div
              key={step.id}
              className="border border-gray-200 dark:border-gray-700 rounded"
            >
              {/* Step Header */}
              <button
                onClick={() =>
                  setExpandedStep(expandedStep === step.id ? null : step.id)
                }
                className="w-full flex items-center gap-2 px-2.5 py-1.5 hover:bg-gray-50 dark:hover:bg-gray-700/50"
              >
                <span className="w-4 h-4 flex items-center justify-center rounded-full border border-gray-300 dark:border-gray-600 text-[9px] text-gray-500 shrink-0">
                  {step.retryCount > 0 ? `R${step.retryCount}` : si + 1}
                </span>
                <span
                  className={`w-1.5 h-1.5 rounded-full shrink-0 ${STATUS_COLOR[step.status] || "bg-gray-300"}`}
                />
                <span className="text-xs text-gray-700 dark:text-gray-300 truncate flex-1 text-left">
                  {step.description}
                </span>
                <div className="flex items-center gap-1 shrink-0">
                  {step.reviewResult && (
                    <span
                      className={`text-[9px] font-medium ${
                        step.reviewResult.pass
                          ? "text-green-600"
                          : "text-red-500"
                      }`}
                    >
                      {step.reviewResult.score}
                    </span>
                  )}
                  {step.decision && (
                    <span className="text-[9px] text-gray-500">
                      {DECISION_TEXT[step.decision] || step.decision}
                    </span>
                  )}
                </div>
              </button>

              {/* Expanded Detail */}
              {expandedStep === step.id && (
                <div className="px-3 pb-2 space-y-1.5 border-t border-gray-100 dark:border-gray-700">
                  <div className="flex items-center gap-4 text-[10px] text-gray-400 pt-1.5">
                    <span>
                      {t("agent.status")}:{" "}
                      {t(STATUS_TEXT[step.status] || step.status)}
                    </span>
                    <span>
                      閲嶈瘯: {step.retryCount}/{step.maxRetries}
                    </span>
                  </div>

                  {step.acceptanceCriteria && (
                    <div className="text-[10px] text-gray-500 bg-gray-50 dark:bg-gray-700/30 p-1.5 rounded">
                      <span className="font-medium">楠屾敹鏍囧噯:</span>{" "}
                      {step.acceptanceCriteria}
                    </div>
                  )}

                  {step.reviewResult && (
                    <div
                      className={`text-[10px] p-1.5 rounded ${
                        step.reviewResult.pass
                          ? "bg-green-50 dark:bg-green-900/20 text-green-700 dark:text-green-300"
                          : "bg-red-50 dark:bg-red-900/20 text-red-700 dark:text-red-300"
                      }`}
                    >
                      <div className="font-medium">
                        {step.reviewResult.pass ? "瀹℃煡閫氳繃" : "瀹℃煡鏈€氳繃"} (
                        {step.reviewResult.score}鍒?
                      </div>
                      {step.reviewResult.summary && (
                        <div className="mt-0.5">
                          {step.reviewResult.summary}
                        </div>
                      )}
                      {step.reviewResult.issues.map((issue, i) => (
                        <div key={i} className="mt-0.5 flex items-start gap-1">
                          <span
                            className={`shrink-0 mt-0.5 w-1 h-1 rounded-full ${
                              issue.severity === "critical"
                                ? "bg-red-500"
                                : issue.severity === "major"
                                  ? "bg-orange-500"
                                  : "bg-yellow-400"
                            }`}
                          />
                          <span>{issue.description}</span>
                        </div>
                      ))}
                    </div>
                  )}

                  {step.error && (
                    <div className="text-[10px] text-red-500 bg-red-50 dark:bg-red-900/20 p-1.5 rounded">
                      {step.error}
                    </div>
                  )}

                  {/* Actions */}
                  <div className="flex gap-1 pt-1">
                    {step.status === "completed" && !step.reviewResult && (
                      <button
                        onClick={() => handleReview(step.id)}
                        disabled={actionLoading === step.id}
                        className="text-[10px] px-2 py-0.5 bg-purple-600 hover:bg-purple-700 text-white rounded"
                      >
                        {actionLoading === step.id ? "..." : "瀹℃煡"}
                      </button>
                    )}
                    {step.reviewResult && !step.decision && (
                      <>
                        <button
                          onClick={() => handleDecide(step.id, "approved")}
                          className="text-[10px] px-2 py-0.5 bg-green-600 hover:bg-green-700 text-white rounded"
                        >
                          {t("common.save")}
                        </button>
                        <button
                          onClick={() => handleDecide(step.id, "retry")}
                          disabled={step.retryCount >= step.maxRetries}
                          className="text-[10px] px-2 py-0.5 bg-blue-600 hover:bg-blue-700 text-white rounded disabled:opacity-50"
                        >
                          {t("common.retry")}
                        </button>
                        <button
                          onClick={() => handleDecide(step.id, "skip")}
                          className="text-[10px] px-2 py-0.5 bg-gray-600 hover:bg-gray-700 text-white rounded"
                        >
                          {t("common.close")}
                        </button>
                      </>
                    )}
                  </div>
                </div>
              )}
            </div>
          ))}
        </div>
      </div>

      {/* 瀹¤鎶ュ憡鎽樿 */}
      {audit && (
        <div className="border-t border-gray-100 dark:border-gray-700 pt-2">
          <span className="text-xs font-medium text-gray-500 dark:text-gray-400 mb-1 block">
            瀹¤鎶ュ憡
          </span>
          <div className="text-[10px] text-gray-500 space-y-0.5 bg-gray-50 dark:bg-gray-700/30 p-1.5 rounded">
            <div>
              {audit.completedSteps}/{audit.totalSteps} 姝ラ瀹屾垚
            </div>
            {audit.failedSteps > 0 && (
              <div className="text-red-500">{audit.failedSteps} 姝ラ澶辫触</div>
            )}
            <div>鎬昏€楁椂: {(audit.totalDurationMs / 1000).toFixed(1)}s</div>
            {audit.totalRetries > 0 && <div>鎬婚噸璇? {audit.totalRetries}</div>}
            <div className="text-gray-600 dark:text-gray-300">
              {audit.summary}
            </div>
          </div>
        </div>
      )}

      {/* 鍒锋柊 */}
      <button
        onClick={load}
        className="w-full text-xs text-blue-600 hover:text-blue-800 dark:text-blue-400 py-0.5"
      >
        {t("common.refresh")}
      </button>
    </div>
  );
}

import { useEffect, useState } from "react";
import { memoryService } from "../../services/memoryService";

interface DreamCycleDetail {
  cycleId: string;
  startedAt: number;
  completedAt: number;
  triggerSource: string;
  status: string;
  snapshotTime: number;
  sessionsScanned: number;
  sessionsProcessed: number;
  knowledgeFilesProcessed: number;
  memoriesCreated: number;
  memoriesRefined: number;
  knowledgeFilesUpdated: number;
  soulUpdated: boolean;
  userProfileUpdated: boolean;
  processedSessionIds: string[];
  processedKnowledgeFiles: string[];
  memoryCount: number;
  insights: string[];
  errors: string[];
  soulConflicts: number;
  userConflicts: number;
}

interface DreamCycleDetailProps {
  cycleId: string;
  isDark: boolean;
  onClose: () => void;
}

function DreamCycleDetail({ cycleId, isDark, onClose }: DreamCycleDetailProps) {
  const [cycle, setCycle] = useState<DreamCycleDetail | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    loadDetail();
  }, [cycleId]);

  const loadDetail = async () => {
    setIsLoading(true);
    setError(null);
    try {
      const result = await memoryService.getDreamCycle(cycleId);
      setCycle(result);
    } catch (e) {
      setError(e instanceof Error ? e.message : "鍔犺浇澶辫触");
    } finally {
      setIsLoading(false);
