};

const DREAM_TYPE_COLORS: Record<string, string> = {
  "dream:started": "text-blue-500",
  "dream:completed": "text-green-500",
  "dream:failed": "text-red-500",
};

const DREAM_TYPE_BG: Record<string, string> = {
