        return "鉁╘

dream:failed":
        return "馃挙";
      default:
        return "馃寵";
    }
  };

  const getStatusIcon = (status: string) => {
    switch (status) {
      case "completed":
        return "鉁匼

p-2 rounded bg-gray-50 dark:bg-gray-700/:
p-2 rounded bg-gray-50 dark:bg-gray-700/50">
                          <div className="text-gray-400 dark:text-gray-500">
