import { useMemo, useEffect, useRef } from "react";
import { useTranslation } from "react-i18next";
import { useChatStore } from "../../stores/chat";
import { useSessionStore } from "../../stores/sessionStore";
import { useBackendStore } from "../../stores/backendStore";
import { useVoiceStore } from "../../stores/voiceStore";
import { useConfigStore } from "../../stores/configStore";
import { useModelSwitchStore } from "../../stores/modelSwitchStore";
import { useChatInspectorStore } from "../../stores/chatInspectorStore";
import { useAutoScroll } from "../../hooks/useAutoScroll";
import { useSessionContextSync } from "../../hooks/useSessionContextSync";
import { voiceService } from "../../services/voiceService";
import { ErrorBoundary } from "../common/ErrorBoundary";
import ChatMessageList from "./ChatMessageList";
import RoundNavigator from "./RoundNavigator";
import StatusFloatBar from "./StatusFloatBar";
import ChatInput from "./ChatInput";
import VoiceSubtitleOverlay from "../VoiceSubtitleOverlay";
import { createLogger } from "@/utils/logger";

const logger = createLogger("components:chatArea");

function ChatArea() {
  const { t } = useTranslation();
  const { messages, error, isStreaming } = useChatStore();
  const { currentSession, createSession } = useSessionStore();
  const backendRunning = useBackendStore((s) => s.status.running);
  const config = useConfigStore((s) => s.config);
  const isDark = config.theme === "dark";

  /** 璇婃柇锛氫細璇濆彉鍖栨椂璁板綍 */
  useEffect(() => {
    console.info("[Diag:chatArea] 浼氳瘽鍙樻洿", {
      sessionId: currentSession?.id,
      title: currentSession?.title,
      msgCount: messages.length,
    });
  }, [currentSession?.id]); // eslint-disable-line react-hooks/exhaustive-deps

  /** 涓婁笅鏂囬潰鏉跨偣鍑绘秷鎭憳瑕?鈫?婊氬姩鍒板搴旀秷鎭?*/
  const highlightedRoundId = useChatInspectorStore((s) => s.highlightedRoundId);
  const setHighlightedRoundId = useChatInspectorStore(
    (s) => s.setHighlightedRoundId,
  );
  useEffect(() => {
    if (!highlightedRoundId) return;
    // 绛夊緟 DOM 娓叉煋瀹屾垚鍚庡啀婊氬姩锛堟秷鎭垪琛ㄥ彲鑳借繕鏈寕杞斤級
    requestAnimationFrame(() => {
      const el = document.querySelector(
        `[data-msg-id="${highlightedRoundId}"]`,
      );
      if (el) {
        el.scrollIntoView({ behavior: "smooth", block: "center" });
        // 楂樹寒闂儊鏁堟灉
        el.classList.add("ring-2", "ring-blue-400", "ring-offset-1");
        setTimeout(() => {
          el.classList.remove("ring-2", "ring-blue-400", "ring-offset-1");
        }, 1500);
      }
      // 閲嶇疆浠ュ厑璁搁噸澶嶇偣鍑诲悓涓€娑堟伅
      setHighlightedRoundId(null);
    });
  }, [highlightedRoundId, setHighlightedRoundId]);
  const { interimText, finalText, audioLevel, subtitleStatus } =
    useVoiceStore();

  /** 妯″潡涓婁笅鏂囧悓姝ワ細淇濆瓨/鎭㈠ ChatSessionContext */
  useSessionContextSync("chat", {
    save: () => ({
      moduleType: "chat" as const,
      modelId: useModelSwitchStore.getState().currentModelId || undefined,
      agentId: undefined,
    }),
    restore: (_ctx) => {
      // model switching is handled by the model switch system
    },
  });

  /** 缁熶竴婊氬姩鐘舵€侊細isUserScrolledUp 鍜?scrollToBottom 鍧囩敱 useAutoScroll 绠＄悊 */
  const {
    containerRef,
    contentRef,
    isUserScrolledUp,
    scrollToBottom,
    distanceFromBottom,
  } = useAutoScroll({
    messageCount: messages.length,
    isStreaming,
    sessionId: currentSession?.id,
  });

  const handleDismissError = () => {
    useChatStore.setState({ error: null });
  };

  const handleCreateSession = () => {
    createSession(t("chat.newSession"));
  };

  /** 鐐瑰嚮鍏ラ棬鎻愮ず鍗＄墖鏃跺彂閫侀璁炬秷鎭?*/
  const handleSendMessage = async (text: string) => {
    let sessionId = currentSession?.id;
    if (!sessionId) {
      const newSession = await createSession(t("chat.newSession"));
      sessionId = newSession.id;
    }
    const { streamMessage } = useChatStore.getState();
    await streamMessage(text, sessionId);
  };

  // ---- 鑷姩 TTS 鎾斁 ----
  const voiceSettings = useVoiceStore((s) => s.settings);
  const playResponse = useVoiceStore((s) => s.playResponse);
  const lastPlayedMsgRef = useRef<string | null>(null);

  useEffect(() => {
    // 娴佸紡浼犺緭缁撴潫锛屼笖鏈€鍚庝竴鏉℃秷鎭槸鍔╂墜娑堟伅 鈫?鑷姩 TTS
    if (
      !isStreaming &&
      messages.length > 0 &&
      voiceSettings?.config?.autoPlayTTS
    ) {
      const lastMsg = messages[messages.length - 1];
      const content =
        typeof lastMsg.content === "string" ? lastMsg.content : "";
      if (
        lastMsg.role === "assistant" &&
        content.trim() &&
        lastMsg.id !== lastPlayedMsgRef.current
      ) {
        lastPlayedMsgRef.current = lastMsg.id;
        voiceService
          .synthesizeSpeech(content)
          .then((audioUrl) => playResponse(audioUrl))
          .catch((err) => logger.warn("鑷姩 TTS 鎾斁澶辫触:", err));
      }
    }
  }, [
    messages.length,
    isStreaming,
    voiceSettings?.config?.autoPlayTTS,
    playResponse,
  ]);

  const displayError =
    error &&
    !backendRunning &&
    (error.includes("fetch") ||
      error.includes("connect") ||
      error.includes("NetworkError") ||
      error.includes("typo") ||
      error.includes("url or port"))
      ? t("chat.backendNotRunning")
      : error;

  // 缂撳瓨 sessionUsage 璁＄畻锛屼粎 messages 鍙樺寲鏃堕噸绠?O(n)
  const sessionUsage = useMemo(() => {
    let inputTokens = 0;
    let outputTokens = 0;
    let totalTokens = 0;
    let estimatedCostUsd = 0;
    let cacheReadTokens = 0;
    let cacheCreationTokens = 0;
    for (const m of messages) {
      if (m.usage) {
        inputTokens += m.usage.inputTokens || 0;
        outputTokens += m.usage.outputTokens || 0;
        totalTokens += m.usage.totalTokens || 0;
        estimatedCostUsd += m.usage.estimatedCostUsd || 0;
        cacheReadTokens += m.usage.cacheReadTokens || 0;
        cacheCreationTokens += m.usage.cacheCreationTokens || 0;
      }
    }
    return totalTokens > 0
      ? {
          inputTokens,
          outputTokens,
          totalTokens,
          estimatedCostUsd,
          cacheReadTokens,
          cacheCreationTokens,
        }
      : undefined;
  }, [messages]);

  return (
    <div className="flex-1 relative bg-gray-50 dark:bg-gray-900 flex flex-col min-h-0">
      <div ref={containerRef} className="flex-1 min-h-0 overflow-y-auto">
        <div ref={contentRef}>
          {/* 閿欒鎻愮ず */}
          {displayError && (
            <div className="m-4 p-4 bg-red-50 dark:bg-red-900/30 border border-red-200 dark:border-red-800 rounded-xl flex items-start gap-3">
              <span className="text-red-500 dark:text-red-400 flex-shrink-0 mt-0.5">
                鈿燶n              </span>
              <div className="flex-1 min-w-0">
                <span className="text-sm text-red-700 dark:text-red-300 block">
                  {displayError}
                </span>
                <div className="flex items-center gap-2 mt-2">
                  <button
                    onClick={() => useBackendStore.getState().checkStatus()}
                    className="text-xs px-2 py-1 rounded bg-red-100 dark:bg-red-800/50 text-red-600 dark:text-red-300 hover:bg-red-200 dark:hover:bg-red-700/50 transition-colors"
                  >
                    馃攧 {t("common.retry")}
                  </button>
                  <button
                    onClick={() => navigator.clipboard.writeText(displayError)}
                    className="text-xs px-2 py-1 rounded bg-red-100 dark:bg-red-800/50 text-red-600 dark:text-red-300 hover:bg-red-200 dark:hover:bg-red-700/50 transition-colors"
                  >
                    馃搵 {t("chat.copyMessage")}
                  </button>
                </div>
              </div>
              <button
                onClick={handleDismissError}
                className="text-red-400 hover:text-red-600 dark:hover:text-red-200 flex-shrink-0"
                title={t("common.close")}
              >
                鉁昞n              </button>
            </div>
          )}

          <ErrorBoundary
            fallback={
              <div className="flex items-center justify-center min-h-[400px] p-8">
                <div className="text-center">
                  <p className="text-gray-500 mb-4">
                    {t("chat.messageListLoadError")}
                  </p>
                  <button
                    onClick={() => window.location.reload()}
                    className="px-4 py-2 text-sm bg-blue-500 text-white rounded hover:bg-blue-600 transition-colors"
                  >
                    {t("chat.refreshPage")}
                  </button>
                </div>
              </div>
            }
          >
            <ChatMessageList
              messages={messages}
              isStreaming={isStreaming}
              sessionUsage={sessionUsage}
              hasSession={!!currentSession}
              sessionTitle={currentSession?.title}
              onCreateSession={handleCreateSession}
              onSendMessage={handleSendMessage}
            />
          </ErrorBoundary>
        </div>
      </div>

      {/* 鍥炲埌搴曢儴鎸夐挳锛氬鐢ㄥ凡鏈夋牱寮忥紝妫€娴?isUserScrolledUp 鍚庢笎鏄撅紝绉诲姩绔伩寮€ MobileBottomNav */}
      {isUserScrolledUp && distanceFromBottom > 200 && (
        <button
          onClick={scrollToBottom}
          aria-label={t("chat.scrollToBottom")}
          role="button"
          className="absolute bottom-28 right-6 z-10 w-10 h-10 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-full shadow-lg flex items-center justify-center hover:bg-gray-50 dark:hover:bg-gray-700 transition-all max-md:bottom-32 opacity-80 hover:opacity-100"
          title={t("chat.scrollToBottom")}
        >
          <svg
            className="w-5 h-5 text-gray-500 dark:text-gray-400"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M19 14l-7 7m0 0l-7-7m7 7V3"
            />
          </svg>
        </button>
      )}

      {/* 杞瀵艰埅鍣?*/}
      <RoundNavigator
        messages={messages}
        isStreaming={isStreaming}
        containerRef={containerRef}
      />

      {/* 閿欒鎻愮ず */}
      {displayError && (
        <div className="absolute bottom-[140px] left-1/2 -translate-x-1/2 w-full max-w-3xl px-4 z-20 pointer-events-none">
          <div className="p-4 bg-red-50 dark:bg-red-900/50 backdrop-blur-xl border border-red-200 dark:border-red-800 rounded-xl flex items-start gap-3 shadow-lg pointer-events-auto">
            <span className="text-red-500 dark:text-red-400 flex-shrink-0 mt-0.5">
              鈿燶n            </span>
            <div className="flex-1 min-w-0">
              <span className="text-sm text-red-700 dark:text-red-300 block">
                {displayError}
              </span>
              <div className="flex items-center gap-2 mt-2">
                <button
                  onClick={() => useBackendStore.getState().checkStatus()}
                  className="text-xs px-2 py-1 rounded bg-red-100 dark:bg-red-800/50 text-red-600 dark:text-red-300 hover:bg-red-200 dark:hover:bg-red-700/50 transition-colors"
                >
                  馃攧 {t("common.retry")}
                </button>
                <button
                  onClick={() => navigator.clipboard.writeText(displayError)}
                  className="text-xs px-2 py-1 rounded bg-red-100 dark:bg-red-800/50 text-red-600 dark:text-red-300 hover:bg-red-200 dark:hover:bg-red-700/50 transition-colors"
                >
                  馃搵 {t("chat.copyMessage")}
                </button>
              </div>
            </div>
            <button
              onClick={handleDismissError}
              className="text-red-400 hover:text-red-600 dark:hover:text-red-200 flex-shrink-0"
              title={t("common.close")}
            >
              鉁昞n            </button>
          </div>
        </div>
      )}

      {/* 搴曢儴鍖哄煙锛欰I 鐘舵€佹爮 + 杈撳叆鍖猴紙flex-col锛孲tatusFloatBar 鑷劧璐寸潃杈撳叆鍖轰笂鏂癸級 */}
      <div className="shrink-0 flex flex-col bg-gray-50 dark:bg-gray-900">
        <StatusFloatBar />

        {/* 璇煶瀛楀箷瑕嗙洊灞?*/}
        <VoiceSubtitleOverlay
          interimText={interimText}
          finalText={finalText}
          audioLevel={audioLevel}
          status={subtitleStatus}
          isDark={isDark}
          position="bottom"
        />

        <ChatInput />
      </div>
    </div>
  );
}

export default ChatArea;

import { useState, useEffect, useRef, useCallback } from "react";
import { useTranslation } from "react-i18next";
import { useSessionStore } from "../../stores/sessionStore";
import { useNavigationStore } from "../../stores/navigationStore";
import { fileService } from "../../services/fileService";
import { knowledgeService } from "../../services/knowledgeService";
import { getOTelTracing } from "../../monitoring/otel/OTelTracing";
import { handleClientError } from "../../utils/handleError";
import type { Session } from "../../types";
import type { FileRegistryRecord } from "../../types/file";
import type { KnowledgeItem } from "../../types/knowledge";

interface GlobalSearchModalProps {
  /** 鏄惁鏄剧ず */
  isOpen: boolean;
  /** 鍏抽棴鍥炶皟 */
  onClose: () => void;
  /** 鏄惁涓烘殫鑹蹭富棰橈紙棰勭暀锛?*/
  isDark?: boolean;
}

/**
 * GlobalSearchModal 鈥?鍏ㄥ眬鎼滅储寮圭獥
 *
 * 鏀寔璺ㄦā鍧楁悳绱細浼氳瘽鏍囬銆佹枃浠跺悕銆佺煡璇嗗簱鏉＄洰銆俓n * 蹇嵎閿細Ctrl+K / Cmd+K 鍞よ捣锛孍scape 鍏抽棴銆俓n * 鎼滅储缁撴灉鍒嗙粍灞曠ず锛岀偣鍑讳細璇?鏂囦欢/鐭ヨ瘑搴撳鑸埌瀵瑰簲椤甸潰銆俓n */
export default function GlobalSearchModal({
  isOpen,
  onClose,
  isDark: _isDark,
}: GlobalSearchModalProps) {
  const { t } = useTranslation();
  const inputRef = useRef<HTMLInputElement>(null);
  const [query, setQuery] = useState("");
  const [sessionResults, setSessionResults] = useState<Session[]>([]);
  const [fileResults, setFileResults] = useState<FileRegistryRecord[]>([]);
  const [knowledgeResults, setKnowledgeResults] = useState<KnowledgeItem[]>([]);
  const [searching, setSearching] = useState(false);
  const sessions = useSessionStore((s) => s.sessions);
  const switchSession = useSessionStore((s) => s.switchSession);
  const setActivePage = useNavigationStore((s) => s.setActivePage);

  /** 鑱氱劍杈撳叆妗?*/
  useEffect(() => {
    if (isOpen) {
      setQuery("");
      setSessionResults([]);
      setFileResults([]);
      setKnowledgeResults([]);
      setTimeout(() => inputRef.current?.focus(), 50);
    }
  }, [isOpen]);

  /** 300ms 闃叉姈鎼滅储 */
  useEffect(() => {
    if (!query.trim()) {
      setSessionResults([]);
      setFileResults([]);
      setKnowledgeResults([]);
      return;
    }

    const timer = setTimeout(async () => {
      setSearching(true);
      const q = query.toLowerCase();

      // 1. 瀹㈡埛绔繃婊や細璇濇爣棰榎n      const matchedSessions = sessions.filter((s) =>
        s.title?.toLowerCase().includes(q),
      );
      setSessionResults(matchedSessions.slice(0, 5));

      // 2. 寮傛鎼滅储鏂囦欢
      try {
        const fileRes = await fileService.searchFiles({ query: q, limit: 5 });
        setFileResults(fileRes.items.slice(0, 5));
      } catch (e) {
        handleClientError(e, {
          module: "components:chat:GlobalSearch",
          action: "searchFiles",
        });
        setFileResults([]);
      }

      // 3. 寮傛鎼滅储鐭ヨ瘑搴揬n      try {
        const kbRes = await knowledgeService.search(q);
        setKnowledgeResults((kbRes as KnowledgeItem[]).slice(0, 5));
      } catch (e) {
        handleClientError(e, {
          module: "components:chat:GlobalSearch",
          action: "searchKnowledge",
        });
        setKnowledgeResults([]);
      }

      setSearching(false);
    }, 300);

    return () => clearTimeout(timer);
  }, [query, sessions]);

  /** 鐐瑰嚮浼氳瘽缁撴灉锛氬垏鎹㈠埌璇ヤ細璇?*/
  const handleSessionClick = useCallback(
    async (session: Session) => {
      const otel = getOTelTracing();
      const span = otel.startSpan("session.switch.globalSearch", {
        sessionId: session.id,
        sessionTitle: session.title,
      });

      try {
        console.info("[SessionSwitch] 鍏ㄥ眬鎼滅储鍒囨崲浼氳瘽", {
          sessionId: session.id,
          sessionTitle: session.title,
          timestamp: Date.now(),
        });

        await switchSession(session.id);

        console.info("[SessionSwitch] 鍏ㄥ眬鎼滅储鍒囨崲浼氳瘽鎴愬姛", {
          sessionId: session.id,
          timestamp: Date.now(),
        });

        span.setAttribute("status", "success");
        setActivePage("chat");
        onClose();
      } catch (error) {
        console.error("[SessionSwitch] 鍏ㄥ眬鎼滅储鍒囨崲浼氳瘽澶辫触", {
          sessionId: session.id,
          sessionTitle: session.title,
          error: String(error),
          stack: (error as Error)?.stack,
          timestamp: Date.now(),
        });

        span.setAttribute("status", "error");
        handleClientError(error, {
          module: "components:chat:GlobalSearchModal",
          action: "handleSessionClick",
          meta: { sessionId: session.id, sessionTitle: session.title },
        });
      } finally {
        otel.endSpan(span);
      }
    },
    [switchSession, setActivePage, onClose],
  );

  /** 鐐瑰嚮鏂囦欢缁撴灉锛氳烦杞枃浠堕〉闈?*/
  const handleFileClick = useCallback(() => {
    setActivePage("files");
    onClose();
  }, [setActivePage, onClose]);

  /** 鐐瑰嚮鐭ヨ瘑搴撶粨鏋滐細璺宠浆鐭ヨ瘑搴撻〉闈?*/
  const handleKnowledgeClick = useCallback(() => {
    setActivePage("knowledge");
    onClose();
  }, [setActivePage, onClose]);

  /** Escape 鍏抽棴 */
  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Escape") {
      onClose();
    }
  };

  if (!isOpen) return null;

  const hasResults =
    sessionResults.length > 0 ||
    fileResults.length > 0 ||
    knowledgeResults.length > 0;
  const noResults = !searching && query && !hasResults;

  return (
    <>
      {/* 閬僵 */}
      <div
        className="fixed inset-0 z-50 bg-black/40 backdrop-blur-sm"
        onClick={onClose}
      />

      {/* 鎼滅储寮圭獥 */}
      <div className="fixed inset-x-0 top-[15%] z-50 mx-auto max-w-xl">
        <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-2xl border border-gray-200 dark:border-gray-700 overflow-hidden">
          {/* 鎼滅储杈撳叆 */}
          <div className="flex items-center gap-3 px-4 py-3 border-b border-gray-200 dark:border-gray-700">
            <svg
              className="w-5 h-5 text-gray-400 shrink-0"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
              strokeWidth={2}
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"
              />
            </svg>
            <input
              ref={inputRef}
              id="global-search-input"
              type="text"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              onKeyDown={handleKeyDown}
              placeholder={t("chat.globalSearchPlaceholder")}
              className="flex-1 text-base bg-transparent border-none outline-none text-gray-800 dark:text-gray-200 placeholder-gray-400"
            />
            {searching && (
              <div className="w-4 h-4 border-2 border-blue-500 border-t-transparent rounded-full animate-spin shrink-0" />
            )}
            <kbd className="hidden sm:inline-flex items-center px-2 py-0.5 text-xs text-gray-400 bg-gray-100 dark:bg-gray-700 rounded font-mono">
              Esc
            </kbd>
          </div>

          {/* 鎼滅储缁撴灉 */}
          <div className="max-h-80 overflow-y-auto">
            {noResults && (
              <div className="px-4 py-8 text-center text-sm text-gray-400 dark:text-gray-500">
                {t("chat.noSearchResults")}
              </div>
            )}

            {/* 浼氳瘽缁撴灉 */}
            {sessionResults.length > 0 && (
              <div>
                <div className="px-4 py-2 text-[10px] font-semibold text-gray-400 dark:text-gray-500 uppercase tracking-wider">
                  {t("chat.sessions")}
                </div>
                {sessionResults.map((session) => (
                  <button
                    key={session.id}
                    onClick={() => handleSessionClick(session)}
                    className="w-full flex items-center gap-3 px-4 py-2.5 text-left hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors"
                  >
                    <span className="text-base shrink-0">馃挰</span>
                    <div className="min-w-0 flex-1">
                      <div className="text-sm text-gray-800 dark:text-gray-200 truncate">
                        {session.title || t("chat.untitledSession")}
                      </div>
                      <div className="text-xs text-gray-400 dark:text-gray-500">
                        {session.messageCount != null
                          ? `${session.messageCount} ${t("chat.messages")}`
                          : ""}
                      </div>
                    </div>
                  </button>
                ))}
              </div>
            )}

            {/* 鏂囦欢缁撴灉 */}
            {fileResults.length > 0 && (
              <div>
                <div className="px-4 py-2 text-[10px] font-semibold text-gray-400 dark:text-gray-500 uppercase tracking-wider border-t border-gray-100 dark:border-gray-700">
                  {t("chat.files")}
                </div>
                {fileResults.map((file, idx) => (
                  <button
                    key={file.fileId || idx}
                    onClick={handleFileClick}
                    className="w-full flex items-center gap-3 px-4 py-2.5 text-left hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors"
                  >
                    <span className="text-base shrink-0">馃搫</span>
                    <div className="min-w-0 flex-1">
                      <div className="text-sm text-gray-800 dark:text-gray-200 truncate">
                        {file.originalName}
                      </div>
                      <div className="text-xs text-gray-400 dark:text-gray-500 truncate font-mono">
                        {file.savedPath}
                      </div>
                    </div>
                  </button>
                ))}
              </div>
            )}

            {/* 鐭ヨ瘑搴撶粨鏋?*/}
            {knowledgeResults.length > 0 && (
              <div>
                <div className="px-4 py-2 text-[10px] font-semibold text-gray-400 dark:text-gray-500 uppercase tracking-wider border-t border-gray-100 dark:border-gray-700">
                  {t("chat.knowledge")}
                </div>
                {knowledgeResults.map((item, idx) => (
                  <button
                    key={item.id || idx}
                    onClick={handleKnowledgeClick}
                    className="w-full flex items-center gap-3 px-4 py-2.5 text-left hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors"
                  >
                    <span className="text-base shrink-0">馃摎</span>
                    <div className="min-w-0 flex-1">
                      <div className="text-sm text-gray-800 dark:text-gray-200 truncate">
                        {item.title || item.content?.slice(0, 60)}
                      </div>
                      <div className="text-xs text-gray-400 dark:text-gray-500 truncate">
                        {item.tags?.length ? item.tags.join(", ") : ""}
                      </div>
                    </div>
                  </button>
                ))}
              </div>
            )}
          </div>

          {/* 搴曢儴鎻愮ず */}
          <div className="px-4 py-2 border-t border-gray-100 dark:border-gray-700 flex items-center gap-4 text-[10px] text-gray-400">
            <span>
              <kbd className="px-1.5 py-0.5 bg-gray-100 dark:bg-gray-700 rounded font-mono text-[10px]">
                鈫戔啌
              </kbd>{" "}
              {t("chat.navigateHint")}
            </span>
            <span>
              <kbd className="px-1.5 py-0.5 bg-gray-100 dark:bg-gray-700 rounded font-mono text-[10px]">
                Enter
              </kbd>{" "}
              {t("chat.openHint")}
            </span>
            <span>
              <kbd className="px-1.5 py-0.5 bg-gray-100 dark:bg-gray-700 rounded font-mono text-[10px]">
                Esc
              </kbd>{" "}
              {t("chat.closeHint")}
            </span>
          </div>
        </div>
      </div>
    </>
  );
}

