/**
 * ReEntryBanner 鈥?鍥炲垏鎽樿妯箙
 *
 * 褰撶敤鎴峰垏鍥炴煇涓細璇濅笖绂诲紑瓒呰繃 30 绉掓椂锛屽湪杈撳叆妗嗕笂鏂规樉绀虹寮€鏈熼棿鐨勫彉鍖栨憳瑕併€俓n */

import { useCallback, useEffect, useState } from "react";
import { useTranslation } from "react-i18next";
import { useChatStore } from "../../stores/chat";

interface ReEntryBannerProps {
  sessionId: string;
  sessionTitle: string;
  leaveTimestamp: number;
  /** 鍒囪蛋鍓嶆渶鍚庝竴鏉℃秷鎭殑 ID */
  lastMessageId: string | null;
  onScrollToLatest: () => void;
  onDismiss: () => void;
}

export default function ReEntryBanner({
  sessionTitle,
  leaveTimestamp,
  lastMessageId,
  onScrollToLatest,
  onDismiss,
}: ReEntryBannerProps) {
  const { t } = useTranslation();
  const messages = useChatStore((s) => s.messages);
  const [visible, setVisible] = useState(true);

  const awayMs = Date.now() - leaveTimestamp;
  const awayMinutes = Math.round(awayMs / 60000);
  // 浠?lastMessageId 璁＄畻鏂版秷鎭暟閲忥紙閬垮厤鍒犻櫎瀵艰嚧璁℃暟涓嶅噯锛塡n  const newMessageCount = lastMessageId
    ? (() => {
        const idx = messages.findIndex((m) => m.id === lastMessageId);
        return idx >= 0 ? Math.max(0, messages.length - idx - 1) : 0;
      })()
    : Math.max(0, messages.length);

  const handleDismiss = useCallback(() => {
    setVisible(false);
    onDismiss();
  }, [onDismiss]);

  // 30绉掑唴鏃犳搷浣滆嚜鍔ㄦ秷澶盶n  useEffect(() => {
    if (!visible) return;
    const timer = setTimeout(() => setVisible(false), 30000);
    return () => clearTimeout(timer);
  }, [visible]);

  if (!visible) return null;

  return (
    <div className="mx-3 mb-2 px-4 py-3 bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded-xl animate-message-enter">
      <div className="flex items-start gap-3">
        <span className="text-lg mt-0.5 shrink-0" aria-hidden="true">
          馃搵
        </span>
        <div className="min-w-0 flex-1">
          <p className="text-sm font-medium text-blue-700 dark:text-blue-300">
            {t("chat.reentryBanner", { title: sessionTitle })}
          </p>
          <p className="text-xs text-blue-600 dark:text-blue-400 mt-1">
            {t("chat.reentryAway", { minutes: awayMinutes })}
            {newMessageCount > 0 &&
              ` 路 ${t("chat.reentryNewMessages", { count: newMessageCount })}`}
          </p>
          <div className="flex items-center gap-3 mt-2">
            {newMessageCount > 0 && (
              <button
                onClick={onScrollToLatest}
                className="text-xs font-medium text-blue-600 dark:text-blue-400 hover:text-blue-800 dark:hover:text-blue-200 flex items-center gap-1"
              >
                <svg
                  className="w-3 h-3"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                  strokeWidth={2}
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    d="M19 14l-7 7m0 0l-7-7m7 7V3"
                  />
                </svg>
                {t("chat.reentryScrollToLatest")}
              </button>
            )}
            <button
              onClick={handleDismiss}
              className="text-xs text-blue-500 dark:text-blue-400 hover:text-blue-700 dark:hover:text-blue-200"
            >
              {t("common.close")}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

