import { useMemo } from "react";

interface SlashCommand {
  key: string;
  label: string;
  description: string;
  action: () => void;
}

interface SlashCommandMenuProps {
  /** 褰撳墠杈撳叆鍊?*/
  input: string;
  /** 鏄惁鏄剧ず鍛戒护鑿滃崟 */
  show: boolean;
  /** 褰撳墠閫変腑椤圭储寮?*/
  commandIndex: number;
  /** 閫変腑鍛戒护 */
  onSelect: (cmd: SlashCommand) => void;
  /** 鎮仠鍛戒护 */
  onHover: (index: number) => void;
}

/**
 * SlashCommandMenu 鈥?蹇嵎鍛戒护鑿滃崟缁勪欢
 *
 * 鍦ㄨ緭鍏ユ涓婃柟灞曠ず /command 鍖归厤鍒楄〃锛屾敮鎸侀敭鐩樹笂涓嬮€夋嫨銆俓n * 涓嶅寘鍚懡浠ら厤缃湰韬紝鍛戒护鐢辩埗缁勪欢閫氳繃 onSelect 鍥炶皟娑堣垂銆俓n */
export default function SlashCommandMenu({
  input,
  show,
  commandIndex,
  onSelect,
  onHover,
}: SlashCommandMenuProps) {
  const filteredCommands = useMemo(() => {
    if (!input.startsWith("/") || input.includes(" ")) return [];
    return SLASH_COMMANDS.filter((cmd) =>
      cmd.key.startsWith(input.toLowerCase()),
    );
  }, [input]);

  if (!show || filteredCommands.length === 0) return null;

  return (
    <div className="absolute bottom-full left-0 right-0 mb-2 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-600 rounded-xl shadow-xl overflow-hidden">
      <div className="px-3 py-2 text-xs text-gray-500 dark:text-gray-400 border-b border-gray-100 dark:border-gray-700">
        蹇嵎鍛戒护
      </div>
      {filteredCommands.map((cmd, idx) => (
        <button
          key={cmd.key}
          onClick={() => onSelect(cmd)}
          onMouseEnter={() => onHover(idx)}
          className={`w-full flex items-center gap-3 px-4 py-2.5 text-left text-sm transition-colors ${
            idx === commandIndex
              ? "bg-blue-50 dark:bg-blue-900/30"
              : "hover:bg-gray-50 dark:hover:bg-gray-700/50"
          }`}
        >
          <span className="font-mono text-blue-600 dark:text-blue-400 font-medium">
            {cmd.label}
          </span>
          <span className="text-gray-500 dark:text-gray-400">
            {cmd.description}
          </span>
        </button>
      ))}
    </div>
  );
}

// ============================================================
// 蹇嵎鍛戒护閰嶇疆锛堥泦涓鐞嗭紝鍙墿灞曚负鍚庣閰嶇疆锛塡n// ============================================================

export const SLASH_COMMANDS: SlashCommand[] = [
  {
    key: "/dashboard",
    label: "/dashboard",
    description: "鎵撳紑浠〃鐩榎

source:
/agent",
    label: "/agent",
    description: "鎵撳紑 Agent 浠诲姟",
    action: () => {},
  },
  {
    key: "/clear",
    label: "/clear",
    description: "娓呯┖鑱婂ぉ娑堟伅",
    action: () => {},
  },
  {
    key: "/help",
    label: "/help",
    description: "鏄剧ず鍙敤鍛戒护",
    action: () => {},
  },
];

export type { SlashCommand };

