import { useState, useMemo, useEffect, useRef } from "react";
import { useChatStore } from "../../stores/chat";
import type { TaskCardData } from "../../types";

const PHASE_LABELS: Record<string, string> = {
  analyzing: "姝ｅ湪鍒嗘瀽浠ｇ爜...",
  designing: "姝ｅ湪璁捐鏂规...",
  implementing: "姝ｅ湪瀹炴柦鍙樻洿...",
  verifying: "姝ｅ湪楠岃瘉缁撴灉...",
  presenting: "姝ｅ湪鐢熸垚鎶ュ憡...",
};

const STATUS_ICONS: Record<string, string> = {
  pending: "鈼孿

source:
text-gray-400",
  in_progress: "text-blue-500",
  completed: "text-green-500",
  failed: "text-red-500",
  blocked: "text-yellow-500",
};

/**
 * 浠庢秷鎭腑鎻愬彇鏈€鏂扮殑 TaskCard锛堥亶鍘嗘墍鏈夋秷鎭殑 blocks 瀵绘壘鏈€鍚庝竴涓?todo 鍧楋級
 */
function findLatestTaskCard(messages: any[]): TaskCardData | null {
  for (let i = messages.length - 1; i >= 0; i--) {
    const blocks = messages[i].blocks;
    if (!blocks) continue;
    for (let j = blocks.length - 1; j >= 0; j--) {
      if (blocks[j].taskCard) {
        return blocks[j].taskCard as TaskCardData;
      }
    }
  }
  return null;
}

/**
 * 浠诲姟杩涘害鏄剧ず缁勪欢
 */
function TaskProgress({ data }: { data: TaskCardData }) {
  const total = data.tasks.length;
  const completed = data.tasks.filter((t) => t.status === "completed").length;
  const failed = data.tasks.filter((t) => t.status === "failed").length;

  if (total === 0) return null;

  return (
    <span className="text-xs text-gray-500 dark:text-gray-400 ml-2">
      {completed}/{total} 浠诲姟宸插畬鎴怽n      {failed > 0 && <span className="text-red-500 ml-1">| {failed} 澶辫触</span>}
    </span>
  );
}

/**
 * 浠诲姟杩涘害 Mini 闈㈡澘锛堢偣鍑诲睍寮€锛塡n */
function TaskMiniPanel({
  data,
  onClose,
}: {
  data: TaskCardData;
  onClose: () => void;
}) {
  return (
    <div
      className="absolute bottom-full left-0 right-0 px-3 pb-1"
      onClick={(e) => e.stopPropagation()}
    >
      <div className="max-w-3xl mx-auto">
        <div className="bg-white/80 dark:bg-gray-800/80 backdrop-blur-xl border border-gray-200/50 dark:border-gray-700/50 rounded-xl shadow-md p-3 space-y-1.5">
          <div className="flex items-center justify-between">
            <span className="text-sm font-medium text-gray-700 dark:text-gray-200">
              {data.title}
            </span>
            <button
              onClick={onClose}
              className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-200 transition-colors"
              aria-label="鏀惰捣"
            >
              <svg
                className="w-4 h-4"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M5 15l7-7 7 7"
                />
              </svg>
            </button>
          </div>

          {data.tasks.map((task) => (
            <div key={task.id} className="flex items-center gap-2 text-xs">
              <span
                className={`${STATUS_COLORS[task.status] || "text-gray-400"} font-mono w-4 text-center`}
              >
                {STATUS_ICONS[task.status] || "?"}
              </span>
              <span className="text-gray-600 dark:text-gray-300 flex-1 truncate">
                {task.name}
              </span>
              {task.status === "failed" && task.result && (
                <span
                  className="text-red-400 truncate max-w-[120px]"
                  title={task.result}
                >
                  {task.result}
                </span>
              )}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

/**
 * 杩愯鐘舵€佹诞鍔ㄩ潰鏉匡紙澧炲己鐗堬級
 *
 * 娴簬 ChatArea 娑堟伅鍒楄〃涓?ChatInput 杈撳叆鍖轰箣闂达紝灞曠ず褰撳墠浼氳瘽鐨勮繍琛岀姸鎬併€俓n * - 杩愯涓細缁胯壊鑴夊啿鐐?+ 鐘舵€佹弿杩版枃鏈?+ 浠诲姟杩涘害
 * - 绌洪棽锛氫笉娓叉煋
 * - 鎵ц闃舵锛氳鍙?executionPhase锛屼紭鍏堟樉绀洪樁娈垫枃鏈琝n * - 浠诲姟杩涘害锛氫粠鏈€鍚庝竴鏉?assistant 娑堟伅鐨?todo 鍧椾腑鎻愬彇锛屾樉绀哄畬鎴愭暟/鎬绘暟
 * - 鐐瑰嚮浠诲姟杩涘害鍙睍寮€ Mini 闈㈡澘鏌ョ湅鍏蜂綋浠诲姟鐘舵€乗n */
export default function StatusFloatBar() {
  const isSending = useChatStore((s) => s.isSending);
  const isStreaming = useChatStore((s) => s.isStreaming);
  const isUploading = useChatStore((s) => s.isUploading);
  const streamingStatus = useChatStore((s) => s.streamingStatus);
  const executionPhase = useChatStore((s) => s.executionPhase);
  const messages = useChatStore((s) => s.messages);
  const stopMessage = useChatStore((s) => s.stopMessage);

  const [showTaskPanel, setShowTaskPanel] = useState(false);

  const isActive = isSending || isStreaming || isUploading;
  const [fadingOut, setFadingOut] = useState(false);
  const fadeTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // isActive 浠?true 鈫?false 鏃惰Е鍙戞笎闅愬姩鐢伙紝2绉掑悗鐪熸闅愯棌
  useEffect(() => {
    if (!isActive && !fadingOut) {
      setFadingOut(true);
      fadeTimerRef.current = setTimeout(() => {
        setFadingOut(false);
      }, 2000);
    } else if (isActive && fadingOut) {
      // 娲昏穬鐘舵€佹仮澶嶆椂绔嬪嵆鍙栨秷娓愰殣
      setFadingOut(false);
      if (fadeTimerRef.current) {
        clearTimeout(fadeTimerRef.current);
        fadeTimerRef.current = null;
      }
    }
    return () => {
      if (fadeTimerRef.current) {
        clearTimeout(fadeTimerRef.current);
        fadeTimerRef.current = null;
      }
    };
  }, [isActive, fadingOut]);

  // 浠庢秷鎭腑鎻愬彇鏈€鏂扮殑 TaskCard锛堝繀椤绘斁鍦ㄦ墍鏈?return 涔嬪墠锛岄伒瀹?Hooks 瑙勫垯锛塡n  const taskCard = useMemo(() => findLatestTaskCard(messages), [messages]);

  if (!isActive && !fadingOut) return null;

  /**
   * 鏍规嵁褰撳墠鐘舵€佺敓鎴愭樉绀烘枃鏈琝n   * 浼樺厛绾э細executionPhase > streamingStatus > 榛樿鐘舵€乗n   */
  const getStatusText = (): string => {
    if (isUploading) return "姝ｅ湪涓婁紶鏂囦欢...";
    if (isSending && !isStreaming) return "姝ｅ湪鍙戦€?..";
    if (executionPhase?.phase) {
      const phaseLabel =
        PHASE_LABELS[executionPhase.phase] || executionPhase.phase;
      return executionPhase.description
        ? `${phaseLabel} ${executionPhase.description}`
        : phaseLabel;
    }
    if (streamingStatus) return streamingStatus;
    return "AI 姝ｅ湪鍥炲...";
  };

  return (
    <div className="w-full relative">
      <div
        className={`w-full px-3 transition-opacity duration-1000 ease-in-out ${fadingOut ? "opacity-0" : "opacity-100"}`}
        onClick={() => setShowTaskPanel(!showTaskPanel)}
      >
        <div className="max-w-3xl mx-auto">
          <div className="flex items-center gap-2.5 px-4 py-2.5 bg-white dark:bg-gray-800 border border-gray-200/50 dark:border-gray-700/50 rounded-xl shadow-md cursor-pointer hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors">
            {/* 鐘舵€佹寚绀虹偣锛氱豢鑹茶剦鍐?= 杩愯涓?*/}
            <span className="relative flex h-2.5 w-2.5">
              <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-green-400 opacity-75" />
              <span className="relative inline-flex rounded-full h-2.5 w-2.5 bg-green-500" />
            </span>

            {/* 鐘舵€佹枃鏈?+ 浠诲姟杩涘害 */}
            <div className="flex items-center flex-1 min-w-0">
              <span className="text-sm text-gray-600 dark:text-gray-300 truncate">
                {getStatusText()}
              </span>
              {taskCard && <TaskProgress data={taskCard} />}
            </div>

            {/* 浠诲姟杩涘害灞曞紑鎸囩ず */}
            {taskCard && (
              <svg
                className={`w-3.5 h-3.5 text-gray-400 transition-transform duration-200 ${
                  showTaskPanel ? "rotate-180" : ""
                }`}
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M19 9l-7 7-7-7"
                />
              </svg>
            )}

            {/* 鍋滄鎸夐挳锛氫粎娴佸紡杈撳嚭涓樉绀?*/}
            {isStreaming && (
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  stopMessage();
                }}
                aria-label="鍋滄 AI 鍥炲"
                className="flex items-center gap-1 px-2.5 py-1 text-xs text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-md transition-colors"
                title="鍋滄 AI 鍥炲"
              >
                <svg
                  className="w-3.5 h-3.5"
                  fill="currentColor"
                  viewBox="0 0 24 24"
                >
                  <rect x="4" y="4" width="16" height="16" rx="2" />
                </svg>
                <span>鍋滄</span>
              </button>
            )}
          </div>
        </div>
      </div>

      {/* 灞曞紑鐨?Mini 闈㈡澘 */}
      {showTaskPanel && taskCard && (
        <TaskMiniPanel
          data={taskCard}
          onClose={() => setShowTaskPanel(false)}
        />
      )}
    </div>
  );
}

