/**
 * KnowledgeEditor 鈥?鐭ヨ瘑鏂囨。缂栬緫鍣?(Phase 2 W5: 鐘舵€佸唴閮ㄧ鐞?+ Tab鍒囨崲淇濇姢)
 *
 * W5: 缂栬緫鍣ㄧ姸鎬佸畬鍏ㄤ笅娌夊埌鍐呴儴锛岀埗缁勪欢鍙紶 file + onSave 鍥炶皟銆俓n * 缂栬緫鍣?unmount 鍓嶅皢鑽夌瀛樺埌 store锛岄噸鏂版寕杞芥椂鎭㈠銆俓n */
import { useRef, useCallback, useEffect, useReducer } from "react";
import EditorToolbar from "./EditorToolbar";
import MarkdownRenderer from "../ChatArea/MarkdownRenderer";
import { useKnowledgeStore } from "../../stores/knowledgeStore";
import { knowledgeService } from "../../services/knowledgeService";
import type { KnowledgeFile } from "../../types";

type ViewMode = "edit" | "preview" | "split";

interface KnowledgeEditorProps {
  file: KnowledgeFile;
  isDark: boolean;
  onSave: (title: string, content: string) => Promise<void>;
  onCancel: () => void;
  /** U5: 浠庢ā鏉挎柊寤烘枃妗ｅ悗鐨勫洖璋?*/
  onFileCreated?: (doc: KnowledgeFile) => void;
}

// 鈹€鈹€ Editor reducer (鏇夸唬鍘熸潵鐨勫 useState) 鈹€鈹€
interface EditorState {
  title: string;
  content: string;
  viewMode: ViewMode;
  saving: boolean;
  autoSaved: boolean;
}

type EditorAction =
  | { type: "SET_TITLE"; title: string }
  | { type: "SET_CONTENT"; content: string }
  | { type: "SET_VIEW_MODE"; mode: ViewMode }
  | { type: "SET_SAVING"; saving: boolean }
  | { type: "SET_AUTO_SAVED"; autoSaved: boolean }
  | { type: "RESET"; title: string; content: string };

function editorReducer(state: EditorState, action: EditorAction): EditorState {
  switch (action.type) {
    case "SET_TITLE":
      return { ...state, title: action.title };
    case "SET_CONTENT":
      return { ...state, content: action.content };
    case "SET_VIEW_MODE":
      return { ...state, viewMode: action.mode };
    case "SET_SAVING":
      return { ...state, saving: action.saving };
    case "SET_AUTO_SAVED":
      return { ...state, autoSaved: action.autoSaved };
    case "RESET":
      return { ...state, title: action.title, content: action.content };
    default:
      return state;
  }
}

const templates: { name: string; content: string }[] = [
  {
    name: "浼氳绾",
    content: `# 浼氳绾\n\n**鏃ユ湡**: ${new Date().toISOString().slice(0, 10)}\n**鍙備笌鑰?*: \n**涓婚**: \n\n## 璁▼\n\n1. \n\n## 鍐宠\n\n- \n\n## 寰呭姙\n\n- [ ] \n`,
  },
  {
    name: "鎶€鏈瑪璁癨

# 鎶€鏈瑪璁癨
\n## 鑳屾櫙\n\n\n## 鏂规\n\n```\n\n```\n\n## 缁撹\n\n",
  },
  { name: "FAQ", content: "# FAQ\n\n## Q: \n\nA: \n\n## Q: \n\nA: \n" },
  {
    name: "鍛ㄦ姤",
    content: `# 鍛ㄦ姤 (${new Date().toISOString().slice(0, 10)})\n\n## 鏈懆瀹屾垚\n\n- \n\n## 閬囧埌鐨勯棶棰榎
\n- \n\n## 涓嬪懆璁″垝\n\n- \n`,
  },
];

function KnowledgeEditor({
  file,
  isDark,
  onSave,
  onCancel,
  onFileCreated,
}: KnowledgeEditorProps) {
  // W5: 浠?store 璇诲彇鑽夌
  const editorDraft = useKnowledgeStore((s) => s.editorDraft);
  const setEditorDraft = useKnowledgeStore((s) => s.setEditorDraft);

  const [state, dispatch] = useReducer(editorReducer, {
    title: editorDraft?.title ?? file.title ?? "",
    content: editorDraft?.content ?? file.content ?? "",
    viewMode: "split",
    saving: false,
    autoSaved: false,
  });

  const { title, content, viewMode, saving, autoSaved } = state;
  const textareaRef = useRef<HTMLTextAreaElement | null>(null);
  const autoSaveTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  // W5: 鍚屾 file prop 鍙樺寲锛堝垏鎹㈡枃妗ｆ椂锛塡n  useEffect(() => {
    dispatch({
      type: "RESET",
      title: file.title ?? "",
      content: file.content ?? "",
    });
    setEditorDraft(null);
  }, [file.id]);

  // W5: 500ms auto-save 鑽夌鍒?store
  useEffect(() => {
    if (!content.trim()) return;
    if (autoSaveTimer.current) clearTimeout(autoSaveTimer.current);
    autoSaveTimer.current = setTimeout(() => {
      setEditorDraft({ title, content });
      dispatch({ type: "SET_AUTO_SAVED", autoSaved: true });
      setTimeout(
        () => dispatch({ type: "SET_AUTO_SAVED", autoSaved: false }),
        2000,
      );
    }, 500);
    return () => {
      if (autoSaveTimer.current) clearTimeout(autoSaveTimer.current);
    };
  }, [title, content, setEditorDraft]);

  // W5: unmount 鍓嶆樉寮忎繚瀛樿崏绋縗n  useEffect(() => {
    return () => {
      const isDirty =
        title !== (file.title ?? "") || content !== (file.content ?? "");
      if (isDirty && content.trim()) {
        setEditorDraft({ title, content });
      }
    };
  }, [title, content, file.title, file.content, setEditorDraft]);

  const inputBg = isDark
    ? "bg-gray-700 border-gray-600 text-white placeholder-gray-400"
    : "bg-white border-gray-300 text-gray-900 placeholder-gray-400";
  const textPrimary = isDark ? "text-gray-100" : "text-gray-900";
  const textSecondary = isDark ? "text-gray-400" : "text-gray-500";
  const borderColor = isDark ? "border-gray-700" : "border-gray-200";

  const handleSave = useCallback(async () => {
    if (!title.trim() || !content.trim() || saving) return;
    dispatch({ type: "SET_SAVING", saving: true });
    try {
      await onSave(title.trim(), content.trim());
      // 淇濆瓨鎴愬姛鍚庢竻闄よ崏绋縗n      setEditorDraft(null);
    } finally {
      dispatch({ type: "SET_SAVING", saving: false });
    }
  }, [title, content, saving, onSave, setEditorDraft]);

  const viewButtons: { mode: ViewMode; icon: string; label: string }[] = [
    { mode: "edit", icon: "鉁忥笍", label: "缂栬緫" },
    { mode: "preview", icon: "馃憗", label: "棰勮" },
    { mode: "split", icon: "鈫擻

鍒嗗睆" },
  ];

  const editorSection = (
    <div className="flex-1 flex flex-col min-h-0">
      <EditorToolbar
        textareaRef={textareaRef}
        onContentChange={(c) => dispatch({ type: "SET_CONTENT", content: c })}
        isDark={isDark}
      />
      <textarea
        ref={textareaRef}
        value={content}
        onChange={(e) =>
          dispatch({ type: "SET_CONTENT", content: e.target.value })
        }
        placeholder="鏂囨。鍐呭锛堟敮鎸?Markdown 鏍煎紡锛塡

source:
bg-gray-900" : "bg-white"}`}
    >
      {content.trim() ? (
        <div className="prose prose-sm max-w-none dark:prose-invert">
          <MarkdownRenderer content={content} />
        </div>
      ) : (
        <p className={`text-sm ${textSecondary} italic`}>锛堟棤鍐呭锛?/p>
      )}
    </div>
  );

  return (
    <div className="flex-1 flex flex-col overflow-hidden">
      {/* 椤堕儴鏍?*/}
      <div
        className={`flex items-center justify-between px-4 py-2 border-b ${borderColor} flex-shrink-0`}
      >
        <input
          type="text"
          value={title}
          onChange={(e) =>
            dispatch({ type: "SET_TITLE", title: e.target.value })
          }
          placeholder="鏂囨。鏍囬"
          className={`flex-1 px-2 py-1 text-base font-semibold ${textPrimary} bg-transparent border-0 focus:outline-none focus:ring-0 placeholder-gray-400`}
        />
        <div className="flex items-center gap-2 ml-4">
          {/* 瑙嗗浘妯″紡 */}
          <div
            className={`flex rounded-md border ${borderColor} overflow-hidden`}
          >
            {viewButtons.map((vb) => (
              <button
                key={vb.mode}
                onClick={() =>
                  dispatch({ type: "SET_VIEW_MODE", mode: vb.mode })
                }
                className={`px-2.5 py-1 text-xs transition-colors ${
                  viewMode === vb.mode
                    ? "bg-blue-600 text-white"
                    : `${textSecondary} hover:bg-gray-100 dark:hover:bg-gray-700`
                }`}
                title={vb.label}
              >
                {vb.icon}
              </button>
            ))}
          </div>
          {/* U5: 妯℃澘 鈫?鏂板缓鏂囨。 */}
          <select
            value=""
            onChange={async (e) => {
              const tpl = templates.find((t) => t.name === e.target.value);
              if (!tpl) return;
              (e.target as HTMLSelectElement).value = "";
              try {
                const title = `${tpl.name} - ${new Date().toLocaleDateString("zh-CN")}`;
                const doc = await knowledgeService.create({
                  title,
                  content: tpl.content,
                  tags: [tpl.name],
                });
                const newFile: KnowledgeFile = {
                  id: doc.id,
                  title: doc.title,
                  content: tpl.content,
                  tags: [tpl.name],
                  category: "",
                  docPath: doc.id,
                  size: 0,
                  source: "manual" as const,
                  created_at: doc.created_at,
                  updated_at: doc.updated_at,
                  base: file.base || "",
                };
                onFileCreated?.(newFile);
              } catch {
                // 鍒涘缓澶辫触闈欓粯蹇界暐
              }
            }}
            className={`text-xs px-2 py-1 rounded border ${isDark ? "bg-gray-700 border-gray-600 text-gray-300" : "bg-white border-gray-300 text-gray-600"} focus:outline-none`}
          >
            <option value="">妯℃澘</option>
            {templates.map((t) => (
              <option key={t.name} value={t.name}>
                {t.name}
              </option>
            ))}
          </select>
          <button
            onClick={handleSave}
            disabled={saving || !title.trim() || !content.trim()}
            className="px-4 py-1.5 text-sm bg-blue-600 hover:bg-blue-700 disabled:opacity-50 text-white rounded-md"
          >
            {saving ? "淇濆瓨涓?.." : "淇濆瓨"}
          </button>
          {autoSaved && (
            <span className="text-[10px] text-green-500 dark:text-green-400 ml-1">
              宸蹭繚瀛榎n            </span>
          )}
          <button
            onClick={onCancel}
            className={`px-3 py-1.5 text-sm border ${borderColor} rounded-md ${textSecondary} hover:bg-gray-100 dark:hover:bg-gray-700`}
          >
            鍙栨秷
          </button>
        </div>
      </div>

      {/* 缂栬緫鍣ㄤ富浣?*/}
      <div className="flex-1 flex min-h-0">
        {viewMode === "edit" && editorSection}
        {viewMode === "preview" && previewSection}
        {viewMode === "split" && (
          <>
            <div className="flex-1 flex flex-col min-h-0 min-w-0 border-r ${borderColor}">
              {editorSection}
            </div>
            <div className="flex-1 flex flex-col min-h-0 min-w-0">
              {previewSection}
            </div>
          </>
        )}
      </div>
    </div>
  );
}

export default KnowledgeEditor;

