import { useState, useEffect, useCallback } from "react";
import { knowledgeService } from "../../services/knowledgeService";
import { formatFileSize, formatDate } from "./shared/utils";

interface RawFileInfo {
  fileName: string;
  ext: string;
  size: number;
  modifiedAt: number;
  createdAt: number;
  category: string | null;
  source: string | null;
}

interface PendingCompilePanelProps {
  isDark: boolean;
  onCompileComplete?: () => void;
}

function PendingCompilePanel({
  isDark,
  onCompileComplete,
}: PendingCompilePanelProps) {
  const [rawFiles, setRawFiles] = useState<RawFileInfo[]>([]);
  const [loading, setLoading] = useState(false);
  const [compiling, setCompiling] = useState(false);
  const [compileProgress, setCompileProgress] = useState(0);
  const [compileResult, setCompileResult] = useState<{
    message: string;
    hasError: boolean;
    failedDocs?: string[];
  } | null>(null);
  const [expanded, setExpanded] = useState(false);

  const bgClass = isDark ? "bg-gray-800" : "bg-gray-50";
  const textPrimary = isDark ? "text-gray-100" : "text-gray-900";
  const textSecondary = isDark ? "text-gray-400" : "text-gray-500";
  const textMuted = isDark ? "text-gray-500" : "text-gray-400";
  const borderColor = isDark ? "border-gray-700" : "border-gray-200";
  const badgeBg = isDark ? "bg-gray-700" : "bg-gray-100";

  const loadRawFiles = useCallback(async () => {
    setLoading(true);
    try {
      const result = await knowledgeService.getRawFiles();
      setRawFiles(result.files);
      setExpanded(result.files.length > 0);
    } catch {
      setRawFiles([]);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadRawFiles();
  }, [loadRawFiles]);

  async function handleCompileAll() {
    setCompiling(true);
    setCompileProgress(0);
    setCompileResult(null);

    // W9: 杞鐪熷疄缂栬瘧杩涘害锛堟瘡 500ms 鏌ヨ涓€娆★級
    const progressTimer = setInterval(async () => {
      try {
        const status = await knowledgeService.getCompileStatus();
        if (status.total > 0) {
          setCompileProgress(Math.round((status.current / status.total) * 100));
        }
      } catch {
        // 杞澶辫触闈欓粯蹇界暐
      }
    }, 500);

    try {
      const result = await knowledgeService.triggerCompile(false);
      clearInterval(progressTimer);
      setCompileProgress(100);
      const hasError = (result.errors?.length ?? 0) > 0;
      const msg = `缂栬瘧瀹屾垚: ${result.compiled} 涓垚鍔? ${result.skipped} 涓烦杩?{hasError ? `, ${result.errors?.length} 涓敊璇痐 : ""}`;
      setCompileResult({
        message: msg,
        hasError,
        failedDocs: (result as any).failedDocs || [],
      });
      await loadRawFiles();
      onCompileComplete?.();
    } catch (err) {
      clearInterval(progressTimer);
      setCompileResult({
        message:
          "缂栬瘧澶辫触: " + (err instanceof Error ? err.message : "鏈煡閿欒"),
        hasError: true,
      });
    } finally {
      setCompiling(false);
    }
  }

  if (!expanded && rawFiles.length === 0) return null;

  return (
    <div
      className={`mx-4 mb-2 rounded-lg border ${borderColor} ${bgClass} overflow-hidden`}
    >
      <div
        className={`flex items-center justify-between px-3 py-2 cursor-pointer select-none ${
          rawFiles.length > 0 ? "hover:opacity-80" : ""
        }`}
        onClick={() => setExpanded(!expanded)}
      >
        <div className="flex items-center gap-2">
          <svg
            className="w-4 h-4 text-amber-500"
            fill="none"
            viewBox="0 0 24 24"
            stroke="currentColor"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4"
            />
          </svg>
          <span className={`text-xs font-medium ${textPrimary}`}>
            寰呭鐞嗘枃浠禱n          </span>
          {rawFiles.length > 0 && (
            <span
              className={`text-[10px] px-1.5 py-0.5 rounded-full ${badgeBg} ${textSecondary}`}
            >
              {rawFiles.length}
            </span>
          )}
        </div>
        <svg
          className={`w-3.5 h-3.5 ${textSecondary} transition-transform ${expanded ? "rotate-180" : ""}`}
          fill="none"
          viewBox="0 0 24 24"
          stroke="currentColor"
        >
          <path
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeWidth={2}
            d="M19 9l-7 7-7-7"
          />
        </svg>
      </div>

      {expanded && (
        <div className="px-3 pb-2">
          {loading ? (
            <div className={`text-center py-3 ${textMuted}`}>
              <span className="text-xs">鍔犺浇涓?..</span>
            </div>
          ) : rawFiles.length === 0 ? (
            <div className={`text-center py-3 ${textMuted}`}>
              <p className="text-xs">鏆傛棤寰呭鐞嗙殑鏂囦欢</p>
              <p className="text-[10px] mt-1 opacity-60">
                涓婁紶 .md .txt .pdf 绛夋枃浠跺悗灏嗚嚜鍔ㄨ繘鍏ョ紪璇戦槦鍒梊n              </p>
            </div>
          ) : (
            <div className="space-y-1 max-h-40 overflow-y-auto">
              {rawFiles.map((file) => (
                <div
                  key={file.fileName}
                  className={`flex items-center justify-between px-2 py-1.5 rounded text-xs ${
                    isDark ? "hover:bg-gray-700" : "hover:bg-gray-100"
                  }`}
                >
                  <div className="flex items-center gap-2 min-w-0">
                    <span className={`font-mono ${textPrimary} truncate`}>
                      {file.fileName}
                    </span>
                    {file.category && (
                      <span className={`px-1 rounded ${badgeBg} ${textMuted}`}>
                        {file.category}
                      </span>
                    )}
                  </div>
                  <div className="flex items-center gap-2 shrink-0 ml-2">
                    <span className={textMuted}>
                      {formatFileSize(file.size)}
                    </span>
                    <span className={textMuted}>
                      {formatDate(file.modifiedAt)}
                    </span>
                  </div>
                </div>
              ))}
            </div>
          )}

          {rawFiles.length > 0 && (
            <div className="flex items-center gap-2 mt-2 pt-2 border-t ${borderColor}">
              <button
                onClick={handleCompileAll}
                disabled={compiling}
                className="flex items-center gap-1 px-3 py-1 text-xs bg-amber-500 hover:bg-amber-600 disabled:opacity-50 text-white rounded-md transition-colors"
              >
                {compiling ? (
                  <>
                    <span className="animate-spin w-3 h-3 border-2 border-white border-t-transparent rounded-full inline-block" />
                    缂栬瘧涓?..
                  </>
                ) : (
                  <>
                    <svg
                      className="w-3 h-3"
                      fill="none"
                      viewBox="0 0 24 24"
                      stroke="currentColor"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2}
                        d="M13 10V3L4 14h7v7l9-11h-7z"
                      />
                    </svg>
                    鍏ㄩ儴缂栬瘧
                  </>
                )}
              </button>
              <button
                onClick={loadRawFiles}
                disabled={loading}
                className={`text-xs ${textSecondary} hover:${isDark ? "text-gray-300" : "text-gray-700"} transition-colors`}
              >
                鍒锋柊
              </button>
            </div>
          )}

          {/* 缂栬瘧杩涘害鏉?*/}
          {compiling && (
            <div className="mt-2">
              <div className="flex justify-between text-[10px] text-gray-400 mb-0.5">
                <span>缂栬瘧涓?..</span>
                <span>{Math.round(compileProgress)}%</span>
              </div>
              <div className="w-full h-1.5 bg-gray-200 dark:bg-gray-700 rounded-full overflow-hidden">
                <div
                  className="h-full bg-blue-500 rounded-full transition-all duration-300"
                  style={{ width: `${compileProgress}%` }}
                />
              </div>
            </div>
          )}

          {compileResult && (
            <div
              className={`mt-2 text-xs px-2 py-1 rounded ${
                compileResult.hasError
                  ? "bg-red-100 dark:bg-red-900/30 text-red-600 dark:text-red-400"
                  : "bg-green-100 dark:bg-green-900/30 text-green-600 dark:text-green-400"
              }`}
            >
              {compileResult.message}
            </div>
          )}
          {compileResult?.failedDocs && compileResult.failedDocs.length > 0 && (
            <div className="mt-1 text-xs text-red-500 dark:text-red-400">
              澶辫触鐨勬枃浠? {compileResult.failedDocs.join(", ")}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

export default PendingCompilePanel;

/**
 * VersionHistory 鈥?鐭ヨ瘑鏂囨。鐗堟湰鍘嗗彶闈㈡澘
 *
 * P0-4: 鏌ョ湅蹇収鍒楄〃銆佸姣旂増鏈樊寮傘€佹仮澶嶅巻鍙茬増鏈琝n */
import { useState, useEffect } from "react";
import { knowledgeService } from "../../services/knowledgeService";

interface VersionHistoryProps {
  isDark: boolean;
  title: string;
  currentContent: string;
  onRestored?: () => void;
}

function VersionHistory({
  isDark,
  title,
  currentContent,
  onRestored,
}: VersionHistoryProps) {
  const [open, setOpen] = useState(false);
  const [snapshots, setSnapshots] = useState<string[]>([]);
  const [loading, setLoading] = useState(false);
  const [selectedSnapshot, setSelectedSnapshot] = useState<string | null>(null);
  const [snapshotContent, setSnapshotContent] = useState<string | null>(null);
  const [restoring, setRestoring] = useState(false);
  const [viewMode, setViewMode] = useState<"side" | "inline">("side");

  const bgClass = isDark ? "bg-gray-800" : "bg-white";
  const borderColor = isDark ? "border-gray-700" : "border-gray-200";
  const textPrimary = isDark ? "text-gray-100" : "text-gray-900";
  const textSecondary = isDark ? "text-gray-400" : "text-gray-500";
  const btnClass = isDark
    ? "bg-gray-700 text-gray-300 hover:bg-gray-600"
    : "bg-gray-100 text-gray-600 hover:bg-gray-200";

  useEffect(() => {
    if (open && snapshots.length === 0) {
      loadSnapshots();
    }
  }, [open]);

  async function loadSnapshots() {
    setLoading(true);
    try {
      const list = await knowledgeService.listSnapshots(title);
      setSnapshots(list);
    } catch {
      setSnapshots([]);
    } finally {
      setLoading(false);
    }
  }

  async function handleSelectSnapshot(name: string) {
    setSelectedSnapshot(name);
    try {
      const content = await knowledgeService.getSnapshotContent(title, name);
      setSnapshotContent(content);
    } catch {
      setSnapshotContent(null);
    }
  }

  async function handleRestore() {
    if (!selectedSnapshot || !confirm("纭畾鎭㈠鍒版鐗堟湰锛熷綋鍓嶅唴瀹瑰皢琚鐩栥€俓

source:
鎭㈠澶辫触");
    }
  }

  function parseSnapshotTime(name: string): string {
    // snapshot_2026-07-12T05-30-00-000Z.md
    const m = name.match(/snapshot_(.+)\.md$/);
    if (!m) return name;
    return m[1]
      .replace(/T/, " ")
      .replace(/-/g, (c, i) => (i >= 10 ? ":" : c))
      .replace("Z", "");
  }

  if (!open) {
    return (
      <button
        onClick={() => setOpen(true)}
        className={`text-xs ${btnClass} px-2 py-1 rounded transition-colors`}
        title="鏌ョ湅鍘嗗彶鐗堟湰"
      >
        鍘嗗彶鐗堟湰
      </button>
    );
  }

  return (
    <div
      className={`mt-4 rounded-lg border ${borderColor} ${bgClass} overflow-hidden`}
    >
      {/* 澶撮儴 */}
      <div
        className={`px-3 py-2 border-b ${borderColor} flex items-center justify-between`}
      >
        <span className={`text-sm font-medium ${textPrimary}`}>
          鍘嗗彶鐗堟湰 ({snapshots.length})
        </span>
        <div className="flex items-center gap-2">
          <select
            value={viewMode}
            onChange={(e) => setViewMode(e.target.value as "side" | "inline")}
            className={`text-xs px-1.5 py-0.5 rounded border ${isDark ? "bg-gray-700 border-gray-600 text-gray-300" : "bg-white border-gray-300"}`}
          >
            <option value="side">骞舵帓瀵规瘮</option>
            <option value="inline">琛屽唴瀵规瘮</option>
          </select>
          <button
            onClick={() => {
              setOpen(false);
              setSelectedSnapshot(null);
            }}
            className={`text-xs ${btnClass} px-2 py-0.5 rounded`}
          >
            鍏抽棴
          </button>
        </div>
      </div>

      {/* 蹇収鍒楄〃 */}
      <div className="flex max-h-80">
        <div
          className={`w-56 border-r ${borderColor} overflow-y-auto flex-shrink-0`}
        >
          {loading && (
            <div className={`px-3 py-2 text-xs ${textSecondary}`}>
              鍔犺浇涓?..
            </div>
          )}
          {!loading && snapshots.length === 0 && (
            <div className={`px-3 py-2 text-xs ${textSecondary}`}>
              鏆傛棤鍘嗗彶鐗堟湰
            </div>
          )}
          {snapshots.map((name) => (
            <button
              key={name}
              onClick={() => handleSelectSnapshot(name)}
              className={`w-full text-left px-3 py-1.5 text-xs transition-colors ${
                selectedSnapshot === name
                  ? "bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400"
                  : `${textSecondary} hover:bg-gray-50 dark:hover:bg-gray-700/50`
              }`}
            >
              {parseSnapshotTime(name)}
            </button>
          ))}
        </div>

        {/* 瀵规瘮鍖哄煙 */}
        <div className="flex-1 overflow-auto" style={{ maxHeight: "20rem" }}>
          {viewMode === "side" ? (
            <div
              className="grid grid-cols-2 divide-x"
              style={{ minHeight: "10rem" }}
            >
              <div className="p-2">
                <div className="text-xs font-semibold text-green-600 dark:text-green-400 mb-1">
                  鏃х増鏈琝n                </div>
                <pre className="text-xs text-gray-500 dark:text-gray-400 whitespace-pre-wrap font-mono leading-relaxed">
                  {snapshotContent || "閫夋嫨宸︿晶鐗堟湰鏌ョ湅"}
                </pre>
              </div>
              <div className="p-2">
                <div className="text-xs font-semibold text-blue-600 dark:text-blue-400 mb-1">
                  褰撳墠鐗堟湰
                </div>
                <pre className="text-xs text-gray-700 dark:text-gray-300 whitespace-pre-wrap font-mono leading-relaxed">
                  {currentContent}
                </pre>
              </div>
            </div>
          ) : (
            <div className="p-2">
              <div className="text-xs font-semibold text-green-600 dark:text-green-400 mb-1">
                鏃х増鏈琝n              </div>
              <pre className="text-xs text-gray-500 dark:text-gray-400 whitespace-pre-wrap font-mono leading-relaxed mb-4">
                {snapshotContent || "閫夋嫨宸︿晶鐗堟湰鏌ョ湅"}
              </pre>
              <div className="text-xs font-semibold text-blue-600 dark:text-blue-400 mb-1">
                褰撳墠鐗堟湰
              </div>
              <pre className="text-xs text-gray-700 dark:text-gray-300 whitespace-pre-wrap font-mono leading-relaxed">
                {currentContent}
              </pre>
            </div>
          )}
        </div>
      </div>

      {/* 搴曢儴鎿嶄綔 */}
      {selectedSnapshot && (
        <div
          className={`px-3 py-2 border-t ${borderColor} flex items-center justify-end gap-2`}
        >
          <button
            onClick={handleRestore}
            disabled={restoring}
            className="px-3 py-1 text-xs bg-amber-600 hover:bg-amber-700 disabled:opacity-50 text-white rounded"
          >
            {restoring ? "鎭㈠涓?.." : "鎭㈠鍒版鐗堟湰"}
          </button>
        </div>
      )}
    </div>
  );
}

export default VersionHistory;

