import { useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import { useTranslation } from "react-i18next";
import { useNavigationStore } from "../../stores/navigationStore";
import { useConfigStore } from "../../stores/configStore";
import { useNotificationStore } from "../../stores/notificationStore";
import {
  HomeIcon,
  ChatIcon,
  KnowledgeIcon,
  ImageIcon,
  TranslateIcon,
  ModelIcon,
  SkillIcon,
  FileIcon,
  McpIcon,
  ChannelIcon,
  ThemeIcon,
  SettingsIcon,
  CouncilIcon,
  OfficeIcon,
  CalendarIcon,
  BuddyIcon,
  BellIcon,
} from "../../assets/icons";

interface MenuItem {
  id: string;
  label: string;
  icon: React.ComponentType<{ className?: string; size?: number }>;
  path?: string;
  action?: () => void;
  badge?: number;
}

const HIGH_FREQUENCY_ITEMS: MenuItem[] = [
  { id: "home", label: "棣栭〉", icon: HomeIcon, path: "/" },
  { id: "chat", label: "鑱婂ぉ", icon: ChatIcon, path: "/chat" },
  { id: "calendar", label: "鏃ュ巻", icon: CalendarIcon, path: "/calendar" },
  { id: "office", label: "鍔炲叕", icon: OfficeIcon, path: "/office" },
  { id: "media", label: "濯掍綋", icon: ImageIcon, path: "/media" },
  { id: "translate", label: "缈昏瘧", icon: TranslateIcon, path: "/translate" },
  { id: "knowledge", label: "鐭ヨ瘑搴揬

/knowledge" },
];

/** 鑿滃崟椤?id 鍒?i18n key 鐨勬槧灏?*/
const MENU_LABEL_KEYS: Record<string, string> = {
  home: "nav.home",
  chat: "nav.chat",
  calendar: "nav.calendar",
  office: "office.title",
  translate: "translate.title",
  knowledge: "knowledge.title",
  models: "model.title",
  skills: "skill.title",
  files: "nav.files",
  mcp: "mcp.title",
  channels: "channels.title",
  "council-roles": "agent.title",
  theme: "settings.theme",
  settings: "nav.settings",
};

/** 绠＄悊鎶樺彔锛氭ā鍨?鎶€鑳?MCP/棰戦亾/鏂囦欢 */
const MANAGEMENT_ITEMS: MenuItem[] = [
  { id: "models", label: "妯″瀷", icon: ModelIcon, path: "/models" },
  { id: "skills", label: "鎶€鑳絓

/agent/roles",
  },
];

const SYSTEM_ITEMS: MenuItem[] = [
  { id: "liri", label: "Liri", icon: BuddyIcon, path: "/liri" },
  { id: "loops", label: "Loops", icon: BuddyIcon, path: "/loops" },
  { id: "theme", label: "涓婚", icon: ThemeIcon },
  { id: "settings", label: "璁剧疆", icon: SettingsIcon, path: "/settings" },
];

function MenuButton({
  item,
  isActive,
  onNavigate,
}: {
  item: MenuItem;
  isActive: boolean;
  onNavigate?: () => void;
}) {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const setActivePage = useNavigationStore((s) => s.setActivePage);
  const config = useConfigStore((s) => s.config);
  const setConfig = useConfigStore((s) => s.setConfig);
  const isDark = config.theme === "dark";

  const labelText = t(MENU_LABEL_KEYS[item.id] || item.label);

  const handleClick = () => {
    const actualPath = item.path;
    if (actualPath) {
      if (actualPath === "/") {
        setActivePage("home");
      } else {
        const pageId = actualPath.replace("/", "") || "chat";
        setActivePage(pageId as any);
      }
      navigate(actualPath);
      onNavigate?.();
    } else if (item.id === "theme") {
      const newTheme = isDark ? "light" : "dark";
      setConfig("theme", newTheme);
    }
  };

  if (item.id === "theme") {
    return (
      <button
        onClick={handleClick}
        className={`flex flex-col items-center justify-center py-2 px-2 rounded transition-colors h-14 w-full flex-shrink-0 ${
          isDark
            ? "text-yellow-400 hover:bg-gray-700"
            : "text-gray-600 hover:bg-gray-200 dark:text-gray-300 dark:hover:bg-gray-700"
        }`}
        title={isDark ? t("sidebar.switchToLight") : t("sidebar.switchToDark")}
      >
        <ThemeIcon size={20} />
        <span className="text-xs mt-1 truncate w-full text-center h-4 flex items-center justify-center">
          {isDark ? t("settings.light") : t("settings.dark")}
        </span>
      </button>
    );
  }

  const IconComponent = item.icon;

  return (
    <button
      onClick={handleClick}
      className={`relative flex flex-col items-center justify-center py-2 px-2 rounded transition-colors h-14 w-full flex-shrink-0 ${
        isActive
          ? "bg-blue-600 text-white"
          : "text-gray-600 hover:bg-gray-200 dark:text-gray-300 dark:hover:bg-gray-700 dark:hover:text-white"
      }`}
      title={labelText}
    >
      <div className="relative">
        <IconComponent size={20} />
        {item.badge != null && item.badge > 0 && (
          <span className="absolute -top-1.5 -right-3 min-w-[18px] h-[18px] flex items-center justify-center rounded-full bg-red-500 text-white text-[10px] font-bold px-1 leading-none">
            {item.badge > 99 ? "99+" : item.badge}
          </span>
        )}
      </div>
      <span className="text-xs mt-1 truncate w-full text-center h-4 flex items-center justify-center">
        {labelText}
      </span>
    </button>
  );
}

/**
 * 宸ヤ綔绌洪棿閫夋嫨鍣細渚ф爮椤堕儴鍥炬爣鎸夐挳 + 涓嬫媺鑿滃崟
 * 宸茶縼绉昏嚦 Header 鍙充笂瑙掔殑 WorkspaceSwitcher 缁勪欢銆俓n * 淇濈暀绌哄３閬垮厤 Sidebar 甯冨眬鍙樺寲銆俓n */

function Sidebar({ onNavigate }: { onNavigate?: () => void }) {
  const { t } = useTranslation();
  const location = useLocation();
  const activeRoute = location.pathname.replace("/", "") || "home";
  const [showManagement, setShowManagement] = useState(false);

  /** 鍒ゆ柇褰撳墠璺敱鏄惁鍖归厤鑿滃崟椤?*/
  const isActive = (item: MenuItem) => {
    const normalizedPath = (item.path || "").replace("/", "") || "home";
    return (
      activeRoute === normalizedPath ||
      activeRoute.startsWith(normalizedPath + "/")
    );
  };

  return (
    <aside className="w-20 bg-gray-100 dark:bg-gray-900 flex flex-col h-full">
      {/* 楂橀瀵艰埅 */}
      <div className="flex-1 overflow-y-auto p-1">
        <div className="space-y-0.5">
          {HIGH_FREQUENCY_ITEMS.map((item) => (
            <MenuButton
              key={item.id}
              item={item}
              isActive={isActive(item)}
              onNavigate={onNavigate}
            />
          ))}
        </div>
      </div>

      {/* 绠＄悊鎶樺彔鎸夐挳 */}
      <div className="p-1 border-t border-gray-300 dark:border-gray-700">
        <button
          onClick={() => setShowManagement(!showManagement)}
          className={`flex flex-col items-center justify-center py-2 px-2 rounded transition-colors h-14 w-full flex-shrink-0 ${
            showManagement || MANAGEMENT_ITEMS.some((m) => isActive(m))
              ? "bg-blue-600 text-white"
              : "text-gray-600 hover:bg-gray-200 dark:text-gray-300 dark:hover:bg-gray-700"
          }`}
          title={t("sidebar.manage")}
        >
          <SettingsIcon size={20} />
          <span className="text-xs mt-1 truncate w-full text-center h-4 flex items-center justify-center">
            {t("sidebar.manage")}
          </span>
        </button>

        {/* 灞曞紑鐨勭鐞嗛」 */}
        {showManagement && (
          <div className="mt-0.5 space-y-0.5">
            {MANAGEMENT_ITEMS.map((item) => (
              <MenuButton
                key={item.id}
                item={item}
                isActive={isActive(item)}
                onNavigate={onNavigate}
              />
            ))}
          </div>
        )}
      </div>

      {/* 绯荤粺瀵艰埅 */}
      <div className="p-1 border-t border-gray-300 dark:border-gray-700">
        <div className="space-y-0.5">
          {SYSTEM_ITEMS.map((item) => (
            <MenuButton
              key={item.id}
              item={item}
              isActive={isActive(item)}
              onNavigate={onNavigate}
            />
          ))}
        </div>
      </div>
    </aside>
  );
}

/** 绉诲姩绔細搴曢儴瀵艰埅鏍?*/
function MobileBottomNav() {
  const { t } = useTranslation();
  const location = useLocation();
  const navigate = useNavigate();
  const activeRoute = location.pathname.replace("/", "") || "home";
  const openPanel = useNotificationStore((s) => s.openPanel);
  const unreadTotal = useNotificationStore((s) => s.counts.total);

  const items: MenuItem[] = [
    { id: "home", label: t("nav.home"), icon: HomeIcon, path: "/" },
    { id: "chat", label: t("nav.chat"), icon: ChatIcon, path: "/chat" },
    {
      id: "notifications",
      label: "閫氱煡",
      icon: BellIcon,
    },
    {
      id: "settings",
      label: t("nav.settings"),
      icon: SettingsIcon,
      path: "/settings",
    },
  ];

  return (
    <nav className="lg:hidden fixed bottom-0 left-0 right-0 bg-white dark:bg-gray-900 border-t border-gray-200 dark:border-gray-700 flex justify-around py-1 z-50 safe-area-bottom">
      {items.map((item) => {
        const isActive =
          activeRoute === (item.path?.replace("/", "") || "home");
        const IconComponent = item.icon;
        return (
          <button
            key={item.id}
            onClick={() => {
              if (item.id === "notifications") {
                openPanel();
              } else {
                navigate(item.path!);
              }
            }}
            className={`relative flex flex-col items-center px-2 py-1 min-w-0 ${
              isActive ? "text-blue-600" : "text-gray-500 dark:text-gray-400"
            }`}
          >
            <IconComponent size={18} />
            {item.id === "notifications" && unreadTotal > 0 && (
              <span className="absolute -top-0.5 right-1 min-w-[16px] h-[16px] flex items-center justify-center rounded-full bg-red-500 text-white text-[9px] font-bold px-1 leading-none">
                {unreadTotal > 99 ? "99+" : unreadTotal}
              </span>
            )}
            <span className="text-xs mt-0.5">{item.label}</span>
          </button>
        );
      })}
    </nav>
  );
}

export default Sidebar;
export { MobileBottomNav };

import { useEffect, useRef } from "react";
import { Terminal } from "@xterm/xterm";
import { FitAddon } from "@xterm/addon-fit";
import { WebLinksAddon } from "@xterm/addon-web-links";
import "@xterm/xterm/css/xterm.css";

interface XTermPanelProps {
  onReady?: (terminal: Terminal) => void;
}

export default function XTermPanel({ onReady }: XTermPanelProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const terminalRef = useRef<Terminal | null>(null);

  useEffect(() => {
    if (!containerRef.current) return;

    const term = new Terminal({
      cursorBlink: true,
      fontSize: 13,
      fontFamily: "'Cascadia Code', 'Fira Code', 'JetBrains Mono', monospace",
      theme: {
        background: "#1a1a2e",
        foreground: "#e6e6e6",
        cursor: "#6c5ce7",
        selectionBackground: "#6c5ce744",
      },
      allowProposedApi: true,
    });

    const fitAddon = new FitAddon();
    const webLinksAddon = new WebLinksAddon();

    term.loadAddon(fitAddon);
    term.loadAddon(webLinksAddon);
    term.open(containerRef.current);

    // 鑷€傚簲
    const handleResize = () => fitAddon.fit();
    handleResize();
    window.addEventListener("resize", handleResize);

    term.writeln("Liri 缁堢宸插氨缁?(xterm.js)");
    term.write("$ ");

    let cmdBuffer = "";
    let cmdHistory: string[] = [];

    term.onData((data) => {
      const code = data.charCodeAt(0);

      if (code === 13) {
        // Enter
        term.write("\r\n");
        const cmd = cmdBuffer.trim();
        if (cmd) {
          cmdHistory.push(cmd);
          term.writeln(`鎵ц: ${cmd}`);
          // 閫氳繃鍥炶皟鍙戦€佸懡浠n          onReady?.(term);
        }
        cmdBuffer = "";
        term.write("$ ");
      } else if (code === 127) {
        // Backspace
        if (cmdBuffer.length > 0) {
          cmdBuffer = cmdBuffer.slice(0, -1);
          term.write("\b \b");
        }
      } else if (code === 27) {
        // ESC 搴忓垪锛堜笂涓嬬澶寸瓑锛塡n        // 绠€鍖栧鐞嗭紝涓嶆嫤鎴鏉?ANSI
      } else if (data.length === 1 && data >= " ") {
        cmdBuffer += data;
        term.write(data);
      }
    });

    terminalRef.current = term;

    return () => {
      window.removeEventListener("resize", handleResize);
      term.dispose();
    };
  }, []);

  return (
    <div
      ref={containerRef}
      className="h-full w-full rounded border border-gray-700"
    />
  );
}

import { useTranslation } from "react-i18next";
import {
  useState,
  useRef,
  useEffect,
  useCallback,
  forwardRef,
  useImperativeHandle,
} from "react";
import { createLogger } from "@/utils/logger";

const logger = createLogger("components:voiceInput");
import { useVoiceStore } from "../stores/voiceStore";
import { voiceService } from "../services/voiceService";
import { handleClientError } from "../utils/handleError";

// 娴忚鍣?SpeechRecognition API 绫诲瀷澹版槑锛堥潪鏍囧噯 API锛屾墜鍔ㄨˉ鍏咃級
declare class SpeechRecognition extends EventTarget {
  continuous: boolean;
  interimResults: boolean;
  lang: string;
  start(): void;
  stop(): void;
  abort(): void;
  onresult: ((event: SpeechRecognitionEvent) => void) | null;
  onerror: ((event: SpeechRecognitionErrorEvent) => void) | null;
  onend: (() => void) | null;
}

interface SpeechRecognitionEvent extends Event {
  resultIndex: number;
  results: SpeechRecognitionResultList;
}

interface SpeechRecognitionResultList {
  length: number;
  [index: number]: SpeechRecognitionResult;
}

interface SpeechRecognitionResult {
  isFinal: boolean;
  length: number;
  [index: number]: SpeechRecognitionAlternative;
}

interface SpeechRecognitionAlternative {
  transcript: string;
  confidence: number;
}

interface SpeechRecognitionErrorEvent extends Event {
  error: string;
  message: string;
}

interface VoiceInputButtonProps {
  isDark: boolean;
  /** 杞綍瀹屾垚鍚庡洖璋冿紝灏嗘枃瀛楀～鍏ヨ亰澶╄緭鍏ユ */
  onTranscribed?: (text: string) => void;
  /** 娴忚鍣?SpeechRecognition 璇█锛堥粯璁や腑鏂囷級 */
  subtitleLang?: string;
  /** 杞綍瀹屾垚鍚庤嚜鍔ㄨЕ鍙戞彁浜わ紙涓?true 鏃堕渶鍚屾椂鎻愪緵 onShouldSubmit锛?*/
  autoSubmit?: boolean;
  /** 鑷姩鎻愪氦鍥炶皟锛屼粎 autoSubmit=true 鏃舵湁鏁?*/
  onShouldSubmit?: (text: string) => void;
}

/** VoiceInputButton 鏆撮湶鐨勫彞鏌勶紝鐢ㄤ簬澶栭儴瑙﹀彂褰曢煶/鍋滄 */
export interface VoiceInputHandle {
  start(): void;
  stop(): void;
}

/**
 * 璇煶杈撳叆鎸夐挳
 *
 * 鎸変綇褰曢煶 鈫?鏉炬墜鍚庤嚜鍔ㄨ皟鐢ㄥ悗绔?STT 杞枃瀛?鈫?閫氳繃 onTranscribed 鍥炶皟浼犲嚭銆俓n * 褰曢煶鍓嶄細妫€娴嬮害鍏嬮鍋ュ悍鐘舵€侊紙闈欓煶/浣庨煶閲?鏃犺澶?鏉冮檺鎷掔粷锛夈€俓n * 闆嗘垚闊抽鐢靛钩鍙鍖栵紝鏀寔 pulsating 鍔ㄧ敾鍙嶉銆俓n */
const VoiceInputButton = forwardRef<VoiceInputHandle, VoiceInputButtonProps>(
  (
    {
      isDark,
      onTranscribed,
      subtitleLang = "zh-CN",
      autoSubmit = false,
      onShouldSubmit,
    },
    ref,
  ) => {
    const { t } = useTranslation();
    const {
      isRecording,
      isProcessing,
      audioLevel,
      startRecording,
      stopRecording,
    } = useVoiceStore();

    const mediaRecorderRef = useRef<MediaRecorder | null>(null);
    const audioChunksRef = useRef<Blob[]>([]);
    const streamRef = useRef<MediaStream | null>(null);
    const analyzerRef = useRef<AudioContext | null>(null);
    const animationRef = useRef<number | null>(null);
    const recognitionRef = useRef<InstanceType<
      typeof SpeechRecognition
    > | null>(null);
    const [micWarning, setMicWarning] = useState<string | null>(null);

    /** 娴忚鍣?SpeechRecognition 鏄惁鍙敤 */
    const hasSpeechRecognition =
      typeof window !== "undefined" &&
      ("SpeechRecognition" in window || "webkitSpeechRecognition" in window);

    useEffect(() => {
      return () => {
        stopAudioAnalysis();
        cleanupStream();
        stopSubtitleRecognition();
      };
    }, []);

    /** 娓呯悊闊抽娴?*/
    const cleanupStream = () => {
      if (streamRef.current) {
        streamRef.current.getTracks().forEach((t) => t.stop());
        streamRef.current = null;
      }
    };

    /** 鍋滄闊抽鐢靛钩鍒嗘瀽 */
    const stopAudioAnalysis = () => {
      if (animationRef.current) {
        cancelAnimationFrame(animationRef.current);
        animationRef.current = null;
      }
      if (analyzerRef.current) {
        analyzerRef.current.close();
        analyzerRef.current = null;
      }
    };

    /**
     * 鍚姩闊抽鐢靛钩鍒嗘瀽
     * 鐢?AnalyserNode 閲囬泦棰戝煙鏁版嵁锛屽綊涓€鍖栧悗鍐欏叆 store
     */
    const startAudioAnalysis = (stream: MediaStream) => {
      const audioContext = new AudioContext();
      analyzerRef.current = audioContext;
      const source = audioContext.createMediaStreamSource(stream);
      const analyzer = audioContext.createAnalyser();
      analyzer.fftSize = 256;
      source.connect(analyzer);

      const dataArray = new Uint8Array(analyzer.frequencyBinCount);

      const updateLevel = () => {
        analyzer.getByteFrequencyData(dataArray);
        const average = dataArray.reduce((a, b) => a + b) / dataArray.length;
        const normalizedLevel = Math.min(100, (average / 128) * 100);
        useVoiceStore.setState({ audioLevel: normalizedLevel });
        animationRef.current = requestAnimationFrame(updateLevel);
      };

      updateLevel();
    };

    /**
     * 鍚姩娴忚鍣ㄥ師鐢?SpeechRecognition 鑾峰彇瀹炴椂瀛楀箷
     * 浠呭湪褰曢煶鏃跺悓姝ュ惎鐢紝鏉炬墜鍚庤嚜鍔ㄥ仠姝n     */
    const startSubtitleRecognition = useCallback(() => {
      if (!hasSpeechRecognition) return;

      // 娓呴櫎鏃х殑瀛楀箷鐘舵€乗n      useVoiceStore.setState({
        interimText: "",
        finalText: "",
        subtitleStatus: "listening",
      });

      try {
        const SpeechRecognitionAPI =
          (window as any).SpeechRecognition ||
          (window as any).webkitSpeechRecognition;
        const recognition = new SpeechRecognitionAPI() as SpeechRecognition;
        recognition.continuous = true;
        recognition.interimResults = true;
        recognition.lang = subtitleLang;

        recognition.onresult = (event: SpeechRecognitionEvent) => {
          let interim = "";
          let final = "";

          for (let i = event.resultIndex; i < event.results.length; i++) {
            const result = event.results[i];
            if (result.isFinal) {
              final += result[0].transcript;
            } else {
              interim += result[0].transcript;
            }
          }

          useVoiceStore.setState({
            interimText: interim,
            finalText: final || useVoiceStore.getState().finalText,
            subtitleStatus: "listening",
          });
        };

        recognition.onerror = () => {
          // SpeechRecognition 鍑洪敊鏃朵笉涓柇褰曢煶锛岄潤榛橀檷绾n          useVoiceStore.setState({
            subtitleStatus: "idle",
          });
        };

        recognition.onend = () => {
          // 鑷姩閲嶈繛锛氬鏋滆繕鍦ㄥ綍闊充腑锛岄噸鍚瘑鍒玕n          if (useVoiceStore.getState().isRecording) {
            try {
              recognition.start();
            } catch (e) {
              handleClientError(e, {
                module: "components:voice:VoiceInput",
                action: "recognitionRestart",
              });
              // 蹇界暐閲嶅惎澶辫触
            }
          }
        };

        recognition.start();
        recognitionRef.current = recognition;
      } catch (e) {
        handleClientError(e, {
          module: "components:voice:VoiceInput",
          action: "startSubtitleRecognition",
        });
        // SpeechRecognition 鍒濆鍖栧け璐ワ紝闈欓粯闄嶇骇
        useVoiceStore.setState({ subtitleStatus: "idle" });
      }
    }, [hasSpeechRecognition, subtitleLang]);

    /**
     * 鍋滄娴忚鍣?SpeechRecognition
     */
    const stopSubtitleRecognition = useCallback(() => {
      if (recognitionRef.current) {
        try {
          recognitionRef.current.stop();
        } catch (e) {
          handleClientError(e, {
            module: "components:voice:VoiceInput",
            action: "stopSubtitleRecognition",
          });
          // 蹇界暐鍋滄閿欒
        }
        recognitionRef.current = null;
      }
    }, []);

    /** 鏆撮湶缁欑埗缁勪欢鐨勫綍闊虫帶鍒舵柟娉?*/
    useImperativeHandle(ref, () => ({
      start: handleMouseDown,
      stop: handleMouseUp,
    }));

    /**
     * 楹﹀厠椋庡仴搴锋娴媆n     * 閲囬泦 500ms 鏍锋湰璁＄畻骞冲潎鑳介噺锛屽垽鏂害鍏嬮鐘舵€乗n     */
    const checkMicHealth = useCallback(async (): Promise<{
      ok: boolean;
      warning?: string;
    }> => {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({
          audio: true,
        });
        const audioContext = new AudioContext();
        const source = audioContext.createMediaStreamSource(stream);
        const analyser = audioContext.createAnalyser();
        analyser.fftSize = 256;
        source.connect(analyser);

        const dataArray = new Uint8Array(analyser.frequencyBinCount);

        // 閲囬泦 500ms 鏍锋湰锛岃绠楀钩鍧囪兘閲廫n        const samples: number[] = [];
        for (let i = 0; i < 10; i++) {
          await new Promise((r) => setTimeout(r, 50));
          analyser.getByteFrequencyData(dataArray);
          samples.push(dataArray.reduce((a, b) => a + b, 0) / dataArray.length);
        }
        const avgLevel = samples.reduce((a, b) => a + b, 0) / samples.length;

        // 鍋滄娴嬭瘯娴乗n        stream.getTracks().forEach((t) => t.stop());
        audioContext.close();

        useVoiceStore.setState({
          micStatus: {
            status:
              avgLevel >= 5 ? "ok" : avgLevel >= 1 ? "low_volume" : "muted",
            audioLevel: Math.round(avgLevel * 10),
          },
        });

        if (avgLevel < 1) {
          return {
            ok: true,
            warning: t("voice.muted"),
          };
        }
        if (avgLevel < 5) {
          return {
            ok: true,
            warning: t("voice.lowVolume"),
          };
        }
        return { ok: true };
      } catch (err) {
        if ((err as DOMException).name === "NotAllowedError") {
          useVoiceStore.setState({
            micStatus: { status: "permission_denied", audioLevel: 0 },
          });
          return { ok: false, warning: t("voice.micPermissionDenied") };
        }
        useVoiceStore.setState({
          micStatus: { status: "no_device", audioLevel: 0 },
        });
        return { ok: false, warning: "鏈娴嬪埌楹﹀厠椋庯紝璇疯繛鎺ラ害鍏嬮璁惧" };
      }
    }, []);

    /**
     * 寮€濮嬪綍闊砛n     * 鍏堟娴嬮害鍏嬮鍋ュ悍锛岄€氳繃鍚庡惎鍔?MediaRecorder + 鐢靛钩鍒嗘瀽
     */
    const handleMouseDown = async () => {
      setMicWarning(null);

      // 楹﹀厠椋庡仴搴锋娴媆n      const health = await checkMicHealth();
      if (!health.ok) {
        setMicWarning(health.warning ?? null);
        return;
      }
      if (health.warning) {
        setMicWarning(health.warning);
      }

      try {
        const stream = await navigator.mediaDevices.getUserMedia({
          audio: true,
        });
        streamRef.current = stream;
        audioChunksRef.current = [];

        const recorder = new MediaRecorder(stream, { mimeType: "audio/webm" });
        mediaRecorderRef.current = recorder;

        // 鏀堕泦闊抽鏁版嵁鍧梊n        recorder.ondataavailable = (event) => {
          if (event.data.size > 0) {
            audioChunksRef.current.push(event.data);
          }
        };

        recorder.onstop = async () => {
          cleanupStream();
          stopAudioAnalysis();
          useVoiceStore.setState({ audioLevel: 0 });

          // 鏀堕泦瀹屾暣闊抽 Blob
          const audioBlob = new Blob(audioChunksRef.current, {
            type: "audio/webm",
          });
          audioChunksRef.current = [];

          // 鏈夐煶棰戞暟鎹笖鏈夊叧鑱斿洖璋?鈫?璋冪敤鍚庣 STT
          if (audioBlob.size > 0 && onTranscribed) {
            useVoiceStore.setState({ isProcessing: true });
            try {
              // 浠庤缃腑璇诲彇鐢ㄦ埛閫夋嫨鐨?STT 寮曟搸
              const sttProviderId =
                useVoiceStore.getState().settings?.config?.sttProviderId;
              const result = await voiceService.transcribe(audioBlob, {
                providerId: sttProviderId || undefined,
              });
              if (result.text && result.text.trim()) {
                onTranscribed(result.text);
                // 鑷姩鎻愪氦妯″紡锛氳浆褰曞畬鎴愬悗瑙﹀彂鎻愪氦
                if (autoSubmit && onShouldSubmit) {
                  onShouldSubmit(result.text);
                }
                // 鍚庣 STT 鎴愬姛锛屾爣璁板瓧骞曞畬鎴怽n                useVoiceStore.setState({ subtitleStatus: "done" });
              }
            } catch (err) {
              logger.error("璇煶杞綍澶辫触", err);
              useVoiceStore.setState({
                error:
                  err instanceof Error ? err.message : t("voice.sttFailed"),
                subtitleStatus: "idle",
              });
            } finally {
              useVoiceStore.setState({ isProcessing: false });
            }
          } else {
            // 鏃犻煶棰戞暟鎹垨鏃犲洖璋冿紝瀛楀箷鐩存帴缁撴潫
            useVoiceStore.setState({ subtitleStatus: "idle" });
          }
        };

        recorder.start();
        await startRecording();
        startAudioAnalysis(stream);
        // 鍚屾鍚姩娴忚鍣?SpeechRecognition 鑾峰彇瀹炴椂瀛楀箷
        startSubtitleRecognition();
      } catch (e) {
        logger.error("鏃犳硶鍚姩褰曢煶", e);
        setMicWarning(t("voice.micAccessFailed"));
      }
    };

    /**
     * 鍋滄褰曢煶
     */
    const handleMouseUp = async () => {
      if (
        mediaRecorderRef.current &&
        mediaRecorderRef.current.state === "recording"
      ) {
        mediaRecorderRef.current.stop();
        await stopRecording();
        // 鍋滄娴忚鍣?SpeechRecognition
        stopSubtitleRecognition();
        // 鏍囪瀛楀箷鐘舵€佷负澶勭悊涓紙绛夊緟鍚庣 STT 缁撴灉锛塡n        useVoiceStore.setState({ subtitleStatus: "processing" });
      }
    };

    const pulseScale = isRecording ? 1 + (audioLevel / 100) * 0.3 : 1;

    return (
      <div className="relative">
        {/* 楹﹀厠椋庤鍛婃彁绀?*/}
        {micWarning && !isRecording && (
          <div className="absolute bottom-full mb-2 left-1/2 -translate-x-1/2 w-max max-w-48 px-2 py-1 text-xs bg-yellow-100 dark:bg-yellow-900 text-yellow-800 dark:text-yellow-200 rounded shadow whitespace-nowrap">
            {micWarning}
          </div>
        )}
        <button
          onMouseDown={handleMouseDown}
          onMouseUp={handleMouseUp}
          onMouseLeave={isRecording ? handleMouseUp : undefined}
          disabled={isProcessing}
          className={`relative flex items-center justify-center w-10 h-10 rounded-full transition-all duration-150 ${
            isProcessing
              ? isDark
                ? "bg-gray-700 cursor-not-allowed"
                : "bg-gray-300 cursor-not-allowed"
              : isRecording
                ? "bg-red-500 hover:bg-red-600"
                : isDark
                  ? "bg-gray-700 hover:bg-gray-600 text-gray-300"
                  : "bg-gray-200 hover:bg-gray-300 text-gray-600"
          }`}
          style={{ transform: `scale(${pulseScale})` }}
          title={
            isProcessing
              ? "璇煶璇嗗埆涓?.."
              : isRecording
                ? "鏉惧紑鍙戦€乗

