                <div className="mt-2 pt-2 border-t border-gray-100 dark:border-gray-700">
                  <div className="h-48">
                    <AgentChatPanel taskId={agent.id} taskName={agent.name} />
                  </div>
                </div>
              )}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

