/**
 * Agent-Model 缁戝畾閰嶇疆缁勪欢
 *
 * 鍙鍖栭厤缃?Agent 瑙掕壊涓庢ā鍨嬬殑缁戝畾鍏崇郴锛歕n * - 姣忎釜 Agent 瑙掕壊鍙互閫夋嫨涓嶅悓鐨勬ā鍨媆n * - 閰嶇疆鏈€澶?Token 鏁般€佹俯搴︾瓑鍙傛暟
 * - 瀹炴椂棰勮鍙敤妯″瀷鍒楄〃
 */

import { useState, useEffect } from "react";
import { workspaceService } from "../../services/workspaceService";
import { createLogger } from "@/utils/logger";

const logger = createLogger("components:agentModelBinding");

import { useTranslation } from "react-i18next";

// ========== 绫诲瀷瀹氫箟 ==========

/** Agent 妯″瀷缁戝畾 */
interface AgentModelBinding {
  agentRole: string;
  model: string;
  maxTokens: number;
  temperature: number;
}

/** 鍙敤妯″瀷 */
interface AvailableModel {
  id: string;
  name: string;
  provider: string;
}

// ========== 缁勪欢 Props ==========

interface AgentModelBindingConfigProps {
  workspaceId: string;
  isDark: boolean;
}

/** Agent 瑙掕壊涓枃鍚?*/
const ROLE_LABELS: Record<string, string> = {
  default: "榛樿 Agent",
  coder: "缂栫爜 Agent",
  reviewer: "瀹℃牳 Agent",
  researcher: "鐮旂┒ Agent",
  coordinator: "鍗忚皟 Agent",
  planner: "瑙勫垝 Agent",
  tester: "娴嬭瘯 Agent",
};

/**
 * Agent-Model 缁戝畾閰嶇疆缁勪欢
 */
function AgentModelBindingConfig({
  workspaceId,
  isDark,
}: AgentModelBindingConfigProps) {
  const { t } = useTranslation();
  const [bindings, setBindings] = useState<AgentModelBinding[]>([]);
  const [availableModels, setAvailableModels] = useState<AvailableModel[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState<{
    type: "success" | "error";
    text: string;
  } | null>(null);

  // 鍔犺浇閰嶇疆
  useEffect(() => {
    loadBindings();
  }, [workspaceId]);

  const loadBindings = async () => {
    setLoading(true);
    try {
      const result = await workspaceService.getAgentModelBindings(workspaceId);
      setBindings(result.bindings);
      setAvailableModels(result.availableModels);
    } catch (err) {
      logger.warn("鍔犺浇閰嶇疆澶辫触", err);
      setMessage({ type: "error", text: "鍔犺浇閰嶇疆澶辫触" });
    } finally {
      setLoading(false);
    }
  };

  // 鏇存柊缁戝畾
  const updateBinding = (
    index: number,
    field: keyof AgentModelBinding,
    value: string | number,
  ) => {
    setBindings((prev) =>
      prev.map((b, i) => (i === index ? { ...b, [field]: value } : b)),
    );
  };

  // 淇濆瓨
  const handleSave = async () => {
    setSaving(true);
    try {
      await workspaceService.updateAgentModelBindings(workspaceId, {
        bindings,
      });
      setMessage({ type: "success", text: "淇濆瓨鎴愬姛" });
      setTimeout(() => setMessage(null), 2000);
    } catch (err) {
      logger.warn("淇濆瓨澶辫触", err);
      setMessage({ type: "error", text: "淇濆瓨澶辫触" });
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <div
        className={`p-4 text-center ${isDark ? "text-gray-400" : "text-gray-500"}`}
      >
        鍔犺浇涓?..
      </div>
    );
  }

  return (
    <div className={`p-4 ${isDark ? "text-gray-200" : "text-gray-800"}`}>
      <div className="flex items-center justify-between mb-4">
        <div>
          <h3 className="text-lg font-semibold">Agent-Model 缁戝畾閰嶇疆</h3>
          <p className="text-sm text-gray-500 mt-1">{t("agent.config")}</p>
        </div>
        <button
          onClick={handleSave}
          disabled={saving}
          className="px-4 py-1.5 bg-blue-500 text-white text-sm rounded hover:bg-blue-600 disabled:opacity-50 transition-colors"
        >
          {saving ? "淇濆瓨涓?.." : "淇濆瓨"}
        </button>
      </div>

      {message && (
        <div
          className={`mb-3 p-2 rounded text-sm ${
            message.type === "success"
              ? "bg-green-50 text-green-700 dark:bg-green-900/30 dark:text-green-400"
              : "bg-red-50 text-red-700 dark:bg-red-900/30 dark:text-red-400"
          }`}
        >
          {message.text}
        </div>
      )}

      <div className="space-y-4">
        {bindings.map((binding, index) => (
          <div
            key={binding.agentRole}
            className={`p-4 rounded-lg border ${
              isDark
                ? "border-gray-700 bg-gray-800"
                : "border-gray-200 bg-white"
            }`}
          >
            <div className="flex items-center gap-3 mb-3">
              <span className="text-sm font-medium w-24">
                {ROLE_LABELS[binding.agentRole] || binding.agentRole}
              </span>
              <span className="text-xs text-gray-500 font-mono">
                {binding.agentRole}
              </span>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
              {/* 妯″瀷閫夋嫨 */}
              <div>
                <label className="block text-xs text-gray-500 mb-1">妯″瀷</label>
                <select
                  value={binding.model}
                  onChange={(e) =>
                    updateBinding(index, "model", e.target.value)
                  }
                  className={`w-full p-2 rounded text-sm border ${
                    isDark
                      ? "bg-gray-700 border-gray-600 text-gray-200"
                      : "bg-white border-gray-300 text-gray-800"
                  }`}
                >
                  {availableModels.map((m) => (
                    <option key={m.id} value={m.id}>
                      {m.name} ({m.provider})
                    </option>
                  ))}
                </select>
              </div>

              {/* 鏈€澶?Token */}
              <div>
                <label className="block text-xs text-gray-500 mb-1">
                  {t("workspace.cost")}
                </label>
                <input
                  type="number"
                  value={binding.maxTokens}
                  onChange={(e) =>
                    updateBinding(
                      index,
                      "maxTokens",
                      parseInt(e.target.value) || 4096,
                    )
                  }
                  min={256}
                  max={128000}
                  step={256}
                  className={`w-full p-2 rounded text-sm border ${
                    isDark
                      ? "bg-gray-700 border-gray-600 text-gray-200"
                      : "bg-white border-gray-300 text-gray-800"
                  }`}
                />
              </div>

              {/* 娓╁害 */}
              <div>
                <label className="block text-xs text-gray-500 mb-1">
                  娓╁害: {binding.temperature}
                </label>
                <input
                  type="range"
                  value={binding.temperature}
                  onChange={(e) =>
                    updateBinding(
                      index,
                      "temperature",
                      parseFloat(e.target.value),
                    )
                  }
                  min={0}
                  max={2}
                  step={0.1}
                  className="w-full"
                />
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

export default AgentModelBindingConfig;
export type { AgentModelBinding, AvailableModel };

/**
 * CouncilView 鈥?Agent 鐞嗕簨浼氳鍥綷n *
 * 灞曠ず Plan 妯″紡涓?AI 鍐呴儴鐨勫 Agent 杈╄杩囩▼銆俓n * 鐢ㄦ埛涓诲姩瑕佹眰鏌ョ湅鏃舵墠鏄剧ず锛歕n * - 宸︿晶锛氬弬涓?Agent 鍒楄〃 + 涓撲笟棰嗗煙
