const logger = createLogger("components:orchIntelligence");

/** Tab 绫诲瀷 */
type IntellTab = "impact" | "risks" | "decision" | "escalations" | "resources";

const TAB_CONFIG: { key: IntellTab; label: string; icon: string }[] = [
  { key: "impact", label: "褰卞搷璇勪及", icon: "\u{1F4CA}" },
  { key: "risks", label: "椋庨櫓璇嗗埆", icon: "\u26A0\uFE0F" },
  { key: "decision", label: "鍐崇瓥鍒嗙骇", icon: "\u{1F3DB}\uFE0F" },
  { key: "escalations", label: "寮傚父鍗囩骇", icon: "\u{1F514}" },
  { key: "resources", label: "璧勬簮璋冨害", icon: "\u{1F504}" },
];

/** 褰卞搷璇勪及缁撴灉 */
interface ImpactResult {
  affectedFiles: string[];
  affectedModules: string[];
  impactLevel: string;
  description: string;
  testSuggestions: string[];
  isBreaking: boolean;
  dependencyChain: string[];
}

/** 椋庨櫓椤?*/
interface RiskItem {
  id: string;
  description: string;
  level: string;
  category: string;
  trigger: string;
  mitigation: string;
  mitigated: boolean;
}

/** 鍐崇瓥缁撴灉 */
interface DecisionResult {
  type: string;
  reason: string;
  requiredApprover?: string;
  aiProposal?: string;
  evidence: string[];
}

/** 寮傚父椤?*/
interface EscalationItem {
  type: string;
  workItemId: string;
  description: string;
  occurrenceCount: number;
  lastOccurrence: number;
  suggestedDirection: string;
}

/** 璧勬簮鐘舵€?*/
interface ResourceStatus {
  resource: string;
  lockedBy: string | null;
  queueLength: number;
}

/** 椋庨櫓绛夌骇棰滆壊 */
const LEVEL_COLORS: Record<string, string> = {
  critical: "bg-red-100 text-red-700 dark:bg-red-900 dark:text-red-300",
  high: "bg-orange-100 text-orange-700 dark:bg-orange-900 dark:text-orange-300",
  medium:
    "bg-yellow-100 text-yellow-700 dark:bg-yellow-900 dark:text-yellow-300",
  low: "bg-green-100 text-green-700 dark:bg-green-900 dark:text-green-300",
  none: "bg-gray-100 text-gray-500 dark:bg-gray-800 dark:text-gray-400",
};

/** 鍐崇瓥绫诲瀷鏍囩 */
const DECISION_LABELS: Record<string, string> = {
  ai_auto: "AI 鑷喅",
  ai_propose_human_confirm: "AI 鍑烘柟妗?/ 浜虹‘璁

浜哄繀椤诲",
};

/**
 * 褰卞搷璇勪及闈㈡澘
 */
function ImpactPanel() {
  const { currentWorkspace } = useWorkspaceStore();
  const [files, setFiles] = useState("");
  const [content, setContent] = useState("");
  const [result, setResult] = useState<ImpactResult | null>(null);
  const [loading, setLoading] = useState(false);

  const handleAnalyze = async () => {
    if (!files.trim()) return;
    setLoading(true);
    try {
      const res = await workspaceService.analyzeImpact(
        currentWorkspace?.id || "",
        {
          changedFiles: files.split("\n").filter(Boolean),
          changedContent: content,
        },
      );
      setResult(res as ImpactResult);
    } catch (e) {
      handleClientError(e, {
        module: "components:workspace:OrchIntelligence",
        action: "analyzeImpact",
      });
      logger.error("褰卞搷璇勪及澶辫触", e);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="p-4 space-y-4">
      <div>
        <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">
          鍙樻洿鏂囦欢鍒楄〃锛堟瘡琛屼竴涓級
        </label>
        <textarea
          className="w-full h-24 text-sm border border-gray-200 dark:border-gray-700 rounded-md p-2 bg-white dark:bg-gray-900 text-gray-700 dark:text-gray-300 resize-none"
          value={files}
          onChange={(e) => setFiles(e.target.value)}
          placeholder="src/utils/cache.ts&#10;src/types/common.ts"
        />
      </div>
      <div>
        <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">
          鍙樻洿鍐呭鎽樿锛堝彲閫夛級
        </label>
        <textarea
          className="w-full h-16 text-sm border border-gray-200 dark:border-gray-700 rounded-md p-2 bg-white dark:bg-gray-900 text-gray-700 dark:text-gray-300 resize-none"
          value={content}
          onChange={(e) => setContent(e.target.value)}
          placeholder="淇敼浜嗙紦瀛樿繃鏈熺瓥鐣?.."
        />
      </div>
      <button
        onClick={handleAnalyze}
        disabled={loading || !files.trim()}
        className="w-full py-2 text-sm bg-blue-500 text-white rounded-md hover:bg-blue-600 disabled:opacity-50 disabled:cursor-not-allowed"
      >
        {loading ? "鍒嗘瀽涓?.." : "鍒嗘瀽褰卞搷鑼冨洿"}
      </button>

      {result && (
        <div className="border border-gray-200 dark:border-gray-700 rounded-md p-3 space-y-2">
          <div className="flex items-center gap-2">
            <span
              className={`text-xs px-2 py-0.5 rounded ${LEVEL_COLORS[result.impactLevel] || ""}`}
            >
              {result.impactLevel}
            </span>
            {result.isBreaking && (
              <span className="text-xs px-2 py-0.5 rounded bg-red-100 text-red-700 dark:bg-red-900 dark:text-red-300">
                鐮村潖鎬у彉鏇碶n              </span>
            )}
          </div>
          <p className="text-sm text-gray-600 dark:text-gray-400">
            {result.description}
          </p>
          <div>
            <p className="text-xs text-gray-500 font-medium">鍙楀奖鍝嶆ā鍧?/p>
            <div className="flex flex-wrap gap-1 mt-1">
              {result.affectedModules.map((m) => (
                <span
                  key={m}
                  className="text-xs px-2 py-0.5 bg-gray-100 dark:bg-gray-800 rounded"
                >
                  {m}
                </span>
              ))}
            </div>
          </div>
          <div>
            <p className="text-xs text-gray-500 font-medium">娴嬭瘯寤鸿</p>
            {result.testSuggestions.map((t, i) => (
              <p
                key={i}
                className="text-xs text-gray-600 dark:text-gray-400 mt-0.5"
              >
                {t}
              </p>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

/**
 * 椋庨櫓璇嗗埆闈㈡澘
 */
function RiskPanel() {
  const { currentWorkspace } = useWorkspaceStore();
  const [title, setTitle] = useState("");
  const [desc, setDesc] = useState("");
  const [risks, setRisks] = useState<RiskItem[]>([]);
  const [summary, setSummary] = useState("");
  const [loading, setLoading] = useState(false);

  const handleDetect = async () => {
    if (!title.trim()) return;
    setLoading(true);
    try {
      const res = await workspaceService.detectRisks(
        currentWorkspace?.id || "",
        { title, description: desc, changedFiles: [] },
      );
      const data = res as { risks: RiskItem[]; summary: string };
      setRisks(data.risks);
      setSummary(data.summary);
    } catch (e) {
      handleClientError(e, {
        module: "components:workspace:OrchIntelligence",
        action: "detectRisks",
      });
      logger.error("椋庨櫓璇嗗埆澶辫触", e);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="p-4 space-y-4">
      <div>
        <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">
          宸ヤ綔椤规爣棰榎n        </label>
        <input
          className="w-full text-sm border border-gray-200 dark:border-gray-700 rounded-md p-2 bg-white dark:bg-gray-900 text-gray-700 dark:text-gray-300"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          placeholder="淇鐧诲綍椤甸潰鐨?SQL 娉ㄥ叆婕忔礊"
        />
      </div>
      <div>
        <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">
          宸ヤ綔椤规弿杩帮紙鍙€夛級
        </label>
        <textarea
          className="w-full h-16 text-sm border border-gray-200 dark:border-gray-700 rounded-md p-2 bg-white dark:bg-gray-900 text-gray-700 dark:text-gray-300 resize-none"
          value={desc}
          onChange={(e) => setDesc(e.target.value)}
          placeholder="浣跨敤 raw SQL 鎷兼帴鏌ヨ..."
        />
      </div>
      <button
        onClick={handleDetect}
        disabled={loading || !title.trim()}
        className="w-full py-2 text-sm bg-orange-500 text-white rounded-md hover:bg-orange-600 disabled:opacity-50 disabled:cursor-not-allowed"
      >
        {loading ? "妫€娴嬩腑..." : "妫€娴嬮闄‐

source:
text-sm text-gray-600 dark:text-gray-400 font-medium">
          {summary}
        </p>
      )}
      {risks.map((risk) => (
        <div
          key={risk.id}
          className="border border-gray-200 dark:border-gray-700 rounded-md p-3 space-y-1"
        >
          <div className="flex items-center gap-2">
            <span
              className={`text-xs px-2 py-0.5 rounded ${LEVEL_COLORS[risk.level] || ""}`}
            >
              {risk.level}
            </span>
            <span className="text-xs text-gray-500">{risk.category}</span>
          </div>
          <p className="text-sm text-gray-700 dark:text-gray-300">
            {risk.description}
          </p>
          <div className="flex items-center gap-2 text-xs">
            <span className="text-gray-400">瑙﹀彂鏉′欢:</span>
            <code className="text-gray-500 dark:text-gray-400 bg-gray-100 dark:bg-gray-800 px-1 rounded">
              {risk.trigger}
            </code>
          </div>
          <p className="text-xs text-green-600 dark:text-green-400">
            {risk.mitigation}
          </p>
        </div>
      ))}
      {!loading && risks.length === 0 && summary && (
        <p className="text-sm text-center text-gray-400">鏈娴嬪埌椋庨櫓</p>
      )}
    </div>
  );
}

/**
 * 鍐崇瓥鍒嗙骇闈㈡澘
 */
function DecisionPanel() {
  const { currentWorkspace } = useWorkspaceStore();
  const [title, setTitle] = useState("");
  const [desc, setDesc] = useState("");
  const [result, setResult] = useState<DecisionResult | null>(null);
  const [loading, setLoading] = useState(false);

  const handleClassify = async () => {
    if (!title.trim()) return;
    setLoading(true);
    try {
      const res = await workspaceService.classifyDecision(
        currentWorkspace?.id || "",
        { title, description: desc },
      );
      setResult(res as DecisionResult);
    } catch (e) {
      handleClientError(e, {
        module: "components:workspace:OrchIntelligence",
        action: "classifyDecision",
      });
      logger.error("鍐崇瓥鍒嗙骇澶辫触", e);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="p-4 space-y-4">
      <div>
        <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">
          宸ヤ綔椤规爣棰榎n        </label>
        <input
          className="w-full text-sm border border-gray-200 dark:border-gray-700 rounded-md p-2 bg-white dark:bg-gray-900 text-gray-700 dark:text-gray-300"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          placeholder="鍒犻櫎鐢ㄦ埛琛ㄥ苟閲嶅缓绱㈠紩"
        />
      </div>
      <div>
        <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">
          宸ヤ綔椤规弿杩帮紙鍙€夛級
        </label>
        <textarea
          className="w-full h-16 text-sm border border-gray-200 dark:border-gray-700 rounded-md p-2 bg-white dark:bg-gray-900 text-gray-700 dark:text-gray-300 resize-none"
          value={desc}
          onChange={(e) => setDesc(e.target.value)}
        />
      </div>
      <button
        onClick={handleClassify}
        disabled={loading || !title.trim()}
        className="w-full py-2 text-sm bg-purple-500 text-white rounded-md hover:bg-purple-600 disabled:opacity-50 disabled:cursor-not-allowed"
      >
        {loading ? "鍒嗙骇涓?.." : "鍐崇瓥鍒嗙骇"}
      </button>

      {result && (
        <div className="border border-gray-200 dark:border-gray-700 rounded-md p-3 space-y-2">
          <div className="flex items-center gap-2">
            <span className="text-lg font-medium text-gray-700 dark:text-gray-300">
              {DECISION_LABELS[result.type] || result.type}
            </span>
          </div>
          <p className="text-sm text-gray-600 dark:text-gray-400">
            {result.reason}
          </p>
          {result.requiredApprover && (
            <p className="text-xs text-gray-500">
              瀹℃壒浜?{" "}
              <span className="font-medium">{result.requiredApprover}</span>
            </p>
          )}
          {result.evidence.length > 0 && (
            <div>
              <p className="text-xs text-gray-500 font-medium">鍐崇瓥渚濇嵁</p>
              {result.evidence.map((e, i) => (
                <p key={i} className="text-xs text-gray-600 dark:text-gray-400">
                  {e}
                </p>
              ))}
            </div>
          )}
          {result.aiProposal && (
            <div className="bg-blue-50 dark:bg-blue-900/20 rounded-md p-2">
              <p className="text-xs text-blue-600 dark:text-blue-400 whitespace-pre-wrap">
                {result.aiProposal}
              </p>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

/**
 * 寮傚父鍗囩骇闈㈡澘
 */
function EscalationsPanel() {
  const { currentWorkspace } = useWorkspaceStore();
  const [escalations, setEscalations] = useState<EscalationItem[]>([]);
  const [loading, setLoading] = useState(false);

  const fetchEscalations = async () => {
    setLoading(true);
    try {
      const res = await workspaceService.getEscalations(
        currentWorkspace?.id || "",
      );
      setEscalations(res as EscalationItem[]);
    } catch (e) {
      handleClientError(e, {
        module: "components:workspace:OrchIntelligence",
        action: "getEscalations",
      });
      logger.error("鑾峰彇寮傚父鍒楄〃澶辫触", e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchEscalations();
  }, []);

  return (
    <div className="p-4 space-y-3">
      <button
        onClick={fetchEscalations}
        disabled={loading}
        className="w-full py-2 text-sm bg-gray-100 dark:bg-gray-800 text-gray-700 dark:text-gray-300 rounded-md hover:bg-gray-200 dark:hover:bg-gray-700"
      >
        {loading ? "鍒锋柊涓?.." : "鍒锋柊寮傚父鍒楄〃"}
      </button>

      {escalations.length === 0 && !loading && (
        <p className="text-sm text-center text-gray-400 py-8">鏆傛棤娲昏穬寮傚父</p>
      )}
      {escalations.map((esc, i) => (
        <div
          key={i}
          className="border border-gray-200 dark:border-gray-700 rounded-md p-3 space-y-1"
        >
          <div className="flex items-center justify-between">
            <span className="text-xs font-medium text-gray-500">
              {esc.type}
            </span>
            <span className="text-xs text-gray-400">
              脳{esc.occurrenceCount}
            </span>
          </div>
          <p className="text-sm text-gray-700 dark:text-gray-300">
            {esc.description}
          </p>
          <p className="text-xs text-gray-500">宸ヤ綔椤? {esc.workItemId}</p>
          <p className="text-xs text-blue-600 dark:text-blue-400">
            {esc.suggestedDirection}
          </p>
        </div>
      ))}
    </div>
  );
}

/**
 * 璧勬簮璋冨害闈㈡澘
 */
function ResourcesPanel() {
  const { currentWorkspace } = useWorkspaceStore();
  const [resources, setResources] = useState<ResourceStatus[]>([]);
  const [loading, setLoading] = useState(false);

  const fetchResources = async () => {
    setLoading(true);
    try {
      const res = await workspaceService.getResources(
        currentWorkspace?.id || "",
      );
      setResources(res as ResourceStatus[]);
    } catch (e) {
      handleClientError(e, {
        module: "components:workspace:OrchIntelligence",
        action: "getResources",
      });
      logger.error("鑾峰彇璧勬簮鐘舵€佸け璐

text-sm text-center text-gray-400 py-8">鏆傛棤娲昏穬璧勬簮</p>
      )}
      {resources.map((r, i) => (
        <div
          key={i}
          className="border border-gray-200 dark:border-gray-700 rounded-md p-3 flex items-center justify-between"
        >
          <div>
            <p className="text-sm font-medium text-gray-700 dark:text-gray-300">
              {r.resource}
            </p>
            <p className="text-xs text-gray-500">
              {r.lockedBy ? `鍗犵敤: ${r.lockedBy}` : "绌洪棽"}
            </p>
          </div>
          <div className="flex items-center gap-2">
            <span
              className={`w-2 h-2 rounded-full ${r.lockedBy ? "bg-red-500" : "bg-green-500"}`}
            />
            {r.queueLength > 0 && (
              <span className="text-xs text-yellow-600 dark:text-yellow-400">
                鎺掗槦 {r.queueLength}
              </span>
            )}
          </div>
        </div>
      ))}
    </div>
  );
}

/**
 * 缂栨帓鏅鸿兘涓昏鍥綷n */
export const OrchIntelligenceView: React.FC = () => {
  const [activeTab, setActiveTab] = useState<IntellTab>("impact");

  return (
    <div className="flex flex-col h-full">
      {/* Tab 瀵艰埅 */}
      <div className="flex border-b border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900 px-2">
        {TAB_CONFIG.map((tab) => (
          <button
            key={tab.key}
            onClick={() => setActiveTab(tab.key)}
            className={`flex items-center gap-1 px-3 py-2 text-xs border-b-2 transition-colors ${
              activeTab === tab.key
                ? "border-blue-500 text-blue-600 dark:text-blue-400 font-medium"
                : "border-transparent text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-300"
            }`}
          >
            <span>{tab.icon}</span>
            <span>{tab.label}</span>
          </button>
        ))}
      </div>

      {/* 鍐呭 */}
      <div className="flex-1 overflow-y-auto">
        {activeTab === "impact" && <ImpactPanel />}
        {activeTab === "risks" && <RiskPanel />}
        {activeTab === "decision" && <DecisionPanel />}
        {activeTab === "escalations" && <EscalationsPanel />}
        {activeTab === "resources" && <ResourcesPanel />}
      </div>
    </div>
  );
};

