                              </p>
                            </div>
                          )}

                          {task.lastRun && (
                            <div className="p-3 bg-gray-50 dark:bg-gray-700/50 rounded">
                              <span className="text-xs font-medium text-gray-500 dark:text-gray-400">
                                {t("cron.lastRunTime", "Last Run")}
