/**
 * JSON 缇庡寲娓叉煋缁勪欢
 */
function PrettyJson({ content }: { content: string }) {
  let parsed: unknown;
  try {
    parsed = JSON.parse(content);
  } catch {
    return <code>{content}</code>;
  }

  const formatted = JSON.stringify(parsed, null, 2);

  return <code>{formatted}</code>;
}

