import { useEffect, useState, useCallback } from "react";
import { useTranslation } from "react-i18next";
import { useConfigStore } from "../../stores/configStore";
import { monitorService } from "../../services/monitorService";
import { usageService, type CostSummary } from "../../services/usageService";
import type { LogEntry, LogSource } from "../../types";
import type {
  SessionSummary,
  SessionDetail,
} from "../../services/monitorService";
import { logStore, type FrontendLogEntry } from "../../utils/logStore";
import SearchInput from "../common/SearchInput";
import LogViewer from "../common/LogViewer";
import { OTELSpanViewer } from "../common/OTELSpanViewer";
import { OTELTraceViewer } from "../common/OTELTraceViewer";
import { createLogger } from "@/utils/logger";

const logger = createLogger("components:logViewer");

const ENABLE_TRACE_REDESIGN = true;

type TabType = "logs" | "frontend" | "sessions" | "cost" | "otel";

function LogViewerPage() {
  const { t, i18n } = useTranslation();
  const config = useConfigStore((s) => s.config);
  const isDark = config.theme === "dark";

  const [activeTab, setActiveTab] = useState<TabType>("logs");

  // 鏃ュ織鐩稿叧鐘舵€乗n  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [logsTotal, setLogsTotal] = useState(0);
  const [isLoadingLogs, setIsLoadingLogs] = useState(false);
  const [logsError, setLogsError] = useState<string | null>(null);

  const [levelFilter, setLevelFilter] = useState<string>("all");
  const [sourceFilter, setSourceFilter] = useState<LogSource>("all");
  const [searchQuery, setSearchQuery] = useState("");
  const [offset, setOffset] = useState(0);
  const limit = 50;

  // 浼氳瘽鐩稿叧鐘舵€乗n  const [sessions, setSessions] = useState<SessionSummary[]>([]);
  const [isLoadingSessions, setIsLoadingSessions] = useState(false);
  const [sessionsError, setSessionsError] = useState<string | null>(null);
  const [selectedSession, setSelectedSession] = useState<SessionDetail | null>(
    null,
  );

  // 鎴愭湰鐩稿叧鐘舵€乗n  const [costSummary, setCostSummary] = useState<CostSummary | null>(null);
  const [isLoadingCost, setIsLoadingCost] = useState(false);
  const [costError, setCostError] = useState<string | null>(null);

  // 鍓嶇鏃ュ織鐩稿叧鐘舵€乗n  const [frontendLogs, setFrontendLogs] = useState<FrontendLogEntry[]>([]);
  const [frontendLogsTotal, setFrontendLogsTotal] = useState(0);
  const [frontendLevelFilter, setFrontendLevelFilter] = useState<string>("all");
  const [frontendModuleFilter, setFrontendModuleFilter] = useState<string>("");
  const [frontendSearchQuery, setFrontendSearchQuery] = useState("");
  const [frontendOffset, setFrontendOffset] = useState(0);
  const frontendLimit = 50;

  const fetchLogs = useCallback(
    async (resetOffset = false) => {
      setIsLoadingLogs(true);
      setLogsError(null);

      try {
        const params = {
          level:
            levelFilter !== "all"
              ? (levelFilter as LogEntry["level"])
              : undefined,
          source: sourceFilter !== "all" ? sourceFilter : undefined,
          search: searchQuery || undefined,
          limit,
          offset: resetOffset ? 0 : offset,
        };

        const result = await monitorService.getLogs(params);

        if (resetOffset) {
          setLogs(result.logs);
          setOffset(limit);
        } else {
          setLogs((prev) => [...prev, ...result.logs]);
          setOffset((prev) => prev + limit);
        }
        setLogsTotal(result.total);
      } catch (e) {
        setLogsError(
          e instanceof Error
            ? e.message
            : t("settings.logViewerErrorFetchLogs"),
        );
      } finally {
        setIsLoadingLogs(false);
      }
    },
    [levelFilter, sourceFilter, searchQuery, offset],
  );

  const fetchSessions = useCallback(async () => {
    setIsLoadingSessions(true);
    setSessionsError(null);

    try {
      const result = await monitorService.getSessions({ limit: 50, offset: 0 });
      setSessions(result.sessions);
    } catch (e) {
      setSessionsError(
        e instanceof Error
          ? e.message
          : t("settings.logViewerErrorFetchSessions"),
      );
    } finally {
      setIsLoadingSessions(false);
    }
  }, []);

  const fetchCostSummary = useCallback(async () => {
    setIsLoadingCost(true);
    setCostError(null);

    try {
      const result = await usageService.getCostSummary();
      setCostSummary(result);
    } catch (e) {
      setCostError(
        e instanceof Error ? e.message : t("settings.logViewerErrorFetchCost"),
      );
    } finally {
      setIsLoadingCost(false);
    }
  }, []);

  const fetchSessionDetail = useCallback(async (sessionId: string) => {
    try {
      const result = await monitorService.getSessionDetail(sessionId);
      setSelectedSession(result);
    } catch (e) {
      logger.error("鑾峰彇浼氳瘽璇︽儏澶辫触", e);
    }
  }, []);

  const fetchFrontendLogs = useCallback(
    (resetOffset = false) => {
      const params = {
        level:
          frontendLevelFilter !== "all"
            ? (frontendLevelFilter as FrontendLogEntry["level"])
            : undefined,
        module: frontendModuleFilter || undefined,
        search: frontendSearchQuery || undefined,
        limit: frontendLimit,
        offset: resetOffset ? 0 : frontendOffset,
      };

      const result = logStore.query(params);

      if (resetOffset) {
        setFrontendLogs(result.logs);
        setFrontendOffset(frontendLimit);
      } else {
        setFrontendLogs((prev) => [...prev, ...result.logs]);
        setFrontendOffset((prev) => prev + frontendLimit);
      }
      setFrontendLogsTotal(result.total);
    },
    [
      frontendLevelFilter,
      frontendModuleFilter,
      frontendSearchQuery,
      frontendOffset,
    ],
  );

  useEffect(() => {
    if (activeTab === "logs") {
      fetchLogs(true);
    } else if (activeTab === "frontend") {
      fetchFrontendLogs(true);
    } else if (activeTab === "sessions") {
      fetchSessions();
    } else if (activeTab === "cost") {
      fetchCostSummary();
    }
  }, [activeTab]);

  useEffect(() => {
    if (activeTab === "logs") {
      fetchLogs(true);
    }
  }, [levelFilter, sourceFilter, searchQuery]);

  useEffect(() => {
    if (activeTab === "frontend") {
      fetchFrontendLogs(true);
    }
  }, [frontendLevelFilter, frontendModuleFilter, frontendSearchQuery]);

  const handleFrontendSearch = () => {
    fetchFrontendLogs(true);
  };

  const handleLoadMoreFrontendLogs = () => {
    fetchFrontendLogs(false);
  };

  const handleClearFrontendLogs = () => {
    logStore.clear();
    fetchFrontendLogs(true);
  };

  const formatFrontendDate = (timestamp: number): string => {
    const date = new Date(timestamp);
    const locale = i18n.language === "en" ? "en-US" : "zh-CN";
    return date.toLocaleString(locale, {
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
    });
  };

  const handleSearch = () => {
    fetchLogs(true);
  };

  const handleLoadMoreLogs = () => {
    fetchLogs(false);
  };

  const handleViewSessionDetail = (sessionId: string) => {
    fetchSessionDetail(sessionId);
  };

  const handleCloseSessionDetail = () => {
    setSelectedSession(null);
  };

  const handleExportLogs = async (format: "json" | "csv") => {
    try {
      const blob = await monitorService.exportLogs({
        format,
        level: levelFilter !== "all" ? levelFilter : undefined,
        source: sourceFilter !== "all" ? sourceFilter : undefined,
        search: searchQuery || undefined,
      });

      const filename = `logs-${Date.now()}.${format}`;
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = filename;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      window.URL.revokeObjectURL(url);
    } catch (e) {
      logger.error("瀵煎嚭鏃ュ織澶辫触", e);
    }
  };

  const formatCost = (cost: number): string => {
    return cost.toFixed(4);
  };

  const formatTokens = (tokens: number): string => {
    if (tokens >= 1000) {
      return (tokens / 1000).toFixed(1) + "K";
    }
    return tokens.toString();
  };

  const formatDate = (dateStr: string): string => {
    const date = new Date(dateStr);
    const locale = i18n.language === "en" ? "en-US" : "zh-CN";
    return date.toLocaleString(locale, {
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
    });
  };

  const tabs = [
    { key: "logs" as TabType, label: t("settings.logViewerTabLogs") },
    { key: "frontend" as TabType, label: t("settings.logViewerTabFrontend") },
    { key: "sessions" as TabType, label: t("settings.logViewerTabSessions") },
    { key: "cost" as TabType, label: t("settings.logViewerTabCost") },
    { key: "otel" as TabType, label: t("settings.logViewerTabOtel") },
