import { useEffect, useState, useMemo } from "react";
import { useConfigStore } from "../../stores/configStore";
import { useSkillStore } from "../../stores/skillStore";
import type {
  Skill,
  SkillCreateData,
  SkillStatus,
  SkillSource,
  SkillContent,
} from "../../services/skillService";
import { useTranslation } from "react-i18next";
import { skillService } from "../../services/skillService";
import SearchInput from "../common/SearchInput";
import ConfirmDialog from "../common/ConfirmDialog";
import SkillList from "../Skill/SkillList";
import SkillDetail from "../Skill/SkillDetail";
import SkillEditor from "../Skill/SkillEditor";
import SkillMarketModal from "./SkillMarketModal";

function SkillPage() {
  const { t } = useTranslation();
  const config = useConfigStore((s) => s.config);
  const isDark = config.theme === "dark";

  const {
    skills,
    total,
    selectedSkill,
    categories,
    error,
    loadSkills,
    loadCategories,
    createSkill,
    updateSkill,
    deleteSkill,
    enableSkill,
    disableSkill,
    setSelectedSkill,
  } = useSkillStore();

  const [sortBy, setSortBy] = useState<
    "createdAt" | "updatedAt" | "usageCount"
  >("updatedAt");
  const [sortOrder, setSortOrder] = useState<"asc" | "desc">("desc");
  const [categoryFilter, setCategoryFilter] = useState("");
  const [statusFilter, setStatusFilter] = useState<SkillStatus | "all">("all");
  const [searchQuery, setSearchQuery] = useState("");
  const [sourceFilter, setSourceFilter] = useState<SkillSource | null>(null);
  const [activeTab, setActiveTab] = useState<
    "local" | "official" | "third_party"
  >("local");
  const [showMarket, setShowMarket] = useState(false);
  const [showEditor, setShowEditor] = useState(false);
  const [editingSkill, setEditingSkill] = useState<Skill | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<Skill | null>(null);
  const [skillContent, setSkillContent] = useState<SkillContent | null>(null);

  useEffect(() => {
    // Bug 1: Tab 鍒囨崲鏃跺悓姝ユ洿鏂?sourceFilter 骞舵竻闄?selectedSkill
    if (activeTab === "local") {
      setSourceFilter(null);
    } else {
      setSourceFilter(activeTab);
    }
    setSelectedSkill(null);
  }, [activeTab]);

  useEffect(() => {
    // Bug 7: 灏?sourceFilter 浼犻€掑埌鍚庣 API
    loadSkills({
      sortBy,
      sortOrder,
      category: categoryFilter || undefined,
      status: statusFilter === "all" ? undefined : statusFilter,
      source: sourceFilter || undefined,
    });
    loadCategories();
  }, [
    loadSkills,
    loadCategories,
    sortBy,
    sortOrder,
    categoryFilter,
    statusFilter,
    sourceFilter,
  ]);

  // 鎼滅储 + 鏉ユ簮杩囨护鍚庣殑鎶€鑳藉垪琛╘n  const filteredSkills = useMemo(() => {
    let result = skills;

    // 鏉ユ簮杩囨护
    if (sourceFilter) {
      result = result.filter((s) => s.source === sourceFilter);
    }

    // 鎼滅储杩囨护
    if (searchQuery.trim()) {
      const q = searchQuery.toLowerCase();
      result = result.filter(
        (s) =>
          s.name.toLowerCase().includes(q) ||
          s.description.toLowerCase().includes(q) ||
          s.category.toLowerCase().includes(q),
      );
    }

    return result;
  }, [skills, searchQuery, sourceFilter]);

  // 缁熻闈㈡澘鏁版嵁
  const stats = useMemo(
    () => ({
      total: skills.length,
      enabled: skills.filter((s) => s.status === "enabled").length,
      disabled: skills.filter((s) => s.status === "disabled").length,
      draft: skills.filter((s) => s.status === "draft").length,
    }),
    [skills],
  );

  const handleSelectSkill = (skill: Skill) => {
    setSelectedSkill(skill);
    setShowEditor(false);
    setEditingSkill(null);

    // 寮傛鍔犺浇鎶€鑳藉唴瀹筡n    setSkillContent(null);
    skillService
      .getContent(skill.id)
      .then((content) => {
        setSkillContent(content);
      })
      .catch(() => {
        setSkillContent(null);
      });
  };

  const handleCreate = () => {
    setEditingSkill(null);
    setShowEditor(true);
    setSelectedSkill(null);
  };

  const handleEdit = () => {
    if (selectedSkill) {
      setEditingSkill(selectedSkill);
      setShowEditor(true);
    }
  };

  const handleSave = async (data: SkillCreateData | Partial<Skill>) => {
    if (editingSkill) {
      await updateSkill(editingSkill.id, data);
    } else {
      await createSkill(data as SkillCreateData);
    }
    setShowEditor(false);
    setEditingSkill(null);
    loadSkills({ sortBy, sortOrder });
  };

  const handleDelete = () => {
    if (selectedSkill) {
      setDeleteTarget(selectedSkill);
    }
  };

  const handleDeleteConfirm = async () => {
    if (deleteTarget) {
      await deleteSkill(deleteTarget.id);
      setDeleteTarget(null);
      setSelectedSkill(null);
      loadSkills({ sortBy, sortOrder });
    }
  };

  const handleToggleStatus = async () => {
    if (selectedSkill) {
      if (selectedSkill.status === "enabled") {
        await disableSkill(selectedSkill.id);
      } else {
        await enableSkill(selectedSkill.id);
