          type: newTaskForm.scheduleType,
          cronExpression:
            newTaskForm.scheduleType === "cron"
              ? newTaskForm.cronExpression
              : undefined,
          intervalMinutes:
            newTaskForm.scheduleType === "interval"
              ? newTaskForm.intervalMinutes
              : undefined,
          scheduledTime:
            newTaskForm.scheduleType === "once"
              ? newTaskForm.scheduledTime
              : undefined,
          enabled: true,
