import { useTranslation } from "react-i18next";
import { httpLegacy as http } from "../../services/httpClient";

const XTermPanel = lazy(() => import("../Terminal/XTermPanel"));

interface TerminalLine {
  id: string;
  type: "input" | "output" | "error";
  content: string;
  timestamp: number;
}

interface CommandResult {
  success: boolean;
  output: string;
  error: string;
}

interface BackendCommand {
  name: string;
  description: string;
  aliases: string[];
  argumentHint: string;
  userInvocable: boolean;
}

function TerminalPage() {
  const { t } = useTranslation();
  const [lines, setLines] = useState<TerminalLine[]>([]);
  const [input, setInput] = useState("");
  const [history, setHistory] = useState<string[]>([]);
  const [historyIndex, setHistoryIndex] = useState(-1);
  const [isExecuting, setIsExecuting] = useState(false);
  const [cwd, setCwd] = useState("~");
  const [backendCommands, setBackendCommands] = useState<BackendCommand[]>([]);
  const [mode, setMode] = useState<"basic" | "xterm">("basic");
  const terminalRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    loadBackendCommands();
    addLine(t("terminal.welcome"), "output");
    addLine(t("terminal.helpHint"), "output");
    addLine("", "output");
  }, []);

  const loadBackendCommands = async () => {
    try {
      const cmds = await http.get<BackendCommand[]>("/v1/commands");
      setBackendCommands(cmds);
    } catch {
      // 闈欓粯澶辫触锛宧elp 鍛戒护浠嶄細灞曠ず鏈湴甯姪
    }
  };

  useEffect(() => {
    terminalRef.current?.scrollTo(0, terminalRef.current.scrollHeight);
  }, [lines]);

  const addLine = useCallback((content: string, type: TerminalLine["type"]) => {
    setLines((prev) => [
      ...prev,
      {
        id: crypto.randomUUID(),
        type,
        content,
        timestamp: Date.now(),
      },
    ]);
  }, []);

  const executeBackendCommand = async (
    command: string,
  ): Promise<CommandResult> => {
    try {
      const result = await http.post<CommandResult>("/v1/commands/execute", {
        command,
      });
      return result;
    } catch (error) {
      return {
        success: false,
        output: "",
        error:
          error instanceof Error ? error.message : t("terminal.networkError"),
      };
    }
  };

  const executeCommand = async (cmd: string) => {
    if (!cmd.trim()) return;

    addLine(`鉂?${cmd}`, "input");
    setHistory((prev) => [cmd, ...prev].slice(0, 50));
    setHistoryIndex(-1);

    const trimmedCmd = cmd.trim();
    setIsExecuting(true);

    // 澶勭悊 cd 鍛戒护锛堝鎴风缁存姢鐩綍鐘舵€侊級
    if (trimmedCmd.startsWith("cd ")) {
      const args = trimmedCmd.split(/\s+/).slice(1);
      const target = args[0];
      if (target === "..") {
        setCwd((prev) =>
          prev === "~" ? "~" : prev.split("/").slice(0, -1).join("/") || "~",
        );
      } else if (target === "~" || target === "/") {
        setCwd("~");
      } else {
        setCwd((prev) => `${prev === "~" ? "" : prev}/${target}`);
      }
      addLine("", "output");
      setIsExecuting(false);
      return;
    }

    // 澶勭悊 clear 鍛戒护
    if (trimmedCmd === "clear" || trimmedCmd === "/clear") {
      setLines([]);
      setIsExecuting(false);
      return;
    }

    // 澶勭悊 pwd 鍛戒护
    if (trimmedCmd === "pwd" || trimmedCmd === "/pwd") {
      addLine(cwd === "~" ? "/home/user" : cwd, "output");
      setIsExecuting(false);
      return;
    }

    // 澶勭悊 date 鍛戒护
    if (trimmedCmd === "date" || trimmedCmd === "/date") {
      addLine(new Date().toLocaleString("zh-CN"), "output");
      setIsExecuting(false);
      return;
    }

    // 澶勭悊 whoami 鍛戒护
    if (trimmedCmd === "whoami" || trimmedCmd === "/whoami") {
      addLine("user", "output");
      setIsExecuting(false);
      return;
    }

    // 澶勭悊 help 鍛戒护锛氬睍绀哄悗绔彲鐢ㄥ懡浠n    if (trimmedCmd === "help" || trimmedCmd === "/help") {
      addLine(t("terminal.help.availableCommands"), "output");
      addLine(t("terminal.help.cd"), "output");
      addLine(t("terminal.help.clear"), "output");
      addLine(t("terminal.help.pwd"), "output");
      addLine(t("terminal.help.date"), "output");
      addLine(t("terminal.help.whoami"), "output");
      addLine(t("terminal.help.help"), "output");
      if (backendCommands.length > 0) {
        addLine("", "output");
        addLine(t("terminal.help.backendCommands"), "output");
        backendCommands.forEach((cmd) => {
          const hint = cmd.argumentHint ? ` ${cmd.argumentHint}` : "";
          addLine(`  ${cmd.name}${hint}    ${cmd.description}`, "output");
        });
      }
      addLine("", "output");
      setIsExecuting(false);
      return;
    }

    // 鍏朵粬鍛戒护鍙戦€佸埌鍚庣鎵ц
    const result = await executeBackendCommand(trimmedCmd);

    if (result.success) {
      if (result.output) {
        const outputLines = result.output.split("\n");
        outputLines.forEach((line: string) => {
          addLine(line, "output");
        });
      }
    } else {
      addLine(result.error || "Command execution failed", "error");
    }

    addLine("", "output");
    setIsExecuting(false);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Enter" && !isExecuting) {
      executeCommand(input);
      setInput("");
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      if (historyIndex < history.length - 1) {
        const newIndex = historyIndex + 1;
        setHistoryIndex(newIndex);
        setInput(history[newIndex]);
      }
    } else if (e.key === "ArrowDown") {
      e.preventDefault();
      if (historyIndex > 0) {
        const newIndex = historyIndex - 1;
        setHistoryIndex(newIndex);
        setInput(history[newIndex]);
      } else if (historyIndex === 0) {
        setHistoryIndex(-1);
        setInput("");
      }
    }
  };

  const focusInput = () => {
    inputRef.current?.focus();
  };

  const getPrompt = () => {
    const user = "user";
    const host = "pyapp";
    const dir = cwd === "~" ? "~" : cwd.split("/").pop() || "~";
    return `${user}@${host}:${dir}$ `;
  };

  return (
    <div
      className="flex-1 overflow-hidden flex flex-col bg-black"
      onClick={focusInput}
    >
      <div className="px-4 py-2 bg-gray-900 border-b border-gray-800 flex items-center justify-between">
        <div className="flex items-center gap-4">
          <span className="text-gray-400 text-sm">{t("terminal.title")}</span>
          <div className="flex gap-1">
            <span className="w-3 h-3 rounded-full bg-red-500" />
            <span className="w-3 h-3 rounded-full bg-yellow-500" />
            <span className="w-3 h-3 rounded-full bg-green-500" />
          </div>
          <div className="flex gap-1 ml-4">
            <button
              onClick={() => setMode("basic")}
              className={`text-xs px-2 py-0.5 rounded ${mode === "basic" ? "bg-gray-700 text-white" : "text-gray-500 hover:text-gray-300"}`}
            >
              {t("terminal.basic")}
            </button>
            <button
              onClick={() => setMode("xterm")}
              className={`text-xs px-2 py-0.5 rounded ${mode === "xterm" ? "bg-gray-700 text-white" : "text-gray-500 hover:text-gray-300"}`}
            >
              xterm.js
            </button>
          </div>
        </div>
      </div>
      {mode === "xterm" ? (
        <Suspense
          fallback={
            <div className="flex-1 flex items-center justify-center text-gray-500 text-sm">
              {t("terminal.loadingEngine")}
            </div>
          }
        >
          <XTermPanel />
        </Suspense>
      ) : (
        <>
          <div className="px-4 py-2 bg-gray-900 border-b border-gray-800 flex items-center justify-end">
            <button
              onClick={() => setLines([])}
              className="px-2 py-1 text-xs text-gray-400 hover:text-white hover:bg-gray-800 rounded"
            >
              {t("terminal.clear")}
            </button>
          </div>

          <div
            ref={terminalRef}
            className="flex-1 overflow-y-auto p-4 font-mono text-sm"
            onClick={focusInput}
          >
            {lines.map((line) => (
              <div key={line.id} className="whitespace-pre-wrap">
                {line.type === "input" ? (
                  <span className="text-green-400">{line.content}</span>
                ) : line.type === "error" ? (
                  <span className="text-red-400">{line.content}</span>
                ) : (
                  <span className="text-gray-300">{line.content}</span>
                )}
              </div>
            ))}
          </div>

          <div className="px-4 py-3 bg-gray-900 border-t border-gray-800">
            <div className="flex items-center">
              <span className="text-green-400 font-mono text-sm mr-2">
                {getPrompt()}
              </span>
              <input
                ref={inputRef}
                type="text"
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={handleKeyDown}
                disabled={isExecuting}
                className="flex-1 bg-transparent text-white font-mono text-sm outline-none"
                autoFocus
                placeholder={isExecuting ? t("terminal.executing") : ""}
              />
            </div>
          </div>
        </>
      )}
    </div>
  );
}

export default TerminalPage;

