// canvas-editor/components/CanvasSurface.tsx 鈥?涓夊眰 Canvas 缁樺埗鍖篭n// 灞傜骇: Static(搴曢儴) 鈫?Interactive(棰勮) 鈫?Overlay(閫夊尯/鏂囧瓧)
// 浜嬩欢缁熶竴鍦?Overlay 灞傜洃鍚紝InputAdapter 鍧愭爣杞崲鍚庡垎鍙慭n
import React, { useRef, useEffect, useState } from "react";
import { CanvasTool, CanvasState } from "../types";
import { CanvasTransform } from "../core/CanvasTransform";
import { CommandManager } from "../core/CommandManager";
import { OffscreenBuffer } from "../core/OffscreenBuffer";
import { InputAdapter } from "../core/InputAdapter";
import { getTool } from "../tools/index";
import { ToolContext } from "../tools/base";
import { clipBoard } from "../utils/clipBoard";
import { SelectTool } from "../tools/SelectTool";
import { LassoSelectTool } from "../tools/LassoSelectTool";

interface Props {
  state: CanvasState;
  transform: CanvasTransform;
  buffer: OffscreenBuffer;
  commands: CommandManager;
  setActiveTool: (tool: CanvasTool) => void;
  onCursorMove: (x: number, y: number) => void;
  onStateChange: (s: Partial<CanvasState>) => void;
  onLoadImage?: (file: File | string) => void;
  /** 鍙抽敭鑿滃崟瀵煎嚭鍥炶皟 */
  onContextExport?: (format: "png" | "jpeg" | "webp") => void;
  /** 鍙抽敭鑿滃崟娓呯┖鍥炶皟 */
  onContextClear?: () => void;
  /** 鍙抽敭鑿滃崟瑁佸壀鍥炶皟 */
  onContextCrop?: () => void;
  /** 鍙抽敭鑿滃崟缈昏浆鍥炶皟 */
  onContextFlip?: (dir: "horizontal" | "vertical") => void;
  /** 鍙抽敭鑿滃崟婊ら暅鍥炶皟 */
  onContextFilter?: (
    op:
      | "brightness+"
      | "brightness-"
      | "contrast+"
      | "contrast-"
      | "grayscale"
      | "invert"
      | "blur",
  ) => void;
  /** 鍙抽敭鑿滃崟鏂板缓鐢诲竷鍥炶皟 */
  onContextNew?: () => void;
  /** Ctrl+S 蹇嵎閿鍑哄洖璋?*/
  onExportShortcut?: () => void;
  /** Ctrl+Shift+S 閫夊尯瀵煎嚭鍥炶皟 */
  onSelectionExport?: () => void;
  /** 缁樺埗鐘舵€侀€氱煡锛堜緵鑷姩淇濆瓨浜掓枼鐢級 */
  onDrawingChange?: (drawing: boolean) => void;
}

let rafId = 0;
let needsRender = true;

/** 浣跨敤 Interactive 灞傝繘琛屽疄鏃堕瑙堢殑宸ュ叿 */
const INTERACTIVE_TOOLS = new Set<CanvasTool>([
  "pencil",
  "eraser",
  "line",
  "arrow",
  "rect",
  "roundedRect",
  "ellipse",
  "polygon",
  "star",
]);

/** 姝ヨ繘缂╂斁妗ｄ綅锛圕trl+=/- 閫愭。鍒囨崲锛?*/
const ZOOM_STEPS = [0.1, 0.25, 0.5, 0.75, 1.0, 1.5, 2.0, 3.0, 5.0, 8.0, 16.0];

/** 鎵惧埌鏈€鎺ヨ繎鐨勭缉鏀炬。浣嶇储寮?*/
function findZoomStep(z: number) {
  let best = 0;
  for (let i = 1; i < ZOOM_STEPS.length; i++) {
    if (Math.abs(ZOOM_STEPS[i] - z) < Math.abs(ZOOM_STEPS[best] - z)) best = i;
  }
  return best;
}

/** 浠庨€夊尯/濂楃储宸ュ叿鑾峰彇褰撳墠閫夊尯 */
function getSelection(
  toolId: CanvasTool,
): { x: number; y: number; w: number; h: number } | null {
  if (toolId === "select") {
    const t = getTool("select") as SelectTool;
    return t?.getSelection?.() ?? null;
  }
  if (toolId === "lasso") {
    const t = getTool("lasso") as LassoSelectTool;
    return t?.getSelection?.() ?? null;
  }
  return null;
}

export const CanvasSurface: React.FC<Props> = ({
  state,
  transform,
  buffer,
  commands,
  setActiveTool,
  onCursorMove,
  onStateChange,
  onLoadImage,
  onContextExport,
  onContextClear,
  onContextCrop,
  onContextFlip,
  onContextFilter,
  onContextNew,
  onExportShortcut,
  onSelectionExport,
  onDrawingChange,
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const staticRef = useRef<HTMLCanvasElement>(null);
  const interactiveRef = useRef<HTMLCanvasElement>(null);
  const overlayRef = useRef<HTMLCanvasElement>(null);
  const [toolCtx, setToolCtx] = useState<ToolContext | null>(null);

  // 鍙抽敭鑿滃崟鐘舵€乗n  const [contextMenu, setContextMenu] = useState<{
    x: number;
    y: number;
  } | null>(null);
  const closeContextMenu = () => setContextMenu(null);

  // 杩借釜鏈€鍚庡厜鏍囦綅缃紙鐢ㄤ簬绮樿创瀹氫綅锛塡n  const lastCursorRef = useRef({ x: 0, y: 0 });

  // 鐩戝惉 canvas-render 鑷畾涔変簨浠讹紙鐢?CanvasEditor 宸ュ叿鏍忔寜閽Е鍙戯級
  useEffect(() => {
    const handler = () => {
      needsRender = true;
    };
    window.addEventListener("canvas-render", handler);
    return () => window.removeEventListener("canvas-render", handler);
  }, []);

  // 鏍规嵁褰撳墠宸ュ叿璁剧疆鍏夋爣鏍峰紡
  useEffect(() => {
    const overlayCanvas = overlayRef.current;
    if (!overlayCanvas) return;
    const tool = getTool(state.activeTool);
    overlayCanvas.style.cursor = tool?.cursor || "default";
  }, [state.activeTool]);

  // 闀挎寜鍙栬壊鍣ㄧ姸鎬乗n  const toolBeforeEyedropper = useRef<CanvasTool | null>(null);
  const longPressTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const longPressPos = useRef({ x: 0, y: 0 });

  // 鍒濆鍖?ToolContext锛堝寘鍚笁灞?Canvas 鐨?context 寮曠敤锛塡n  useEffect(() => {
    const iCtx = interactiveRef.current?.getContext("2d") ?? null;
    const oCtx = overlayRef.current?.getContext("2d") ?? null;

    setToolCtx({
      buffer,
      transform,
      state,
      commands,
      setActiveTool,
      interactiveCtx: iCtx,
      overlayCtx: oCtx,
      overlayCanvas: overlayRef.current,
    });
  }, [buffer, transform, state, commands, setActiveTool]);

  // 娓叉煋寰幆: Static 灞備粠 Buffer drawImage锛堢┖闂?rAF锛屼粎鍦?needsRender 鏃舵墽琛岋級
  const rafPending = useRef(false);
  useEffect(() => {
    const render = () => {
      rafPending.current = false;
      needsRender = false;

      const staticCanvas = staticRef.current;
      if (!staticCanvas) return;
      const sCtx = staticCanvas.getContext("2d");
      if (!sCtx) return;

      // Static 灞傦細浠?Buffer drawImage锛堝簲鐢?transform锛塡n      sCtx.resetTransform();
      sCtx.clearRect(0, 0, staticCanvas.width, staticCanvas.height);
      transform.applyTransform(sCtx);
      sCtx.drawImage(buffer.getSource(), 0, 0);

      // 缁樺埗鐢诲竷鑳屾櫙杈圭晫鎸囩ず锛堢櫧鑹茬煩褰㈣竟妗嗭級
      sCtx.strokeStyle = "rgba(255,255,255,0.15)";
      sCtx.lineWidth = 1;
      sCtx.strokeRect(0, 0, buffer.width, buffer.height);

      // Overlay 灞傦細闈為€夊尯宸ュ叿鏃舵竻鐞嗘畫鐣橽n      if (state.activeTool !== "select" && state.activeTool !== "lasso") {
        const overlayCanvas = overlayRef.current;
        if (overlayCanvas) {
          const oCtx = overlayCanvas.getContext("2d");
          if (oCtx)
            oCtx.clearRect(0, 0, overlayCanvas.width, overlayCanvas.height);
        }
      }

      // Interactive 灞傦細闈炵粯鍒跺伐鍏锋椂娓呯悊娈嬬暀锛堢粯鍒跺伐鍏疯嚜琛岀鐞嗚灞傦級
      if (!INTERACTIVE_TOOLS.has(state.activeTool)) {
        const iCanvas = interactiveRef.current;
        if (iCanvas) {
          const iCtx = iCanvas.getContext("2d");
          if (iCtx) iCtx.clearRect(0, 0, iCanvas.width, iCanvas.height);
        }
      }
    };

    // 娓叉煋寰幆锛氶娆℃覆鏌撳悗鎸佺画杞锛屾瘡娆?frame 妫€鏌?needsRender
    const scheduleLoop = () => {
      rafId = requestAnimationFrame(loop);
    };

    const loop = () => {
      if (needsRender && !rafPending.current) {
        rafPending.current = true;
        rafId = requestAnimationFrame(() => {
          rafId = 0;
          render();
          // 娓叉煋瀹屾垚鍚庢棤鏉′欢鎭㈠杞锛岀‘淇濆悗缁?canvas-render / ResizeObserver 淇″彿鑳借鎷惧彇
          rafPending.current = needsRender;
          scheduleLoop();
        });
      } else {
        // needsRender 涓?false 鎴栧凡鏈?render 鎺掗槦锛岀户缁笅涓€甯ц疆璇n        scheduleLoop();
      }
    };
    scheduleLoop();
    return () => {
      if (rafId) cancelAnimationFrame(rafId);
      rafId = 0;
    };
  }, [transform, buffer, state.activeTool]);

  // ResizeObserver + 涓夊眰 Canvas 灏哄鍚屾 + InputAdapter
  useEffect(() => {
    const container = containerRef.current;
    const staticCanvas = staticRef.current;
    const interactiveCanvas = interactiveRef.current;
    const overlayCanvas = overlayRef.current;
    if (!container || !staticCanvas || !interactiveCanvas || !overlayCanvas)
      return;

    const resize = () => {
      const dpr = window.devicePixelRatio || 1;
      transform.dpr = dpr;
      const w = container.clientWidth;
      const h = container.clientHeight;

      // 缁熶竴璁剧疆涓夊眰 Canvas 鐨勫昂瀵竆n      for (const c of [staticCanvas, interactiveCanvas, overlayCanvas]) {
        c.width = w * dpr;
        c.height = h * dpr;
        c.style.width = w + "px";
        c.style.height = h + "px";
      }

      // Interactive 灞傞渶瑕佸簲鐢?transform
      const iCtx = interactiveCanvas.getContext("2d");
      if (iCtx) {
        iCtx.setTransform(dpr, 0, 0, dpr, 0, 0);
      }

      if (state.fitToWindow) transform.fitTo(w, h, state.width, state.height);
      needsRender = true;
    };
    resize();

    const ro = new ResizeObserver(resize);
    ro.observe(container);

    // InputAdapter 鈥斺€?缁熶竴鍦?Overlay 灞傦紙椤跺眰锛夌洃鍚簨浠禱n    const pointerDownRef = { current: false }; // 瀹堝崼锛氬彧鏈夋寜涓嬫椂 onPointerMove 鎵嶈Е鍙戞覆鏌揬n    const clearLongPress = () => {
      if (longPressTimer.current) {
        clearTimeout(longPressTimer.current);
        longPressTimer.current = null;
      }
      if (toolBeforeEyedropper.current) {
        setActiveTool(toolBeforeEyedropper.current);
        toolBeforeEyedropper.current = null;
      }
    };

    const adapter = new InputAdapter(
      overlayCanvas,
      transform,
      {
        onPointerDown: (e) => {
          pointerDownRef.current = true;
          onDrawingChange?.(true);
          if (toolCtx) {
            // Alt+鐐瑰嚮 鈫?涓存椂鍙栬壊鍣╘n            if (e.altKey) {
              const pixel = buffer.getImageData(
                Math.round(e.x),
                Math.round(e.y),
                1,
                1,
              ).data;
              const hex =
                "#" +
                [pixel[0], pixel[1], pixel[2]]
                  .map((v) => v.toString(16).padStart(2, "0"))
                  .join("");
              onStateChange({ fgColor: hex });
              return;
            }
            // 闀挎寜鍙栬壊鍣紙500ms 鏃犵Щ鍔?鈫?鍙栬壊骞舵仮澶嶅師宸ュ叿锛塡n            longPressPos.current = { x: e.x, y: e.y };
            longPressTimer.current = setTimeout(() => {
              toolBeforeEyedropper.current = state.activeTool as CanvasTool;
              const pixel = buffer.getImageData(
                Math.round(longPressPos.current.x),
                Math.round(longPressPos.current.y),
                1,
                1,
              ).data;
              const hex =
                "#" +
                [pixel[0], pixel[1], pixel[2]]
                  .map((v) => v.toString(16).padStart(2, "0"))
                  .join("");
              onStateChange({ fgColor: hex });
              longPressTimer.current = null;
            }, 500);

            const t = getTool(state.activeTool);
            t?.onPointerDown(e, toolCtx);
            needsRender = true;
          }
        },
        onPointerMove: (e) => {
          // 绉诲姩瓒呰繃 5px 鍙栨秷闀挎寜
          const dx = e.x - longPressPos.current.x;
          const dy = e.y - longPressPos.current.y;
          if (Math.abs(dx) > 5 || Math.abs(dy) > 5) {
            if (longPressTimer.current) {
              clearTimeout(longPressTimer.current);
              longPressTimer.current = null;
            }
          }
          lastCursorRef.current = { x: e.x, y: e.y };
          onCursorMove(e.x, e.y);
          if (toolCtx) {
            const t = getTool(state.activeTool);
            t?.onPointerMove(e, toolCtx);
            if (pointerDownRef.current) needsRender = true;
          }
        },
        onPointerUp: (e) => {
          pointerDownRef.current = false;
          onDrawingChange?.(false);
          clearLongPress();
          if (toolCtx) {
            const t = getTool(state.activeTool);
            t?.onPointerUp(e, toolCtx);
            needsRender = true;
          }
        },
      },
      {
        // 鍙屾寚鎹忓悎缂╂斁
        onPinchZoom: (ratio, _cx, _cy) => {
          const z = Math.max(0.1, Math.min(8, transform.zoom * ratio));
          transform.setZoom(z);
          needsRender = true;
        },
        // 鍙屾寚骞崇Щ
        onTwoFingerPan: (dx, dy) => {
          transform.setOffset(transform.offsetX + dx, transform.offsetY + dy);
          needsRender = true;
        },
        // 鍙屽嚮 100%
        onDoubleTap: () => {
          transform.setZoom(1);
          needsRender = true;
        },
      },
    );

    return () => {
      ro.disconnect();
      adapter.destroy();
    };
  }, [transform, buffer, state, toolCtx, onCursorMove]);

  // Canvas context 涓㈠け/鎭㈠淇濇姢
  useEffect(() => {
    const staticCanvas = staticRef.current;
    if (!staticCanvas) return;

    const handleContextLost = (e: Event) => {
      e.preventDefault(); // 闃绘榛樿琛屼负锛屽厑璁稿皾璇曟仮澶峔n    };

    const handleContextRestored = () => {
      // 浠?OffscreenBuffer 鍏ㄩ噺鎭㈠鍒颁富 Canvas
      needsRender = true;
    };

    staticCanvas.addEventListener("contextlost", handleContextLost);
    staticCanvas.addEventListener("contextrestored", handleContextRestored);
    return () => {
      staticCanvas.removeEventListener("contextlost", handleContextLost);
      staticCanvas.removeEventListener(
        "contextrestored",
        handleContextRestored,
      );
    };
  }, []);

  // 蹇嵎閿郴缁焅n  useEffect(() => {
    let spaceDown = false;
    let isComposing = false;

    const handleCompositionStart = () => {
      isComposing = true;
    };
    const handleCompositionEnd = () => {
      isComposing = false;
    };
    window.addEventListener("compositionstart", handleCompositionStart);
    window.addEventListener("compositionend", handleCompositionEnd);

    const handleKey = (e: KeyboardEvent) => {
      // IME 杈撳叆娉曟ā寮忎笅鑷姩璺宠繃鍏ㄥ眬蹇嵎閿甛n      if (isComposing) return;
      // 杈撳叆妗嗗唴涓嶈Е鍙戝揩鎹烽敭
      const tag = (document.activeElement?.tagName || "").toLowerCase();
      if (tag === "input" || tag === "textarea" || tag === "select") return;

      if (e.ctrlKey && e.key === "z") {
        e.preventDefault();
        commands.undo(buffer.ctx);
        needsRender = true;
      } else if (
        e.ctrlKey &&
        (e.key === "y" || (e.shiftKey && e.key === "Z"))
      ) {
        e.preventDefault();
        commands.redo(buffer.ctx);
        needsRender = true;
      }
      // Ctrl+S 鈫?蹇€熷鍑?PNG
      else if (e.ctrlKey && e.key === "s") {
        e.preventDefault();
        onExportShortcut?.();
      }
      // Ctrl+Shift+S 鈫?閫夊尯瀵煎嚭
      else if (e.ctrlKey && e.shiftKey && e.key === "S") {
        e.preventDefault();
        onSelectionExport?.();
      }
      // Ctrl+A 鈫?鍏ㄩ€夌敾甯僜n      else if (e.ctrlKey && e.key === "a") {
        e.preventDefault();
        setActiveTool("select");
        // 寤惰繜涓€甯х瓑寰呭伐鍏锋縺娲诲悗鎵ц鍏ㄩ€塡n        requestAnimationFrame(() => {
          const selTool = getTool("select") as SelectTool;
          if (toolCtx) selTool?.selectAll?.(toolCtx);
        });
      }
      // Ctrl+C/V/X 鍓垏鏉匡紙閫夊尯/濂楃储宸ュ叿婵€娲绘椂锛塡n      else if (
        e.ctrlKey &&
        e.key === "c" &&
        (state.activeTool === "select" || state.activeTool === "lasso")
      ) {
        e.preventDefault();
        const sel = getSelection(state.activeTool);
        if (sel) clipBoard.set(buffer.getImageData(sel.x, sel.y, sel.w, sel.h));
      } else if (
        e.ctrlKey &&
        e.key === "x" &&
        (state.activeTool === "select" || state.activeTool === "lasso")
      ) {
        e.preventDefault();
        const sel = getSelection(state.activeTool);
        if (sel) {
          clipBoard.set(buffer.getImageData(sel.x, sel.y, sel.w, sel.h));
          const before = buffer.getImageData(0, 0, buffer.width, buffer.height);
          buffer.ctx.fillStyle = state.bgColor;
          buffer.ctx.fillRect(sel.x, sel.y, sel.w, sel.h);
          const after = buffer.getImageData(0, 0, buffer.width, buffer.height);
          commands.execute({
            type: "selection",
            bbox: { x: 0, y: 0, w: buffer.width, h: buffer.height },
            before,
            after,
            apply: (c) => {
              c.putImageData(after, 0, 0);
            },
            revert: (c) => {
              c.putImageData(before, 0, 0);
            },
          });

          // 娓呴櫎 overlay 閫夊尯妗嗘畫鐣橽n          const oCanvas = overlayRef.current;
          if (oCanvas) {
            const oCtx = oCanvas.getContext("2d");
            if (oCtx) oCtx.clearRect(0, 0, oCanvas.width, oCanvas.height);
          }

          needsRender = true;
        }
      } else if (e.ctrlKey && e.key === "v" && clipBoard.has()) {
        e.preventDefault();
        const data = clipBoard.get()!;
        // 绮樿创鍒板厜鏍囦綅缃紙濡傛灉娌℃湁绉诲姩杩囧厜鏍囧垯灞呬腑锛塡n        const cursor = lastCursorRef.current;
        const px = Math.max(
          0,
          Math.min(
            buffer.width - data.width,
            Math.round(cursor.x - data.width / 2),
          ),
        );
        const py = Math.max(
          0,
          Math.min(
            buffer.height - data.height,
            Math.round(cursor.y - data.height / 2),
          ),
        );
        const before = buffer.getImageData(px, py, data.width, data.height);
        buffer.ctx.putImageData(data, px, py);
        const after = buffer.getImageData(px, py, data.width, data.height);
        commands.execute({
          type: "selection",
          bbox: { x: px, y: py, w: data.width, h: data.height },
          before,
          after,
          apply: (c) => {
            c.putImageData(after, px, py);
          },
          revert: (c) => {
            c.putImageData(before, px, py);
          },
        });
        needsRender = true;
      } else if (e.key === "b" || e.key === "p") setActiveTool("pencil");
      else if (e.key === "e") setActiveTool("eraser");
      else if (e.key === "l") setActiveTool("line");
      else if (e.key === "a") setActiveTool("arrow");
      else if (e.key === "r") setActiveTool("rect");
      else if (e.key === "u") setActiveTool("roundedRect");
      else if (e.key === "o") setActiveTool("ellipse");
      else if (e.key === "y") setActiveTool("polygon");
      else if (e.key === "s") setActiveTool("star");
      else if (e.key === "g") setActiveTool("fill");
      else if (e.key === "t") setActiveTool("text");
      else if (e.key === "i") setActiveTool("eyedropper");
      else if (e.key === "h") setActiveTool("pan");
      else if (e.key === "v") setActiveTool("select");
      else if (e.key === "m") setActiveTool("lasso");
      else if (e.key === " ") {
        spaceDown = true;
        e.preventDefault();
      }
      // Escape 鈫?鍙栨秷閫夊尯 / 鍒囨崲鍥炵敾绗擻n      else if (e.key === "Escape") {
        if (state.activeTool === "select" || state.activeTool === "lasso")
          setActiveTool("pencil");
      }
      // 鏂瑰悜閿?鈫?寰皟閫夊尯锛?px / Shift+10px锛塡n      else if (
        ["ArrowUp", "ArrowDown", "ArrowLeft", "ArrowRight"].includes(e.key) &&
        (state.activeTool === "select" || state.activeTool === "lasso")
      ) {
        const sel = getSelection(state.activeTool);
        if (sel && sel.w > 0 && sel.h > 0) {
          const step = e.shiftKey ? 10 : 1;
          let dx = 0,
            dy = 0;
          if (e.key === "ArrowLeft") dx = -step;
          if (e.key === "ArrowRight") dx = step;
          if (e.key === "ArrowUp") dy = -step;
          if (e.key === "ArrowDown") dy = step;

          const nx = Math.max(0, Math.min(buffer.width - sel.w, sel.x + dx));
          const ny = Math.max(0, Math.min(buffer.height - sel.h, sel.y + dy));
          if (nx === sel.x && ny === sel.y) return; // 鏃犵Щ鍔╘n
          const selectedPixels = buffer.getImageData(
            sel.x,
            sel.y,
            sel.w,
            sel.h,
          );
          const before = buffer.getImageData(0, 0, buffer.width, buffer.height);
          buffer.ctx.fillStyle = state.bgColor;
          buffer.ctx.fillRect(sel.x, sel.y, sel.w, sel.h);
          buffer.ctx.putImageData(selectedPixels, nx, ny);
          const after = buffer.getImageData(0, 0, buffer.width, buffer.height);

          commands.execute({
            type: "selection",
            bbox: { x: 0, y: 0, w: buffer.width, h: buffer.height },
            before,
            after,
            apply: (c) => {
              c.putImageData(after, 0, 0);
            },
            revert: (c) => {
              c.putImageData(before, 0, 0);
            },
          });
          // 娓呴櫎 overlay 鏃т綅缃€夊尯妗哱n          const oCanvas = overlayRef.current;
          if (oCanvas) {
            const oCtx = oCanvas.getContext("2d");
            if (oCtx) oCtx.clearRect(0, 0, oCanvas.width, oCanvas.height);
          }
          needsRender = true;
        }
        e.preventDefault();
      }
      // Delete 鈫?浠呮竻闄ら€夊尯鍐呭
      else if (
        e.key === "Delete" &&
        (state.activeTool === "select" || state.activeTool === "lasso")
      ) {
        const sel = getSelection(state.activeTool);
        if (sel && sel.w > 0 && sel.h > 0) {
          const before = buffer.getImageData(sel.x, sel.y, sel.w, sel.h);
          buffer.ctx.fillStyle = state.bgColor;
          buffer.ctx.fillRect(sel.x, sel.y, sel.w, sel.h);
          const after = buffer.getImageData(sel.x, sel.y, sel.w, sel.h);
          commands.execute({
            type: "selection",
            bbox: { x: sel.x, y: sel.y, w: sel.w, h: sel.h },
            before,
            after,
            apply: (c) => {
              c.putImageData(after, sel.x, sel.y);
            },
            revert: (c) => {
              c.putImageData(before, sel.x, sel.y);
            },
          });

          // 娓呴櫎 overlay 閫夊尯妗嗘畫鐣橽n          const oCanvas = overlayRef.current;
          if (oCanvas) {
            const oCtx = oCanvas.getContext("2d");
            if (oCtx) oCtx.clearRect(0, 0, oCanvas.width, oCanvas.height);
          }

          needsRender = true;
        }
      } else if (e.key === "[")
        onStateChange({ strokeWidth: Math.max(1, state.strokeWidth - 1) });
      else if (e.key === "]")
        onStateChange({ strokeWidth: Math.min(20, state.strokeWidth + 1) });
      // Ctrl+= / Ctrl+- 姝ヨ繘缂╂斁锛圸OOM_STEPS 11 妗ｏ級
      else if (e.ctrlKey && (e.key === "=" || e.key === "+")) {
        e.preventDefault();
        const idx = findZoomStep(transform.zoom);
        transform.setZoom(ZOOM_STEPS[Math.min(ZOOM_STEPS.length - 1, idx + 1)]);
        needsRender = true;
      } else if (e.ctrlKey && e.key === "-") {
        e.preventDefault();
        const idx = findZoomStep(transform.zoom);
        transform.setZoom(ZOOM_STEPS[Math.max(0, idx - 1)]);
        needsRender = true;
      } else if (e.ctrlKey && e.key === "0") {
        e.preventDefault();
        transform.setZoom(1);
        needsRender = true;
      }
    };

    const handleKeyUp = (e: KeyboardEvent) => {
      if (e.key === " ") spaceDown = false;
    };

    // 婊氳疆缂╂斁 + Space 骞崇Щ
    const handleWheel = (e: WheelEvent) => {
      if (spaceDown) {
        transform.setOffset(
          transform.offsetX - e.deltaX,
          transform.offsetY - e.deltaY,
        );
        needsRender = true;
      } else {
        const z = transform.zoom * (e.deltaY > 0 ? 0.9 : 1.1);
        transform.setZoom(z);
        needsRender = true;
      }
    };

    window.addEventListener("keydown", handleKey);
    window.addEventListener("keyup", handleKeyUp);
    const container = containerRef.current;
    if (container)
      container.addEventListener("wheel", handleWheel, { passive: false });

    return () => {
      window.removeEventListener("keydown", handleKey);
      window.removeEventListener("keyup", handleKeyUp);
      window.removeEventListener("compositionstart", handleCompositionStart);
      window.removeEventListener("compositionend", handleCompositionEnd);
      if (container) container.removeEventListener("wheel", handleWheel);
    };
  }, [
    commands,
    buffer,
    state.strokeWidth,
    setActiveTool,
    onStateChange,
    transform,
  ]);

  // 鎷栨嫿瀵煎叆鍥剧墖
  useEffect(() => {
    const container = containerRef.current;
    if (!container || !onLoadImage) return;

    const handleDragOver = (e: DragEvent) => {
      e.preventDefault();
      if (e.dataTransfer) e.dataTransfer.dropEffect = "copy";
    };

    const handleDrop = (e: DragEvent) => {
      e.preventDefault();
      const file = e.dataTransfer?.files?.[0];
      if (file && file.type.startsWith("image/")) {
        onLoadImage(file);
      }
    };

    container.addEventListener("dragover", handleDragOver);
    container.addEventListener("drop", handleDrop);
    return () => {
      container.removeEventListener("dragover", handleDragOver);
      container.removeEventListener("drop", handleDrop);
    };
  }, [onLoadImage]);

  // 鍙抽敭涓婁笅鏂囪彍鍗昞n  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const handleContextMenu = (e: MouseEvent) => {
      e.preventDefault();
      setContextMenu({ x: e.clientX, y: e.clientY });
    };

    // 鐐瑰嚮澶栭儴鍏抽棴鑿滃崟
    const handleClick = () => {
      if (contextMenu) closeContextMenu();
    };

    container.addEventListener("contextmenu", handleContextMenu);
    document.addEventListener("click", handleClick);
    return () => {
      container.removeEventListener("contextmenu", handleContextMenu);
      document.removeEventListener("click", handleClick);
    };
  }, [contextMenu]);

  return (
    <div
      ref={containerRef}
      className="flex-1 relative overflow-hidden bg-gray-950"
      style={{
        backgroundImage:
          "linear-gradient(45deg, #1a1a2e 25%, transparent 25%), linear-gradient(-45deg, #1a1a2e 25%, transparent 25%), linear-gradient(45deg, transparent 75%, #1a1a2e 75%), linear-gradient(-45deg, transparent 75%, #1a1a2e 75%)",
        backgroundSize: "16px 16px",
        backgroundPosition: "0 0, 0 8px, 8px -8px, -8px 0",
      }}
    >
      {/* Static 灞?鈥?浠?Buffer 娓叉煋锛堝簳閮級 */}
      <canvas ref={staticRef} className="absolute inset-0 z-0" />

      {/* Interactive 灞?鈥?褰㈢姸棰勮锛堜腑闂达紝搴旂敤 transform锛?*/}
      <canvas
        ref={interactiveRef}
        className="absolute inset-0 z-10 pointer-events-none"
      />

      {/* Overlay 灞?鈥?閫夊尯妗?鏂囧瓧缂栬緫妗嗭紙椤堕儴锛屽儚绱犲榻愶紝鎺ユ敹浜嬩欢锛?*/}
      <canvas
        ref={overlayRef}
        className="absolute inset-0 z-20"
        tabIndex={0}
        role="img"
        aria-label="鐢诲竷缂栬緫鍣╘

