import { CanvasEditor } from "../image/canvas-editor/components/CanvasEditor";
import type { CanvasEditorHandle } from "../image/canvas-editor/components/CanvasEditor";
import { CanvasErrorBoundary } from "../image/canvas-editor/components/CanvasErrorBoundary";

type EditLayerPhase = "loading" | "ready" | "saving" | "error";

interface Props {
  imageUrl: string;
  imageId: string;
  onClose: () => void;
  /** 淇濆瓨鎴愬姛鍥炶皟锛堢敤浜?Toast 绛夊閮ㄥ弽棣堬級 */
  onSaveSuccess?: () => void;
}

export const EditLayer: React.FC<Props> = ({
  imageUrl,
  imageId,
  onClose,
  onSaveSuccess,
}) => {
  const [phase, setPhase] = useState<EditLayerPhase>("loading");
  const [error, setError] = useState<string | null>(null);
  const [hasUnsaved, setHasUnsaved] = useState(false);
  const [retryKey, setRetryKey] = useState(0); // 寮哄埗 CanvasEditor 閲嶆寕杞絓n  const savingRef = useRef(false); // 闃查噸鍏ラ攣
  const hasUnsavedRef = useRef(false); // StrictMode 鍏煎
  const editorRef = useRef<CanvasEditorHandle>(null); // CanvasEditor ref锛圕trl+S 璋冪敤 triggerSave锛塡n
  // 鍚屾 hasUnsaved 鍒?ref
  useEffect(() => {
    hasUnsavedRef.current = hasUnsaved;
  }, [hasUnsaved]);

  // CORS 棰勬 鈥?鐢?fetch + createImageBitmap锛堟瘮 new Image() 鏇存棭鏆撮湶璺ㄥ煙闂锛塡n  useEffect(() => {
    let cancelled = false;
    fetch(imageUrl, { mode: "cors" })
      .then((res) => {
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        return res.blob();
      })
      .then((blob) => {
        if (cancelled) return;
        return createImageBitmap(blob);
      })
      .then(() => {
        if (!cancelled) setPhase("ready");
      })
      .catch(() => {
        if (!cancelled) {
          setPhase("error");
          setError("鏃犳硶鍔犺浇鍥剧墖锛堣法鍩熼檺鍒讹級锛岃鑱旂郴绠＄悊鍛橀厤缃?CORS 澶碶

flex flex-col items-center gap-1 w-16\"\:
";
      }
    };
    window.addEventListener("beforeunload", handleBeforeUnload);

    // 蹇嵎閿甛n    const handleKeyDown = (e: KeyboardEvent) => {
      // saving 鐘舵€佷笅绂佺敤鎵€鏈夊揩鎹烽敭
      if (phase === "saving") {
        e.preventDefault();
        return;
      }
      if (e.key === "s" && (e.ctrlKey || e.metaKey)) {
        e.preventDefault();
        editorRef.current?.triggerSave();
      }
      if (e.key === "Escape") {
        e.preventDefault();
        handleClose();
      }
    };
    window.addEventListener("keydown", handleKeyDown);

    // 閿佸畾 body 婊氬姩
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";

    return () => {
      window.removeEventListener("beforeunload", handleBeforeUnload);
      window.removeEventListener("keydown", handleKeyDown);
      document.body.style.overflow = prev;
    };
  }, [hasUnsaved, phase]);

  // 鍏抽棴锛堝甫鏈繚瀛樻娴嬶級
  const handleClose = useCallback(() => {
    if (hasUnsaved) {
      const confirmed = window.confirm("鏈夋湭淇濆瓨鐨勬洿鏀癸紝纭畾閫€鍑猴紵");
      if (!confirmed) return;
    }
    onClose();
  }, [hasUnsaved, onClose]);

  // 鏍煎紡妫€娴嬶細浼樺厛浠?Content-Type 鎺ㄦ柇锛孶RL 鎵╁睍鍚嶄綔涓?fallback
  const detectFormat = useCallback(async (url: string): Promise<string> => {
    try {
      const head = await fetch(url, { method: "HEAD" });
      const ct = head.headers.get("content-type") || "";
      if (ct.includes("png")) return "png";
      if (ct.includes("jpeg") || ct.includes("jpg")) return "jpg";
      if (ct.includes("webp")) return "webp";
    } catch {
      /* HEAD 澶辫触锛宖allback 鍒?URL 姝ｅ垯 */
    }
    return url.match(/\.(\w+)(\?|$)/)?.[1] || "png";
  }, []);

  // 淇濆瓨锛堝惈 toBlob null 妫€鏌ャ€侀槻閲嶅叆閿併€佹牸寮忎繚鎸併€佽秴鏃躲€佹渶灏忓欢杩燂級
  const handleSave = useCallback(
    async (blob: Blob | null) => {
      // 闃查噸鍏ラ攣锛氳繛鎸?Ctrl+S 鍙墽琛岀涓€娆n      if (savingRef.current) return;
      savingRef.current = true;

      // null 妫€鏌n      if (!blob) {
        savingRef.current = false;
        setPhase("error");
        setError("鐢诲竷瀵煎嚭澶辫触锛岃閲嶈瘯鎴栬仈绯荤鐞嗗憳");
        return;
      }

      setPhase("saving");
      try {
        const format = await detectFormat(imageUrl);
        // 瀹夊叏杩囨护锛氫粎鍏佽宸茬煡鍥剧墖鏍煎紡
        if (!["png", "jpg", "jpeg", "webp"].includes(format))
          throw new Error(`涓嶆敮鎸佺殑鏍煎紡: ${format}`);

        const formData = new FormData();
        const newName = `${imageId}_edited_${Date.now()}.${format}`;
        formData.append("file", blob, newName);
        formData.append("sourceImageId", imageId);

        // 30s 瓒呮椂
        const controller = new AbortController();
        const timeout = setTimeout(() => controller.abort(), 30000);

        // 鏈€灏戞樉绀?500ms saving 鐘舵€侊紙闃查棯鐑侊級
        const [result] = await Promise.all([
          fetch("/v1/images/upload", {
            method: "POST",
            body: formData,
            signal: controller.signal,
          }),
          new Promise((r) => setTimeout(r, 500)),
        ]);
        clearTimeout(timeout);

        if (!result.ok) {
          throw new Error(`涓婁紶澶辫触: ${result.status}`);
        }

        setPhase("ready");
        setHasUnsaved(false);
        savingRef.current = false;
        onSaveSuccess?.();
        onClose();
        // 澶栭儴璐熻矗 refreshGallery() + toast
      } catch (e) {
        savingRef.current = false;
        setPhase("error");
        if (e instanceof DOMException && e.name === "AbortError") {
          setError("淇濆瓨瓒呮椂锛岃妫€鏌ョ綉缁滃悗閲嶈瘯");
        } else {
          setError(e instanceof Error ? e.message : "淇濆瓨澶辫触");
        }
      }
    },
    [imageUrl, imageId, detectFormat, onClose],
  );

  // CanvasEditor 鍐呴儴淇濆瓨瑙﹀彂锛堢敱 Ctrl+S 鎴栧伐鍏锋爮鎸夐挳瑙﹀彂锛塡n  const handleEditorSave = useCallback(
    async (blob: Blob | null) => {
      await handleSave(blob);
    },
    [handleSave],
  );

  // 閬僵鐐瑰嚮 = 瑙﹀彂鍏抽棴妫€娴媆n  const handleOverlayClick = useCallback(
    (e: React.MouseEvent) => {
      if (e.target === e.currentTarget) handleClose();
    },
    [handleClose],
  );

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/80"
      onClick={handleOverlayClick}
    >
      {/* loading */}
      {phase === "loading" && (
        <div className="flex flex-col items-center gap-3 text-white">
          <div className="w-8 h-8 border-2 border-white/30 border-t-white rounded-full animate-spin" />
          <div className="text-lg">姝ｅ湪鍔犺浇鍥剧墖...</div>
        </div>
      )}

      {/* error */}
      {phase === "error" && (
        <div className="flex flex-col items-center gap-4 text-white">
          <div className="text-red-400 text-lg">{error}</div>
          <div className="flex gap-3">
            <button
              onClick={onClose}
              className="px-4 py-2 rounded bg-gray-700 hover:bg-gray-600 border-0 cursor-pointer text-gray-300"
            >
              鍏抽棴
            </button>
            <button
              onClick={() => {
                setPhase("loading");
                setRetryKey((k) => k + 1);
              }}
              className="px-4 py-2 rounded bg-blue-700/40 hover:bg-blue-600/40 border-0 cursor-pointer text-blue-200"
            >
              閲嶈瘯
            </button>
          </div>
        </div>
      )}

      {/* ready */}
      {phase === "ready" && (
        <CanvasErrorBoundary>
          <CanvasEditor
            ref={editorRef}
            key={retryKey}
            src={imageUrl}
            canvasId={imageId}
            containerHeight="h-full max-h-[calc(100vh-4rem)]"
            onSave={handleEditorSave}
            onCancel={handleClose}
            onDirty={setHasUnsaved}
          />
        </CanvasErrorBoundary>
      )}

      {/* saving */}
      {phase === "saving" && (
        <div className="absolute inset-0 z-10 flex items-center justify-center bg-black/50">
          <div className="flex flex-col items-center gap-3 text-white">
            <div className="w-8 h-8 border-2 border-white/30 border-t-white rounded-full animate-spin" />
            <div className="text-lg">姝ｅ湪淇濆瓨...</div>
          </div>
        </div>
      )}
    </div>
  );
};

