/**
 * MasonryGallery 鈥?Phase 2 鐎戝竷娴佺敾寤婏紙闆朵緷璧栵紝瀵规爣 Copilot锛塡n *
 * 鏍稿績绛栫暐锛歕n *   - CSS columns 瀹炵幇鐎戝竷娴佽嚜閫傚簲鍒楀
 *   - IntersectionObserver 瀹炵幇鏃犻檺婊氬姩
 *   - content-visibility: auto 鍐呯疆娓叉煋浼樺寲
 *   - video_card_margin 璁＄畻 uiAspectRatio 闃叉甯冨眬涓嶉綈
 */

import React, { useRef, useEffect, useState } from "react";
import type { GalleryItem } from "../../../stores/mediaStore";
import { ActionMenu } from "./ActionMenu";
import { getCachedThumb, generateAndCacheThumb } from "./thumbCache";

interface Props {
  items: GalleryItem[];
  selectedId: string | null;
  hasMore: boolean;
  loading: boolean;
  isDark: boolean;
  onSelect: (id: string) => void;
  onLoadMore: () => void;
  /** 缂栬緫閿侊細true 鏃剁鐢?onClick */
  disabled?: boolean;
  /** 婊氬姩瀹瑰櫒 ref锛堜緵澶栭儴淇濆瓨/鎭㈠婊氬姩浣嶇疆锛?*/
  scrollRef?: React.Ref<HTMLDivElement>;
}

/**
 * 甯︾缉鐣ュ浘缂撳瓨鐨勫浘鐗囩粍浠禱n * 棣栨鍔犺浇鍚庣紦瀛樹负 base64锛屽悗缁闂洿鎺ヨ缂撳瓨
 */
const CachedImage: React.FC<{
  src: string;
  alt: string;
  aspectRatio: string;
  className?: string;
}> = ({ src, alt, aspectRatio, className }) => {
  const [imgSrc, setImgSrc] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;

    // 鍏堟煡缂撳瓨
    const cached = getCachedThumb(src);
    if (cached) {
      setImgSrc(cached);
      return;
    }

    // 寮傛鐢熸垚骞剁紦瀛榎n    generateAndCacheThumb(src).then((dataUrl) => {
      if (!cancelled) setImgSrc(dataUrl);
    });

    return () => {
      cancelled = true;
    };
  }, [src]);

  return (
    <img
      src={imgSrc || src}
      alt={alt}
      loading={imgSrc ? undefined : "lazy"}
      className={className || "w-full"}
      style={{ aspectRatio }}
    />
  );
};

/**
 * 鐎戝竷娴佺敾寤奬n *
 * 浣跨敤 CSS columns 瀹炵幇鑷姩鍒嗗垪 + IntersectionObserver 瀹炵幇瑙﹀簳鍔犺浇
 */
export const MasonryGallery: React.FC<Props> = ({
  items,
  selectedId,
  hasMore,
  loading,
  isDark,
  onSelect,
  onLoadMore,
  disabled = false,
  scrollRef,
}) => {
  const sentinelRef = useRef<HTMLDivElement>(null);
  const [hoveredId, setHoveredId] = useState<string | null>(null);
  const preventImmediateRef = useRef(false);

  // 鏃犻檺婊氬姩锛氳瀵?sentinel 瑙﹀簳
  useEffect(() => {
    const sentinel = sentinelRef.current;
    if (!sentinel || !hasMore) return;

    // loading 鈫?false 鏃剁煭鏆傚喎鍗达紝闃叉 observer 閲嶅缓鍚庣珛鍗宠Е鍙慭n    if (preventImmediateRef.current) {
      const timer = setTimeout(() => {
        preventImmediateRef.current = false;
      }, 300);
      return () => clearTimeout(timer);
    }

    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting && hasMore && !loading) {
          preventImmediateRef.current = true;
          onLoadMore();
        }
      },
      { root: sentinel.parentElement, rootMargin: "200px" },
    );

    observer.observe(sentinel);
    return () => observer.disconnect();
  }, [hasMore, loading, onLoadMore]);

  return (
    <div className="h-full overflow-y-auto p-3 pb-20" ref={scrollRef}>
      <div
        className="columns-2 md:columns-3 lg:columns-4"
        style={{ columnGap: 8 }}
      >
        {items.map((item) => {
          const selected = selectedId === item.id;
          const hovered = hoveredId === item.id;

          return (
            <div
              key={item.id}
              onClick={() => !disabled && onSelect(item.id)}
              onMouseEnter={() => setHoveredId(item.id)}
              onMouseLeave={() => setHoveredId(null)}
              className="group relative mb-2 cursor-pointer overflow-hidden rounded-lg border-2 transition-all"
              style={{
                breakInside: "avoid" as any,
                contentVisibility: "auto",
                containIntrinsicSize: "auto 200px",
                borderColor: selected
                  ? "#3b82f6"
                  : hovered
                    ? isDark
                      ? "#93c5fd"
                      : "#93c5fd"
                    : "transparent",
                boxShadow: selected ? "0 2px 8px rgba(59,130,246,0.3)" : "none",
              }}
            >
              {/* 濯掍綋瀹瑰櫒锛歱adding-bottom 淇濇寔鍘熺敓姣斾緥 */}
              <div className="relative w-full overflow-hidden bg-gray-100 dark:bg-gray-800">
                {item.type === "video" ? (
                  <video
                    src={item.url}
                    muted
                    loop
                    playsInline
                    className="w-full"
                    style={{ aspectRatio: "16/9" }}
                    onMouseEnter={(e) => e.currentTarget.play()}
                    onMouseLeave={(e) => {
                      e.currentTarget.pause();
                      e.currentTarget.currentTime = 0;
                    }}
                    preload="auto"
                    onLoadedData={(e) => {
                      // 鍔犺浇瀹屾垚鍚?seek 鍒扮 0.1 绉掓姄鍙栫缉鐣ュ浘甯n                      const video = e.currentTarget as HTMLVideoElement;
                      video.currentTime = 0.1;
                    }}
                  />
                ) : (
                  <CachedImage
                    src={item.thumbnailUrl || item.url}
                    alt={item.alt || ""}
                    aspectRatio={
                      item.width && item.height
                        ? `${item.width}/${item.height}`
                        : "1/1"
                    }
                  />
                )}
              </div>

              {/* 瑙嗛鏃堕暱鏍囩 */}
              {item.type === "video" && item.duration && (
                <div className="pointer-events-none absolute bottom-1 left-1 flex items-center gap-1 rounded bg-black/60 px-1.5 py-0.5 text-xs text-white">
                  <span>鈻?/span>
                  <span>{item.duration}s</span>
                </div>
              )}

              {/* 鎿嶄綔鑿滃崟锛堝浘鐗囧崱鐗囷級 */}
              {item.type === "image" && (selected || hovered) && (
                <ActionMenu
                  itemId={item.id}
                  itemUrl={item.url}
                  itemType={item.type}
                  isDark={isDark}
                />
              )}
            </div>
          );
        })}
      </div>

      {/* 瑙﹀簳鍝ㄥ叺 */}
      <div ref={sentinelRef} className="h-1" />

      {/* 鍔犺浇鎸囩ず鍣?*/}
      {loading && (
        <div className="flex items-center justify-center py-4">
          <span className="text-xs text-gray-400">鍔犺浇鏇村鈥?/span>
        </div>
      )}
    </div>
  );
};

/**
 * CreateDocModal 鈥?鏂囨。鍒涘缓妯℃€佹
 * 鏍规嵁 DocModule 鐘舵€佹樉绀轰笉鍚屽唴瀹癸細
 * - degraded: OfficeCLI 瀹夎寮曞
 * - full: 鏂囨。鍒涘缓琛ㄥ崟锛堝紩瀵煎埌鑱婂ぉ鐣岄潰锛塡n */

import { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { useTranslation } from "react-i18next";
import { officeService } from "../../../services/officeService";
import { useChatStore } from "../../../stores/chat";

interface CreateDocModalProps {
  /** 榛樿鏂囨。绫诲瀷 */
  defaultType?: "docx" | "xlsx" | "pptx";
  onClose: () => void;
}

export default function CreateDocModal({
  defaultType = "docx",
  onClose,
}: CreateDocModalProps) {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const [type, setType] = useState(defaultType);
  const [template, setTemplate] = useState("");
  const [sending, setSending] = useState(false);
  const [statusCheck, setStatusCheck] = useState<
    "loading" | "ready" | "degraded"
  >("loading");

  // 杩涘叆鏃舵鏌?OfficeCLI 鐘舵€乗n  useEffect(() => {
    officeService
      .getDocStatus()
      .then((res) => {
        const installed =
          (res as any)?.data?.data?.officeCliInfo?.installed ||
          (res as any)?.data?.officeCliInfo?.installed;
        setStatusCheck(installed ? "ready" : "degraded");
      })
      .catch(() => setStatusCheck("degraded"));
  }, []);

  /** 閫氳繃 AI 鑱婂ぉ鍒涘缓鏂囨。 */
  async function handleCreate() {
    setSending(true);
    try {
      const prompts: Record<string, string> = {
        docx: "璇峰府鎴戝垱寤轰竴浠芥枃妗ｏ紙.docx锛塡

flex flex-col items-center gap-1 w-16\"\:
${template}"妯℃澘甯垜鍒涘缓涓€浠?{type}鏂囨。`
        : prompts[type] || prompts.docx;
      await useChatStore.getState().sendMessage(prompt);
      onClose();
      navigate("/chat");
    } catch {
      /* ignore */
    } finally {
      setSending(false);
    }
  }

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/50"
      onClick={(e) => {
        if (e.target === e.currentTarget) onClose();
      }}
    >
      <div className="w-[480px] bg-white dark:bg-gray-950 rounded-xl overflow-hidden shadow-2xl">
        {/* 澶撮儴 */}
        <div className="flex items-center justify-between px-5 py-3 border-b border-gray-200 dark:border-gray-700">
          <span className="text-sm font-semibold text-gray-900 dark:text-white">
            {t("office.docCreate", "鍒涘缓鏂囨。")}
          </span>
          <button
            onClick={onClose}
            className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300 text-lg leading-none p-1"
          >
            鉁昞n          </button>
        </div>

        <div className="p-5">
          {statusCheck === "loading" && (
            <div className="text-center py-8 text-gray-400 animate-pulse">
              {t("common.loading", "鍔犺浇涓?..")}
            </div>
          )}

          {statusCheck === "degraded" && (
            <div className="text-center py-4">
              <span className="text-2xl mb-3 block">鈿狅笍</span>
              <p className="text-sm text-amber-800 dark:text-amber-200 font-medium mb-2">
                {t("office.cliNotInstalledTitle", "OfficeCLI 鏈畨瑁匼

text-xs text-amber-700 dark:text-amber-300 mb-4">
                鏂囨。鍒涘缓闇€瑕?OfficeCLI 鍛戒护琛屽伐鍏枫€傝鍦╘n                PowerShell锛堢鐞嗗憳锛変腑杩愯浠ヤ笅鍛戒护瀹夎锛歕n              </p>
              <div className="bg-gray-100 dark:bg-gray-900 rounded-lg p-3 mb-3 text-left">
                <code className="block text-xs text-blue-700 dark:text-blue-300">
                  cd BA_REF\OfficeCLI-main
                </code>
                <code className="block text-xs text-blue-700 dark:text-blue-300">
                  .\install.ps1
                </code>
              </div>
              <button
                onClick={onClose}
                className="px-4 py-2 text-xs bg-amber-600 text-white rounded-lg hover:bg-amber-700 transition-colors"
              >
                {t("common.close", "鍏抽棴")}
              </button>
            </div>
          )}

          {statusCheck === "ready" && (
            <div className="space-y-4">
              <div>
                <label className="block text-xs text-gray-500 dark:text-gray-400 mb-1">
                  {t("office.docType", "鏂囨。绫诲瀷")}
                </label>
                <div className="flex gap-2">
                  {(["docx", "xlsx", "pptx"] as const).map((t) => (
                    <button
                      key={t}
                      onClick={() => setType(t)}
                      className={`flex-1 px-3 py-2 text-sm border rounded-lg transition-colors ${
                        type === t
                          ? "border-blue-500 bg-blue-50 dark:bg-blue-950 text-blue-700 dark:text-blue-300"
                          : "border-gray-200 dark:border-gray-700 text-gray-600 dark:text-gray-400"
                      }`}
                    >
                      .{t}
                    </button>
                  ))}
                </div>
              </div>

              <div>
                <label className="block text-xs text-gray-500 dark:text-gray-400 mb-1">
                  {t("office.docTemplate", "妯℃澘锛堝彲閫夛級")}
                </label>
                <select
                  value={template}
                  onChange={(e) => setTemplate(e.target.value)}
                  className="w-full border border-gray-300 dark:border-gray-700 rounded-lg px-3 py-2 text-sm bg-white dark:bg-gray-900 text-gray-900 dark:text-white"
                >
                  <option value="">鏃犳ā鏉?/option>
                  <option value="鍛ㄦ姤">鍛ㄦ姤</option>
                  <option value="浼氳绾">浼氳绾</option>
                  <option value="鎶€鏈璁

PRD">PRD</option>
                </select>
              </div>

              <div className="flex justify-end gap-2 pt-2">
                <button
                  onClick={onClose}
                  className="px-4 py-2 text-sm text-gray-600 dark:text-gray-400 hover:text-gray-800 dark:hover:text-gray-200"
                >
                  {t("common.cancel", "鍙栨秷")}
                </button>
                <button
                  onClick={handleCreate}
                  disabled={sending}
                  className="px-4 py-2 text-sm bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors disabled:opacity-50"
                >
                  {sending
                    ? t("office.docCreating", "璺宠浆涓?..")
                    : t("office.docCreate", "鍒涘缓鏂囨。")}
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

