/**
 * FileList 鈥?鏂囨。鍒楄〃缁勪欢
 * 铏氭嫙婊氬姩 + 鎼滅储杩囨护 + 涓婁紶鎸夐挳 + hover 鎿嶄綔锛堥噸鍛藉悕/鍒犻櫎锛? 鎷栨嫿
 */

import { useState, useMemo, useCallback } from "react";
import { List } from "react-window";
import { useTranslation } from "react-i18next";
import { useOfficeStore, type FileInfo } from "../../../stores/officeStore";
import { officeApi } from "../../../services/officeApi";

/** 铏氭嫙婊氬姩琛岄珮 */
const ROW_HEIGHT = 44;

/** 鏂囦欢鎵╁睍鍚?鈫?鍥炬爣鏄犲皠 */
const FILE_ICONS: Record<string, string> = {
  docx: "馃搫",
  xlsx: "馃搳",
  pptx: "馃摻锔廫

馃摃",
  html: "馃寪",
};

/** 鏍规嵁鎵╁睍鍚嶈幏鍙栧浘鏍?*/
function getFileIcon(name: string): string {
  const ext = name.split(".").pop()?.toLowerCase() ?? "";
  return FILE_ICONS[ext] ?? "馃搧";
}

export function FileList() {
  const { t } = useTranslation();
  const {
    fileList,
    selectedFile,
    searchQuery,
    filterType,
    selectFile,
    setSearchQuery,
    setFilterType,
    setPreviewState,
    refreshFileList,
  } = useOfficeStore();

  const [hoveredFile, setHoveredFile] = useState<string | null>(null);
  const [renamingFile, setRenamingFile] = useState<string | null>(null);
  const [renameValue, setRenameValue] = useState("");

  /** 鍓嶇杩囨护锛氭悳绱?+ 绫诲瀷 */
  const filteredFiles = useMemo(() => {
    return fileList.filter((f) => {
      if (filterType !== "all" && !f.name.endsWith(`.${filterType}`)) {
        return false;
      }
      if (
        searchQuery &&
        !f.name.toLowerCase().includes(searchQuery.toLowerCase())
      ) {
        return false;
      }
      return true;
    });
  }, [fileList, searchQuery, filterType]);

  /** 鏂囦欢鎷栨嫿寮€濮?*/
  const handleDragStart = useCallback((e: React.DragEvent, file: FileInfo) => {
    e.dataTransfer.setData("text/plain", file.id);
    e.dataTransfer.effectAllowed = "move";
  }, []);

  /** 鏂囦欢鐐瑰嚮 鈫?棰勮 */
  const handleFileClick = useCallback(
    (file: FileInfo) => {
      selectFile(file);
      setPreviewState("loading");
    },
    [selectFile, setPreviewState],
  );

  /** 閿洏瀵艰埅 */
  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent, file: FileInfo) => {
      if (e.key === "Enter") {
        handleFileClick(file);
      }
    },
    [handleFileClick],
  );

  /** 涓婁紶鏂囦欢 */
  const handleUpload = useCallback(async () => {
    const input = document.createElement("input");
    input.type = "file";
    input.accept = ".docx,.xlsx,.pptx,.pdf,.doc,.xls,.ppt";
    input.onchange = async () => {
      const file = input.files?.[0];
      if (!file) return;
      try {
        await officeApi.uploadDoc(file);
        await refreshFileList();
      } catch {
        // 闈欓粯澶辫触
      }
    };
    input.click();
  }, [refreshFileList]);

  /** 鍒犻櫎鏂囦欢 */
  const handleDelete = useCallback(
    async (name: string) => {
      if (!window.confirm(t("office.confirmDelete", "纭畾瑕佸垹闄ゆ鏂囦欢鍚楋紵")))
        return;
      try {
        await officeApi.deleteDoc(name);
        // 鑻ュ綋鍓嶉瑙堟鏂囦欢锛屾竻绌洪瑙圽n        if (selectedFile?.name === name) {
          selectFile(null);
        }
        await refreshFileList();
      } catch {
        // 闈欓粯澶辫触
      }
    },
    [selectedFile, selectFile, refreshFileList, t],
  );

  /** 寮€濮嬮噸鍛藉悕 */
  const handleStartRename = useCallback((file: FileInfo) => {
    setRenamingFile(file.id);
    setRenameValue(file.name);
  }, []);

  /** 纭閲嶅懡鍚?*/
  const handleConfirmRename = useCallback(
    async (oldName: string) => {
      if (renameValue && renameValue !== oldName) {
        try {
          await officeApi.renameDoc(oldName, renameValue);
          await refreshFileList();
        } catch {
          // 闈欓粯澶辫触
        }
      }
      setRenamingFile(null);
      setRenameValue("");
    },
    [renameValue, refreshFileList],
  );

  /** 鏍煎紡鍖栨枃浠跺ぇ灏?*/
  const formatSize = (bytes: number): string => {
    if (bytes < 1024) return `${bytes} B`;
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
    return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
  };

  /** 鍗曡娓叉煋锛坮eact-window锛?*/
  const Row = useCallback(
    ({ index, style }: { index: number; style: React.CSSProperties }) => {
      const file = filteredFiles[index];
      const isSelected = selectedFile?.id === file.id;
      const isHovered = hoveredFile === file.id;
      const isRenaming = renamingFile === file.id;

      return (
        <div
          style={style}
          draggable
          data-file-id={file.id}
          onDragStart={(e) => handleDragStart(e, file)}
          onClick={() => handleFileClick(file)}
          onKeyDown={(e) => handleKeyDown(e, file)}
          onMouseEnter={() => setHoveredFile(file.id)}
          onMouseLeave={() => setHoveredFile(null)}
          role="option"
          aria-selected={isSelected}
          tabIndex={0}
          className={`flex items-center gap-2 px-2 cursor-pointer outline-none
            ${isSelected ? "bg-blue-100 dark:bg-blue-900" : "hover:bg-gray-100 dark:hover:bg-gray-800"}
          `}
        >
          <span className="text-base flex-shrink-0" aria-hidden="true">
            {getFileIcon(file.name)}
          </span>

          {isRenaming ? (
            <input
              autoFocus
              value={renameValue}
              onChange={(e) => setRenameValue(e.target.value)}
              onBlur={() => handleConfirmRename(file.name)}
              onKeyDown={(e) => {
                if (e.key === "Enter") handleConfirmRename(file.name);
                if (e.key === "Escape") {
                  setRenamingFile(null);
                  setRenameValue("");
                }
              }}
              className="flex-1 text-sm px-1 py-0.5 border border-blue-400 rounded bg-white dark:bg-gray-800"
              onClick={(e) => e.stopPropagation()}
            />
          ) : (
            <>
              <span className="flex-1 text-sm truncate text-gray-900 dark:text-white">
                {file.name}
              </span>
              <span className="text-xs text-gray-400 flex-shrink-0">
                {formatSize(file.size)}
              </span>
            </>
          )}

          {/* hover 鎿嶄綔鎸夐挳 */}
          {isHovered && !isRenaming && (
            <div className="flex gap-1 flex-shrink-0">
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  handleStartRename(file);
                }}
                className="px-1.5 py-0.5 text-xs rounded bg-gray-200 dark:bg-gray-700 
                  hover:bg-gray-300 dark:hover:bg-gray-600"
                title={t("office.rename", "閲嶅懡鍚峔

flex flex-col items-center gap-1 w-16\"\:
px-1.5 py-0.5 text-xs rounded bg-gray-200 dark:bg-gray-700 
                  hover:bg-red-200 dark:hover:bg-red-900"
                title={t("office.delete", "鍒犻櫎")}
                aria-label={t("office.delete", "鍒犻櫎")}
              >
                馃棏锔廫n              </button>
            </div>
          )}
        </div>
      );
    },
    [
      filteredFiles,
      selectedFile,
      hoveredFile,
      renamingFile,
      renameValue,
      handleDragStart,
      handleFileClick,
      handleKeyDown,
      handleStartRename,
      handleConfirmRename,
      handleDelete,
    ],
  );

  /** 杩囨护鏍囩鎸夐挳 */
  const filterTypes: Array<{ key: string; label: string }> = [
    { key: "all", label: "鍏ㄩ儴" },
    { key: "docx", label: "馃搫 鏂囨。" },
    { key: "xlsx", label: "馃搳 琛ㄦ牸" },
    { key: "pptx", label: "馃摻锔?婕旂ず" },
  ];

  return (
    <div className="flex flex-col h-full">
      {/* 鎼滅储妗?+ 杩囨护鏍囩 */}
      <div className="px-2 space-y-2">
        <input
          type="text"
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          placeholder={t("office.searchFiles", "鎼滅储鏂囦欢...")}
          aria-label={t("office.searchFiles", "鎼滅储鏂囦欢")}
          className="w-full px-2 py-1.5 text-sm border border-gray-200 dark:border-gray-700 
            rounded-lg bg-white dark:bg-gray-800 text-gray-900 dark:text-white 
            placeholder-gray-400 focus:outline-none focus:ring-1 focus:ring-blue-400"
        />

        <div className="flex gap-1 flex-wrap">
          {filterTypes.map((ft) => (
            <button
              key={ft.key}
              onClick={() => setFilterType(ft.key)}
              className={`px-2 py-0.5 text-xs rounded-full transition-colors
                ${
                  filterType === ft.key
                    ? "bg-blue-600 text-white"
                    : "bg-gray-100 dark:bg-gray-800 text-gray-600 dark:text-gray-400 hover:bg-gray-200 dark:hover:bg-gray-700"
                }
              `}
              aria-pressed={filterType === ft.key}
            >
              {ft.label}
            </button>
          ))}
        </div>

        {/* 涓婁紶鎸夐挳 */}
        <button
          onClick={handleUpload}
          className="w-full px-2 py-1.5 text-sm border border-dashed border-gray-300 
            dark:border-gray-600 rounded-lg text-gray-500 dark:text-gray-400 
            hover:border-blue-400 hover:text-blue-600 transition-colors"
          aria-label={t("office.uploadFile", "涓婁紶鏂囦欢")}
        >
          + {t("office.uploadFile", "涓婁紶鏂囦欢")}
        </button>
      </div>

      {/* 鏂囦欢鍒楄〃锛堣櫄鎷熸粴鍔級 */}
      <div
        className="flex-1 mt-2"
        role="listbox"
        aria-label={t("office.fileList", "鏂囦欢鍒楄〃")}
      >
        {filteredFiles.length === 0 ? (
          <p className="text-xs text-center text-gray-400 dark:text-gray-500 py-4">
            {searchQuery
              ? t("office.noSearchResults", "鏃犲尮閰嶆枃浠禱

office.noFiles", "鏆傛棤鏂囦欢")}
          </p>
        ) : (
          <div style={{ height: 300, width: "100%" }}>
            <List
              rowCount={filteredFiles.length}
              rowHeight={ROW_HEIGHT}
              rowComponent={Row as any}
              rowProps={{} as any}
            />
          </div>
        )}
      </div>
    </div>
  );
}

