export function useVideoTaskPolling(
  onTaskCompleted?: (taskId: string) => void,
) {
  const activeTasks = useMediaStore((s) => s.activeTasks);
  const updateTask = useMediaStore((s) => s.updateTask);
  const addTask = useMediaStore((s) => s.addTask);
  const setActiveTasks = useMediaStore((s) => s.setActiveTasks);

  const timers = useRef<Map<string, ReturnType<typeof setInterval>>>(new Map());

  /** 鎭㈠椤甸潰鍒锋柊鍓嶇殑娲昏穬浠诲姟 */
  const restoreActiveTasks = useCallback(async () => {
    try {
      const response = await videoService.listVideoTasks({
        status: "active",
        limit: 20,
      });

      if (response.tasks && response.tasks.length > 0) {
        const mapped: VideoTaskItem[] = response.tasks.map((t: any) => ({
          taskId: t.taskId,
          status: t.status,
          mode: t.mode || "text-to-video",
          progress: t.progress || 0,
          sourceImageUrl: t.sourceImageUrl || null,
          resultVideoUrl: t.resultVideoUrl || null,
          prompt: t.prompt || "",
          error: t.error || null,
          createdAt: t.createdAt,
          completedAt: t.completedAt || null,
        }));
        setActiveTasks(mapped);
        logger.info("鎭㈠娲昏穬浠诲姟", { count: mapped.length });
      }
    } catch (e) {
      handleClientError(
        e,
        { module: "hooks:useVideoTaskPolling", action: "restoreActiveTasks" },
        "warn",
      );
    }
  }, [setActiveTasks]);

  /** 鍋滄杞鍗曚釜浠诲姟 */
  const stopPolling = useCallback((taskId: string) => {
    const timer = timers.current.get(taskId);
    if (timer) {
      clearInterval(timer);
      timers.current.delete(taskId);
    }
  }, []);

  /** 杞鍗曚釜浠诲姟 */
  const pollTask = useCallback(
    async (taskId: string) => {
      try {
        const response = await videoService.getVideoTask(taskId);

        if (response) {
          updateTask(taskId, {
            status: response.status,
            progress: response.progress || 0,
            resultVideoUrl: response.resultVideoUrl || null,
            error: response.error || null,
            completedAt: response.completedAt || null,
          });

          // 瀹屾垚鎴栧け璐ユ椂鍋滄杞
          if (response.status === "completed" || response.status === "failed") {
            stopPolling(taskId);
            // 閫氱煡澶栭儴锛堝鍒锋柊鐢诲粖锛塡n            if (response.status === "completed" && onTaskCompleted) {
              onTaskCompleted(taskId);
            }
          }
        }
      } catch (e) {
        logger.warn("杞浠诲姟澶辫触", { taskId, error: String(e) });
      }
    },
    [updateTask, stopPolling, onTaskCompleted],
  );

  /** 寮€濮嬭疆璇㈠崟涓换鍔?*/
  const startPolling = useCallback(
    (taskId: string) => {
      if (timers.current.has(taskId)) return;

      const timer = setInterval(() => {
        pollTask(taskId);
      }, POLL_INTERVAL);

      timers.current.set(taskId, timer);
    },
    [pollTask],
  );

  /** 娣诲姞鏂颁换鍔″苟寮€濮嬭疆璇?*/
  const submitTask = useCallback(
    (taskId: string) => {
      addTask({
        taskId,
        status: "pending",
        mode: "text-to-video",
        progress: 0,
        sourceImageUrl: null,
        resultVideoUrl: null,
        prompt: "",
        error: null,
        createdAt: new Date().toISOString(),
        completedAt: null,
      });
      startPolling(taskId);
    },
    [addTask, startPolling],
  );

  // 鈹€鈹€鈹€鈹€ Effects 鈹€鈹€鈹€鈹€

  // 鍚姩鏃舵仮澶嶆椿璺冧换鍔n  useEffect(() => {
    restoreActiveTasks();
  }, [restoreActiveTasks]);

  // 娲昏穬浠诲姟鍙樺寲鏃讹紝鑷姩涓烘湭杞鐨勪换鍔″惎鍔ㄨ疆璇n  useEffect(() => {
    activeTasks
      .filter((t) => ACTIVE_STATUSES.includes(t.status))
      .forEach((t) => {
        if (!timers.current.has(t.taskId)) {
          startPolling(t.taskId);
        }
      });
  }, [activeTasks, startPolling]);

  // 椤甸潰鍙鎬у彉鍖栨椂鎺у埗杞
  useEffect(() => {
    const onVisibilityChange = () => {
      if (document.hidden) {
        // 鏆傚仠鎵€鏈夎疆璇n        timers.current.forEach((timer, taskId) => {
          clearInterval(timer);
          timers.current.delete(taskId);
        });
      } else {
        // 鎭㈠娲昏穬浠诲姟鐨勮疆璇n        const store = useMediaStore.getState();
        store.activeTasks
          .filter((t) => ACTIVE_STATUSES.includes(t.status))
          .forEach((t) => {
            startPolling(t.taskId);
          });
      }
    };

    document.addEventListener("visibilitychange", onVisibilityChange);
    return () => {
      document.removeEventListener("visibilitychange", onVisibilityChange);
      // 娓呯悊鎵€鏈夎鏃跺櫒
      timers.current.forEach((timer) => clearInterval(timer));
      timers.current.clear();
    };
  }, [startPolling]);

  return { activeTasks, submitTask, restoreActiveTasks };
}

