/**
 * 澹伴煶鏈嶅姟鈥斺€斾娇鐢?Web Audio API 鐢熸垚鎻愮ず闊砛n *
 * 鑱岃矗锛歕n * - playWarningSound()锛氬嵄闄╂搷浣?闇€瑕佽緭鍏ユ椂鎾斁璀︾ず闊砛n * - playCompletionSound()锛欰I 浠诲姟瀹屾垚鏃舵挱鏀炬彁绀洪煶
 *
 * 瀹归敊锛欰udioContext 涓嶅彲鐢ㄦ椂闈欓粯闄嶇骇 audioAvailable = false锛屾墍鏈?play* 绉掕繑鍥瀄n * 鑺傛祦锛氳绀洪煶 1s 鍐呬笉閲嶅锛屽畬鎴愰煶 3s 鍐呬笉閲嶅
 * 閰嶇疆锛氫粠 useConfigStore 璇诲彇 inputNeededEnabled / taskCompleteEnabled
 */

import { useConfigStore } from "../stores/configStore";
import { createLogger } from "@/utils/logger";
import { handleClientError } from "../utils/handleError";

const logger = createLogger("services:soundService");

/** AudioContext 杩愯鐜鏄惁鍙敤 */
let audioAvailable = true;
let audioCtx: AudioContext | null = null;

/** 璀︾ず闊宠妭娴佹椂闂存埑 */
let lastWarningTime = 0;
const WARNING_THROTTLE_MS = 1000;

/** 瀹屾垚闊宠妭娴佹椂闂存埑 */
let lastCompletionTime = 0;
const COMPLETION_THROTTLE_MS = 3000;

/**
 * 鑾峰彇鎴栧垱寤?AudioContext锛堟噿鍒濆鍖栵級
 * 棣栨澶辫触鍚庢案涔呴檷绾?audioAvailable = false
 */
function getContext(): AudioContext | null {
  try {
    if (!audioCtx) {
      const AC = window.AudioContext || (window as any).webkitAudioContext;
      if (!AC) throw new Error("AudioContext not supported");
      audioCtx = new AC();
    }
    if (audioCtx.state === "suspended") {
      audioCtx.resume();
    }
    return audioCtx;
  } catch (e) {
    handleClientError(e, { module: "services:sound", action: "getContext" });
    logger.warn("AudioContext 涓嶅彲鐢紝闈欓粯闄嶇骇", e);
    audioAvailable = false;
    return null;
  }
}

/** 璇诲彇閫氱煡閰嶇疆涓殑甯冨皵寮€鍏?*/
function isNotificationEnabled(key: string): boolean {
  const config = useConfigStore.getState().config;
  const notifications = config.notifications as
    Record<string, unknown> | undefined;
  if (notifications && typeof notifications[key] === "boolean") {
    return notifications[key] as boolean;
  }
  return true; // 榛樿寮€鍚痋n}

/**
 * 鍗遍櫓鎿嶄綔璀︾ず闊砛n * 鏂瑰舰娉?800Hz锛岀煭淇冨埡鑰充互寮曡捣娉ㄦ剰
 * 鑺傛祦锛? 绉掑唴涓嶉噸澶峔n */
export function playWarningSound(): void {
  if (!audioAvailable) return;
  if (!isNotificationEnabled("inputNeededEnabled")) return;

  const now = Date.now();
  if (now - lastWarningTime < WARNING_THROTTLE_MS) return;
  lastWarningTime = now;

  const ctx = getContext();
  if (!ctx) return;

  const osc = ctx.createOscillator();
  const gain = ctx.createGain();
  osc.type = "square";
  osc.frequency.value = 800;
  gain.gain.setValueAtTime(0.3, ctx.currentTime);
  gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.2);
  osc.connect(gain);
  gain.connect(ctx.destination);
  osc.start(ctx.currentTime);
  osc.stop(ctx.currentTime + 0.2);
}

/**
