/**
 * clipboardService 鈥?璺ㄥ钩鍙板壀璐存澘鍥剧墖璇诲彇鏈嶅姟
 *
 * 鏀寔 Windows (PowerShell)銆乵acOS (osascript)銆丩inux (xclip/wl-paste)
 * 鍙傜収 cc_code backend/utils/imagePaste.ts
 */

import { createLogger } from "@/utils/logger";
import { handleClientError } from "../utils/handleError";

const logger = createLogger("clipboardService");

/** 鍥剧墖璇诲彇缁撴灉 */
export interface ClipboardImageResult {
  /** Base64 缂栫爜鐨勫浘鐗囨暟鎹?*/
  base64: string;
  /** MIME 绫诲瀷 */
  mimeType: string;
  /** 鏁版嵁澶у皬锛堝瓧鑺傦級 */
  size: number;
}

/**
 * 浠庣郴缁熷壀璐存澘璇诲彇鍥剧墖
 * @returns 鍥剧墖鏁版嵁锛屾棤鍥剧墖鏃惰繑鍥?null
 */
export async function readImageFromClipboard(): Promise<ClipboardImageResult | null> {
  try {
    const platform = getPlatform();
    let base64: string | null = null;
    let mimeType = "image/png";

    switch (platform) {
      case "windows":
        base64 = await readFromWindows();
        break;
      case "macos":
        base64 = await readFromMacOS();
        break;
      case "linux":
        base64 = await readFromLinux();
        break;
      default:
        logger.warn("涓嶆敮鎸佺殑骞冲彴:", platform);
        return null;
    }

    if (!base64) return null;

    return {
      base64,
      mimeType,
      size: base64.length,
    };
  } catch (err) {
    handleClientError(err, {
      module: "services:clipboard",
      action: "readImageFromClipboard",
    });
    logger.warn("鍓创鏉胯鍙栧け璐?", err);
    return null;
  }
}

/**
 * 妫€鏌ュ壀璐存澘涓槸鍚︽湁鍥剧墖
 */
export async function hasImageInClipboard(): Promise<boolean> {
  const result = await readImageFromClipboard();
  return result !== null && result.size > 0;
}

/** 鑾峰彇褰撳墠骞冲彴鏍囪瘑 */
function getPlatform(): string {
  // Tauri 鐜涓嬩娇鐢?window.__TAURI__ 鍒ゆ柇锛屽惁鍒欑敤 navigator
  if (typeof navigator !== "undefined") {
    const ua = navigator.userAgent || "";
    if (ua.includes("Win")) return "windows";
    if (ua.includes("Mac")) return "macos";
    if (ua.includes("Linux")) return "linux";
  }
  // 榛樿杩斿洖 Windows
  return "windows";
}

/** Windows: 浣跨敤 PowerShell Get-Clipboard */
async function readFromWindows(): Promise<string | null> {
  try {
    // PowerShell 鑴氭湰锛氳鍙栧壀璐存澘鍥剧墖骞惰浆涓?Base64
    const script = `
      Add-Type -AssemblyName System.Windows.Forms
      Add-Type -AssemblyName System.Drawing
      $img = [System.Windows.Forms.Clipboard]::GetImage()
      if ($img) {
        $ms = New-Object System.IO.MemoryStream
        $img.Save($ms, [System.Drawing.Imaging.ImageFormat]::Png)
        [Convert]::ToBase64String($ms.ToArray())
        $ms.Close()
        $img.Dispose()
      }
    `;

    const cmd = `powershell -NoProfile -Command "${script.replace(/"/g, '\\"')}"`;
    const result = await execCommand(cmd);
    if (result && result.trim()) {
      return result.trim();
    }
    return null;
  } catch (e) {
    handleClientError(e, {
      module: "services:clipboard",
      action: "readFromWindows",
    });
    return null;
  }
}

/** macOS: 浣跨敤 osascript 璇诲彇鍓创鏉?PNG 鏁版嵁 */
async function readFromMacOS(): Promise<string | null> {
  try {
    // 鏂规硶 1: 鐩存帴鑾峰彇 PNG 鏍煎紡鐨勫壀璐存澘鏁版嵁
    const script = `
      set pngData to (the clipboard as 芦class PNGf禄)
      if pngData is not missing value then
        return pngData
      end if
    `;
    const result = await execCommand(
      `osascript -e '${script.replace(/'/g, "\\'")}'`,
    );
    if (result && result.trim() && !result.includes("missing value")) {
      return result.trim();
    }

    // 鏂规硶 2: 浣跨敤 pngpaste (濡傚凡瀹夎)
    try {
      const pngResult = await execCommand(
        "pngpaste -b /dev/stdout 2>/dev/null | base64",
      );
      if (pngResult && pngResult.trim()) {
        return pngResult.trim();
      }
    } catch (e) {
      handleClientError(e, {
        module: "services:clipboard",
        action: "readFromMacOS-pngpaste",
      });
      // pngpaste 涓嶅彲鐢紝蹇界暐
    }

    return null;
  } catch (e) {
    handleClientError(e, {
      module: "services:clipboard",
      action: "readFromMacOS",
    });
    return null;
  }
}

/** Linux: xclip (X11) 鎴?wl-paste (Wayland) */
async function readFromLinux(): Promise<string | null> {
  try {
    // 灏濊瘯 Wayland
    const waylandResult = await execCommand(
      "wl-paste --type image/png 2>/dev/null | base64 -w0",
    );
    if (waylandResult && waylandResult.trim()) {
      return waylandResult.trim();
    }
  } catch (e) {
    handleClientError(e, {
      module: "services:clipboard",
      action: "readFromLinux-wayland",
    });
    // Wayland 涓嶅彲鐢╘n  }

  try {
    // 灏濊瘯 X11
    const xResult = await execCommand(
      "xclip -selection clipboard -t image/png -o 2>/dev/null | base64 -w0",
    );
    if (xResult && xResult.trim()) {
      return xResult.trim();
    }
  } catch (e) {
    handleClientError(e, {
      module: "services:clipboard",
      action: "readFromLinux-xclip",
    });
    // xclip 涓嶅彲鐢╘n  }

  return null;
}

/**
 * 鎵ц shell 鍛戒护骞惰繑鍥?stdout
 * 鍦?Tauri 鐜涓嬩娇鐢?Tauri API锛屽惁鍒欎娇鐢?child_process
 */
async function execCommand(cmd: string): Promise<string> {
  // 鍓嶇鐜锛氶€氳繃鍚庣 HTTP API 鎵ц鍛戒护
  // 鎴栦娇鐢?Tauri invoke
  try {
    // 浣跨敤 Tauri command invoke锛堝鏋滃湪 Tauri 鐜涓級
    if (typeof window !== "undefined" && (window as any).__TAURI__) {
      const { invoke } = (window as any).__TAURI__.core;
      return (await invoke("exec_command", { command: cmd })) as string;
    }
  } catch (e) {
    handleClientError(e, {
      module: "services:clipboard",
      action: "execCommand-tauri",
    });
    // 闈?Tauri 鐜
  }

  // 鍥為€€锛氶€氳繃 fetch 璋冪敤鍚庣 API
  try {
    const response = await fetch("/v1/system/exec", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ command: cmd }),
    });
    if (response.ok) {
      const data = (await response.json()) as { output: string };
      return data.output || "";
    }
  } catch (e) {
    handleClientError(e, {
      module: "services:clipboard",
      action: "execCommand-fetch",
    });
    // API 涓嶅彲鐢╘n  }

  return "";
}

