      throw new Error(String(res.error || "鍒涘缓浠诲姟澶辫触"));
    }
    return res.data as { taskId: string; status: string };
  },

  /**
   * 鏌ヨ鍗曚釜浠诲姟鐘舵€乗n   */
  async getVideoTask(taskId: string): Promise<{
    taskId: string;
