}

/**
 * 寤虹珛鍞ら啋璇?WebSocket 杩炴帴鍒板悗绔殑 /wake 绔偣
 * 杩炴帴鎴愬姛鍚庤嚜鍔ㄧ洃鍚?wakeword_detected 浜嬩欢
 * 鏂紑鏃惰嚜鍔ㄩ噸杩烇紙鎸囨暟閫€閬匡級
 */
export function connectWakeWordWebSocket(): Promise<void> {
  return new Promise((resolve, reject) => {
    // 濡傛灉宸叉湁杩炴帴锛屽厛鍏抽棴锛堜絾涓嶈涓轰富鍔ㄦ柇寮€锛岃閲嶈繛閫昏緫缁х画鐢熸晥锛塡n    disconnectWakeWordWebSocket(false);

    wakeDisconnectRequested = false;
    wakeReconnectAttempt = 0;

    const protocol = window.location.protocol === "https:" ? "wss:" : "ws:";
    // P1-2.16: 娉ㄥ叆 traceparent 鏌ヨ鍙傛暟
    const span = getOTelTracing().getActiveSpan();
    let tpParam = "";
    if (span) {
      const ctx = span.spanContext();
      if (ctx.traceId) {
        tpParam = `?traceparent=00-${ctx.traceId}-${ctx.spanId}-0${ctx.traceFlags}`;
      }
    }
    const url = `${protocol}//${window.location.host}/wake${tpParam}`;
    const ws = new WebSocket(url);

    ws.onopen = () => {
      wakeWs = ws;
      wakeReconnectAttempt = 0;
      resolve();
    };

    ws.onmessage = (event: MessageEvent) => {
      try {
        const data = JSON.parse(event.data);

        // 澶勭悊鍞ら啋璇嶆娴嬩簨浠禱n        if (data.type === "wakeword_detected") {
          onWakeWordDetectedCb?.({
            matchedTrigger: data.data?.matchedTrigger ?? null,
            remainingText: data.data?.remainingText ?? null,
          });
          return;
        }

        // 鏈嶅姟绔?ping 鈫?鍥炲 pong
        if (data.type === "ping") {
          if (ws.readyState === WebSocket.OPEN) {
            ws.send(JSON.stringify({ type: "pong", timestamp: Date.now() }));
          }
          return;
        }
      } catch {
        // 闈?JSON 娑堟伅蹇界暐
      }
    };

    ws.onclose = () => {
      wakeWs = null;

      if (wakeDisconnectRequested) {
        return;
      }

      // 鑷姩閲嶈繛锛堟寚鏁伴€€閬匡級
      const delay = Math.min(
        WAKE_RECONNECT_BASE_MS * Math.pow(2, wakeReconnectAttempt),
        WAKE_RECONNECT_MAX_MS,
      );
      wakeReconnectAttempt++;

      wakeReconnectTimer = setTimeout(() => {
        if (!wakeDisconnectRequested) {
          connectWakeWordWebSocket().catch(() => {
            // 閲嶈繛澶辫触鐢?onclose 鍐嶆瑙﹀彂
          });
        }
      }, delay);
    };

    ws.onerror = () => {
      // onerror 鍚庝細鏈?onclose锛岀敱 onclose 澶勭悊閲嶈繛
      reject(new Error("鍞ら啋 WS 杩炴帴澶辫触"));
    };
  });
}

/**
 * 鏂紑鍞ら啋璇?WebSocket 杩炴帴
 * @param requested 鏄惁涓轰富鍔ㄦ柇寮€锛堜富鍔ㄦ柇寮€涓嶈Е鍙戦噸杩烇級
 */
export function disconnectWakeWordWebSocket(requested: boolean = true): void {
  if (requested) {
    wakeDisconnectRequested = true;
  }

  if (wakeReconnectTimer) {
    clearTimeout(wakeReconnectTimer);
    wakeReconnectTimer = null;
  }

  if (wakeWs) {
    wakeWs.onclose = null;
    wakeWs.close(1000, "normal closure");
    wakeWs = null;
  }
}

/**
 * 娉ㄥ唽鐘舵€佸彉鏇村洖璋僜n * 褰撳悗绔?VoiceSession 鐘舵€佸彉鏇存椂閫氳繃 WebSocket 鎺ㄩ€侊紝姝ゅ洖璋冭瑙﹀彂
 */
export function onVoiceStateChange(
  cb: (state: string, previous: string) => void,
): void {
  onStateChangeCb = cb;
}

/**
 * 娉ㄥ唽杩炴帴鏂紑鍥炶皟
 * 蹇冭烦瓒呮椂鎴?WebSocket 鏂紑鏃惰Е鍙慭n */
export function onVoiceDisconnect(cb: () => void): void {
  onDisconnectCb = cb;
}

/**
 * 寤虹珛鍓嶇 WebSocket 杩炴帴鍒板悗绔殑 /voice 绔偣
 * 杩炴帴鎴愬姛鍚庤嚜鍔ㄥ惎鍔ㄥ績璺冲畾鏃跺櫒
 */
export function connectVoiceWebSocket(): Promise<void> {
  return new Promise((resolve, reject) => {
    // 濡傛灉宸叉湁杩炴帴锛屽厛鍏抽棴
    disconnectVoiceWebSocket();

    const protocol = window.location.protocol === "https:" ? "wss:" : "ws:";
    // P1-2.16: 娉ㄥ叆 traceparent 鏌ヨ鍙傛暟锛屽疄鐜拌法杩涚▼ TraceContext 浼犻€抃n    const span = getOTelTracing().getActiveSpan();
    let tpParam = "";
    if (span) {
      const ctx = span.spanContext();
      if (ctx.traceId) {
        tpParam = `?traceparent=00-${ctx.traceId}-${ctx.spanId}-0${ctx.traceFlags}`;
      }
    }
    const url = `${protocol}//${window.location.host}/voice${tpParam}`;
    const ws = new WebSocket(url);

    ws.onopen = () => {
      voiceWs = ws;
      missedPongs = 0;

      // 鍚姩蹇冭烦锛氭瘡 30s 鍙戦€?ping
      heartbeatTimer = setInterval(() => {
        if (ws.readyState !== WebSocket.OPEN) return;

        ws.send(JSON.stringify({ type: "ping", timestamp: Date.now() }));
        missedPongs++;

        // 杩炵画涓ゆ鏈敹鍒?pong 鈫?杩炴帴宸插け鏁圽n        if (missedPongs >= MAX_MISSED_PONGS) {
          onDisconnectCb?.();
          disconnectVoiceWebSocket();
        }
      }, HEARTBEAT_INTERVAL_MS);

      resolve();
    };

    ws.onmessage = (event: MessageEvent) => {
      try {
        const data = JSON.parse(event.data);

        // P2-2: 蹇冭烦鍝嶅簲 鈥?閲嶇疆璁℃暟鍣╘n        if (data.type === "pong") {
          missedPongs = 0;
          return;
        }

        // P2-2: 鐘舵€佸彉鏇翠簨浠?鈥?鍒嗗彂鍒版敞鍐岀殑鍥炶皟
        if (data.type === "session.state_change") {
          onStateChangeCb?.(data.state, data.previous);
          return;
        }
      } catch {
        // 闈?JSON 娑堟伅锛堝浜岃繘鍒跺抚锛夊拷鐣n      }
    };

    ws.onclose = () => {
      disconnectVoiceWebSocket();
      onDisconnectCb?.();
    };

    ws.onerror = () => {
      reject(new Error("WebSocket 杩炴帴澶辫触"));
    };
  });
}

/**
 * 鏂紑 WebSocket 杩炴帴骞舵竻鐞嗗績璺冲畾鏃跺櫒
 */
export function disconnectVoiceWebSocket(): void {
  if (heartbeatTimer) {
    clearInterval(heartbeatTimer);
    heartbeatTimer = null;
  }

  if (voiceWs) {
    voiceWs.onclose = null; // 闃叉閫掑綊瑙﹀彂
    voiceWs.close(1000, "normal closure");
    voiceWs = null;
  }

  missedPongs = 0;
}

