      | "verifying"
      | "presenting"
      | null;
    progress: number;
    description: string;
  } | null;
  error: string | null;
  replyMessage: Message | null;
  /** 寰呰缃殑鍥炲寮曠敤 ID锛坰treamMessage 涓垱寤虹敤鎴锋秷鎭椂璇诲彇锛?*/
  pendingReplyToId: string | null;
  /** 姝ｅ湪缂栬緫鐨勬秷鎭紙鐢ㄦ埛娑堟伅锛?*/
  editTarget: Message | null;
  /** 涓鎺у埗鍣細鐢ㄤ簬鍙栨秷姝ｅ湪杩涜鐨勬祦寮忚姹?*/
  abortController: AbortController | null;
  /** 娑堟伅闃熷垪锛氭祦寮忚緭鍑轰腑鐢ㄦ埛鍙戦€佺殑鏂版秷鎭紙鏀惧紑杈撳叆闄愬埗鍚庝娇鐢級 */
  messageQueue: Array<{ content: string; sessionId?: string }>;

  addMessage: (message: Message) => void;
  sendMessage: (content: string, sessionId?: string) => Promise<void>;
  /** 灏嗘秷鎭姞鍏ラ槦鍒楋紙娴佸紡杈撳嚭涓笉闃诲杈撳叆锛?*/
  enqueueMessage: (content: string, sessionId?: string) => void;
  /** 娑堣垂闃熷垪涓殑涓嬩竴鏉℃秷鎭?*/
  dequeueAndSend: (sessionId?: string) => Promise<void>;
  streamMessage: (
    content: string,
    sessionId?: string,
    workMode?: "plan" | "do",
    attachedImages?: AttachedImage[],
  ) => Promise<void>;
  /** 閲嶆柊鐢熸垚涓婁竴鏉?AI 娑堟伅 */
  regenerateMessage: (sessionId?: string) => Promise<void>;
  /** 鍦ㄥ嚭閿欏悗閲嶈瘯锛堜紶鍏ュ嚭閿欑殑 assistant 娑堟伅 ID锛屽唴閮ㄦ壘鍒板墠缃敤鎴锋秷鎭噸鏂板彂閫侊級 */
  retryFromError: (assistantMsgId: string, sessionId?: string) => Promise<void>;
  clearMessages: () => void;
  setMessages: (messages: Message[]) => void;
  setReplyMessage: (message: Message | null) => void;
  /** 璁剧疆寰呯紪杈戞秷鎭?*/
  setEditTarget: (message: Message | null) => void;
  /** 鍙栨秷褰撳墠娴佸紡璇锋眰 */
  stopMessage: () => void;
  flushPendingSaves: () => Promise<void>;
  /** 鍒犻櫎鍗曟潯娑堟伅锛堜箰瑙傛洿鏂帮級 */
  deleteMessage: (messageId: string) => Promise<void>;
  /** 鍥為€€鍒版寚瀹氭秷鎭箣鍓?*/
  rollbackToMessage: (messageId: string) => Promise<{
    messages: Array<Record<string, unknown>>;
    remainingRollbacks: number;
    undoResults?: Array<{ roundId: number; success: boolean; error?: string }>;
  }>;
  /** 鍥為€€鍓嶅揩鐓э紙鐢ㄤ簬鎾ら攢鍥為€€锛?*/
  rollbackSnapshot: Message[] | null;
  /** 鎾ら攢鏈€杩戜竴娆″洖閫€锛堟仮澶嶅揩鐓т腑鐨勬秷鎭級 */
  restoreRollback: () => void;
}

/**
 * 鍒涘缓 Message Slice锛圸ustand StateCreator 妯″紡锛塡n */
export const createMessageSlice: StateCreator<
  MessageSlice & FileSlice,
  [],
  [],
  MessageSlice
> = (set, get) => ({
  messages: [],
  isSending: false,
  isInputBlocked: false,
  isStreaming: false,
  streamingStatus: "",
  executionPhase: null,
  error: null,
  replyMessage: null,
  pendingReplyToId: null,
  editTarget: null,
  abortController: null,
  messageQueue: [],
  rollbackSnapshot: null,
  hasPendingQuestion: false,

  addMessage: (message: Message) => {
    set({ messages: [...get().messages, message] });
  },

  sendMessage: async (content: string, sessionId?: string) => {
    // 娑堟伅鎺掗槦妯″紡锛氭祦寮忚緭鍑轰腑涓嶉樆濉烇紝鍔犲叆闃熷垪
    const messageQueueEnabled =
      useFeatureFlagStore.getState().flags.message_queue;
    if (messageQueueEnabled && get().isStreaming) {
      get().enqueueMessage(content, sessionId);
      return;
    }

    // 鏍囪褰撳墠 session 缂撳瓨涓?stale锛堝彂閫佹柊娑堟伅鍚庣紦瀛樺皢杩囨湡锛塡n    const state = get();
    const currentSid = sessionId ?? state.messages[0]?.session_id ?? "";
    if (currentSid) staleSessionCache(currentSid);

    set({ isSending: true, isInputBlocked: !messageQueueEnabled, error: null });

    const pendingReplyId = get().pendingReplyToId;
    const userMessage: Message = {
      id: crypto.randomUUID(),
      role: "user",
      content,
      timestamp: Date.now(),
      session_id: sessionId || "default",
      replyToId: pendingReplyId || undefined,
    };
    // 浣跨敤鍚庢竻闄n    if (pendingReplyId) {
      set({ pendingReplyToId: null });
    }

    set({ messages: [...get().messages, userMessage] });

    try {
      const response = await chatService.sendMessage(content, sessionId);

      // 妫€娴嬮潪娴佸紡璺緞鐨勫緟澶勭悊浜や簰
      if (
        (response as Message & { pendingInteraction?: unknown })
          .pendingInteraction
      ) {
        const pi = (
          response as Message & {
            pendingInteraction: import("../../services/chatService").QuestionData;
          }
        ).pendingInteraction;
        const builder = new ChronologicalBlockBuilder();
        builder.addQuestion(pi);
        const blocks = builder.getBlocks();
        const questionMessage: Message = {
          id: response.id,
          role: "assistant",
          content: "",
          timestamp: Date.now(),
          session_id: sessionId || "default",
          blocks,
        };
        set({
          messages: [...get().messages, questionMessage],
          isSending: false,
          isInputBlocked: false,
        });
        return;
      }

      const newMessages = [...get().messages, response];

      // 鍏堥噸缃?isSending/isInputBlocked锛孶I 绔嬪埢鍝嶅簲
      set({ messages: newMessages, isSending: false, isInputBlocked: false });

      // 闈炴祦寮忚矾寰勪篃鎸佷箙鍖?blocks锛岄伩鍏嶄笅娆″叏閲忓姞杞芥椂閲嶅缓涓㈠け缁撴瀯
      const assistantMsg = response as Message;
      if (assistantMsg.role === "assistant" && assistantMsg.blocks?.length) {
        chatService
          .updateMessageBlocks(
            sessionId || "default",
            assistantMsg.id,
            assistantMsg.blocks as unknown as Array<Record<string, unknown>>,
          )
          .catch((err) =>
            handleClientError(
              err,
              {
                module: "stores:chat:message",
                action: "sendMessage:saveBlocks",
              },
              "warn",
            ),
          );
      }

      // 鍐嶆墽琛岃嚜鍔ㄩ噸鍛藉悕锛堜笉闃诲 UI 鐘舵€侊級
      if (await shouldAutoRename(sessionId)) {
        doAutoRename(sessionId!, content, (response as Message).content).catch(
          (e) =>
            handleClientError(
              e,
              {
                module: "stores:chat:message",
                action: "sendMessage:autoRename",
              },
              "warn",
            ),
        );
      }
    } catch (error) {
      handleClientError(
        error,
        { module: "stores:chat:message", action: "sendMessage" },
        "warn",
      );
      set({ error: String(error), isSending: false, isInputBlocked: false });
    }
  },

  /**
   * 灏嗘秷鎭姞鍏ラ槦鍒楋紝寰呭綋鍓嶆祦寮忎换鍔″畬鎴愬悗鑷姩鍙戦€乗n   * 浠呭湪 message_queue Feature Flag 寮€鍚椂鐢?sendMessage 鑷姩璋冪敤
   */
  enqueueMessage: (content: string, sessionId?: string) => {
    const currentQueue = get().messageQueue;
    set({
      messageQueue: [...currentQueue, { content, sessionId }],
      // 鎺掗槦鍚庝粛淇濇寔 isSending 鐘舵€侊紝涓嶉樆濉炶緭鍏n    });
  },

  /**
   * 娑堣垂闃熷垪涓殑涓嬩竴鏉℃秷鎭紝鑷姩鍙戦€乗n   * 鍦ㄦ祦寮忚緭鍑虹粨鏉熷悗鑷姩璋冪敤
   */
  dequeueAndSend: async (sessionId?: string) => {
    const queue = get().messageQueue;
    if (queue.length === 0) return;

    const next = queue[0];
    const remaining = queue.slice(1);
    set({ messageQueue: remaining });

    // 閫掑綊璋冪敤 sendMessage锛屽鏋滈槦鍒椾腑杩樻湁鏇村娑堟伅锛宻endMessage 浼氳嚜鍔ㄧ户缁帓闃焅n    await get().sendMessage(next.content, next.sessionId || sessionId);
  },

  streamMessage: async (
    content: string,
    sessionId?: string,
    workMode?: "plan" | "do",
    attachedImages?: AttachedImage[],
  ) => {
    // J1: 鍙栨秷涓婁竴涓湭瀹屾垚鐨勬祦寮忚姹俓n    const prevController = get().abortController;
    if (prevController) {
      prevController.abort();
    }

    const abortController = new AbortController();

    const messageQueueEnabled =
      useFeatureFlagStore.getState().flags.message_queue;

    set({
      isSending: true,
      isInputBlocked: !messageQueueEnabled,
      isStreaming: true,
      error: null,
      abortController,
    });

    // 缂栬緫娑堟伅锛氬鏋滃瓨鍦?editTarget锛屾埅鏂叾鍚庣殑娑堟伅
    const editTarget = get().editTarget;
    if (editTarget) {
      const editIndex = get().messages.findIndex((m) => m.id === editTarget.id);
      if (editIndex >= 0) {
        // 鎴柇 editTarget 鍙婂叾涔嬪悗鐨勬墍鏈夋秷鎭痋n        const truncated = get().messages.slice(0, editIndex);
        set({ messages: truncated, editTarget: null });
      } else {
        set({ editTarget: null });
      }
    }

    // 娑堟伅鎺掗槦锛氭祦缁撴潫鍚庤嚜鍔ㄦ秷璐归槦鍒梊n    const tryDequeue = () => {
      if (messageQueueEnabled && get().messageQueue.length > 0) {
        get()
          .dequeueAndSend(sessionId)
          .catch((e) =>
            handleClientError(
              e,
              {
                module: "stores:chat:message",
                action: "streamMessage:dequeue",
              },
              "warn",
            ),
          );
      }
    };

    const userMessage: Message = {
      id: crypto.randomUUID(),
      role: "user",
      content,
      timestamp: Date.now(),
      session_id: sessionId || "default",
      attachedImages:
        attachedImages && attachedImages.length > 0
          ? attachedImages
          : undefined,
    };

    const assistantId = crypto.randomUUID();
    const assistantMessage: Message = {
      id: assistantId,
      role: "assistant",
      content: "",
      timestamp: Date.now(),
      session_id: sessionId || "default",
      blocks: [],
    };

    set({ messages: [...get().messages, userMessage, assistantMessage] });

    // J3: 灏嗘ā鍧楃骇绔炴€佸彉閲忔敼涓洪棴鍖呭唴鐨勫眬閮ㄥ彉閲廫n    let saveBlocksTimer: ReturnType<typeof setTimeout> | null = null;
    let pendingSaveSessionId: string | null = null;
    let pendingSaveMessageId: string | null = null;
    let pendingSaveBlocks: MessageBlock[] | null = null;

    const flushSaveBlocksLocal = async (): Promise<void> => {
      if (pendingSaveSessionId && pendingSaveMessageId && pendingSaveBlocks) {
        const sid = pendingSaveSessionId;
        const mid = pendingSaveMessageId;
        const blk = pendingSaveBlocks;
        pendingSaveSessionId = null;
        pendingSaveMessageId = null;
        pendingSaveBlocks = null;
        try {
          await chatService.updateMessageBlocks(
            sid,
            mid,
            blk as unknown as Array<Record<string, unknown>>,
          );
        } catch (err) {
          handleClientError(
            err,
            {
              module: "stores:chat:message",
              action: "streamMessage:saveBlocks",
            },
            "warn",
          );
        }
      }
    };

    const debouncedSaveBlocksLocal = (
      sid: string,
      mid: string,
      blk: MessageBlock[],
      immediate: boolean = false,
    ): void => {
      pendingSaveSessionId = sid;
      pendingSaveMessageId = mid;
      pendingSaveBlocks = blk;
      if (immediate) {
        // 鍏抽敭鑺傜偣鍗虫椂钀界洏锛歵ool_call 瀹屾垚 / finish_reason 鍒拌揪 / 鎴柇
        // 纭繚鍒囪蛋鏃朵笉涓㈠け锛岀鍚圽

鍘熷垯锛堟柟妗?C锛塡n        if (saveBlocksTimer) clearTimeout(saveBlocksTimer);
        saveBlocksTimer = null;
        flushSaveBlocksLocal();
        return;
      }
      if (saveBlocksTimer) {
        clearTimeout(saveBlocksTimer);
      }
      saveBlocksTimer = setTimeout(() => {
        flushSaveBlocksLocal();
      }, 200); // 200ms 闃叉姈锛屾瘮 800ms 鏇村強鏃禱n    };

    // J4: 鎵归噺 set 鏇存柊鈥斺€斾娇鐢ㄧ増鏈彿鏈哄埗锛岄槻姝㈣繃鏈?rAF 瑕嗙洊鏈€缁堢姸鎬乗n    let batchVersion = 0;
    let batchPending = false;
    let latestMessages: Message[] | null = null;

    const flushSet = (currentVersion: number): void => {
      // 鐗堟湰鍙锋鏌ワ細杩囨湡鐗堟湰鐩存帴涓㈠純锛堟祦缁撴潫鍚庢棫 rAF 鍥炶皟涓嶈鐩栨渶缁堢姸鎬侊級
      if (currentVersion < batchVersion) {
        logger.debug("flushSet: 鐗堟湰杩囨湡涓㈠純", {
          currentVersion,
          batchVersion,
        });
        batchPending = false;
        return;
      }

      if (latestMessages) {
        const questionCount = latestMessages.reduce((cnt, m) => {
          return (
            cnt + (m.blocks?.filter((b) => b.type === "question").length ?? 0)
          );
        }, 0);
        logger.debug("flushSet: 鏇存柊 store", {
          version: currentVersion,
          batchVersion,
          msgCount: latestMessages.length,
          questionBlocks: questionCount,
        });
        set({ messages: latestMessages });
        latestMessages = null;
      }
      batchPending = false;
    };

    try {
      const generator = chatService.streamMessage(
        content,
        sessionId,
        abortController.signal,
        { workMode, images: attachedImages },
      );
      const blockBuilder = new ChronologicalBlockBuilder();
      const extractor = createThinkExtractor();

      for await (const rawChunk of generator) {
        // 妫€鏌ユ槸鍚﹀凡琚腑姝n        if (abortController.signal.aborted) break;

        const chunks = Array.from(extractor.extract(rawChunk));
        for (const chunk of chunks) {
          await processChunk(chunk);
        }
      }

      // 澶勭悊鏈棴鍚堢殑 think 鏍囩
      if (!abortController.signal.aborted) {
        for (const chunk of extractor.flush()) {
          await processChunk(chunk);
        }
      }

      async function processChunk(
        chunk: import("../../services/chatService").StreamChunk,
      ) {
        const current = get().messages;
        const msgIdx = current.findIndex((m) => m.id === assistantId);

        if (msgIdx === -1) {
          logger.warn(
            "processChunk: 鏈壘鍒板搴旂殑 assistant 娑堟伅锛坅ssistantId=%s锛夛紝璺宠繃 chunk",
            assistantId,
          );
          return;
        }

        const msg = current[msgIdx];
        let updatedMsg: Message;

        if (chunk.type === "thinking") {
          blockBuilder.addThinking(chunk.content, true);
          updatedMsg = { ...msg, blocks: blockBuilder.getBlocks() };
        } else if (chunk.type === "text") {
          blockBuilder.freezeThinking();
          blockBuilder.addText(chunk.content, true);
          updatedMsg = {
            ...msg,
            content: msg.content + stripStructuralTags(chunk.content),
            blocks: blockBuilder.getBlocks(),
          };
        } else if (chunk.type === "status") {
          blockBuilder.addStatus(chunk.content);
          set({ streamingStatus: chunk.content });
          updatedMsg = { ...msg, blocks: blockBuilder.getBlocks() };
        } else if (chunk.type === "context_state") {
          // 涓婁笅鏂囩姸鎬佷簨浠讹紙鍘嬬缉/鍙洖绛夛級锛屼娇鐢?status 鍧楁覆鏌揬n          blockBuilder.addStatus(chunk.content);
          set({ streamingStatus: chunk.content });
          updatedMsg = { ...msg, blocks: blockBuilder.getBlocks() };
        } else if (chunk.type === "tool_completed") {
          // 宸ュ叿瀹屾垚浜嬩欢锛氭惡甯︾粨鏋勫寲 result data 鏇存柊瀵瑰簲 toolCall.result
          const tcId = chunk.tool_call_id;
          const resultData = chunk.result_data;
          logger.debug("tool_completed chunk", {
            tcId,
            hasResultData: !!resultData,
            resultDataKeys: resultData ? Object.keys(resultData) : "N/A",
          });
          if (tcId && resultData) {
            blockBuilder.updateToolCallResult(tcId, resultData);
            logger.debug("after updateToolCallResult", {
              blocks: blockBuilder
                .getBlocks()
                .filter((b) => b.type === "tool_call")
                .map((b) => ({
                  id: b.toolCall?.id,
                  name: b.toolCall?.name,
                  hasResult: !!b.toolCall?.result,
                })),
            });
          }
          updatedMsg = { ...msg, blocks: blockBuilder.getBlocks() };
        } else if (chunk.type === "execution_phase" && chunk.executionPhase) {
          // 鎵ц闃舵鎺ㄩ€侊細鏇存柊 executionPhase 鐘舵€?+ 鐢熸垚杩涘害鍧梊n          const ep = chunk.executionPhase;
          const progressData: import("../../types").ProgressData = {
            phase:
              (ep.phase as import("../../types").ProgressData["phase"]) ||
              "analyzing",
            progress: ep.progress || 0,
            description: ep.description || "",
            steps:
              (ep.steps as import("../../types").ProgressData["steps"]) || [],
            currentStep: ep.currentStep || "",
          };
          set({
            executionPhase: {
              phase: progressData.phase,
              progress: progressData.progress,
              description: progressData.description,
            },
          });
          blockBuilder.addProgress(progressData);
          updatedMsg = { ...msg, blocks: blockBuilder.getBlocks() };
        } else if (chunk.type === "error") {
          // 灏嗛敊璇俊鎭樉绀哄湪鑱婂ぉ鐣岄潰涓璡n          blockBuilder.addStatus(`鉂?${chunk.content}`);
          updatedMsg = {
            ...msg,
            content: msg.content + stripStructuralTags(chunk.content),
            blocks: blockBuilder.getBlocks(),
          };
          set({ error: chunk.content });
        } else if (chunk.type === "tool_call" && chunk.toolCall) {
          // 瀹炴椂杞崲锛歵odo_write 鐨?tool_call 鐩存帴杞?todo block锛屼笉绛夋祦缁撴潫
          let skipDefault = false;
          if (chunk.toolCall.name === "todo_write") {
            const args = chunk.toolCall.arguments as
              Record<string, unknown> | undefined;
            if (args?.action === "write" && args?.todos) {
              const todos =
                (args.todos as Array<Record<string, unknown>>) || [];
              const tasks = todos.map((t, idx) => ({
                id: String(t.id || idx + 1),
                name: String(t.name || t.content || `姝ラ ${idx + 1}`),
                status:
                  (t.status as import("../../types").TaskCardTask["status"]) ||
                  "pending",
                dependsOn: (t.dependsOn as string[]) || [],
              }));
              const title = String(
                args?.title ||
                  (typeof args?.description === "string"
                    ? args.description
                    : "") ||
                  `浠诲姟 (${todos.length} 姝?`,
              );
              blockBuilder.addTodo({ title, tasks, status: "planning" });
              skipDefault = true;
            } else if (args?.action === "update") {
              // 瀹炴椂鏇存柊鍗曚釜浠诲姟鐘舵€侊細浠?tool_call 鍙傛暟涓彁鍙栧彉鏇村苟搴旂敤鍒?todo block
              const taskId = String(args.todoId ?? args.id ?? "");
              if (taskId) {
                const updates: Partial<{
                  status: import("../../types").TaskCardTask["status"];
                  result: string;
                  durationMs: number;
                }> = {};
                if (args.status)
                  updates.status =
                    args.status as import("../../types").TaskCardTask["status"];
                if (args.result) updates.result = args.result as string;
                if (args.durationMs)
                  updates.durationMs = args.durationMs as number;
                blockBuilder.updateTodoTask(taskId, updates);
              }
              skipDefault = true;
            }
          }
          // ask_user_question 鐨?tool_call锛氳烦杩囬粯璁?tool_call 娓叉煋鍧楋紝
          // 绋嶅悗灏嗙敱 question 绫诲瀷 chunk 娓叉煋 QuestionBlock
          if (chunk.toolCall.name === "ask_user_question") {
            skipDefault = true;
          }
          if (!skipDefault) {
            blockBuilder.addToolCall(chunk.toolCall);
          }

          // 鏂囦欢璺緞鏀堕泦宸茬Щ鑷虫祦缁撴潫鍚庣殑 addFilePathsFromBlocks 缁熶竴澶勭悊
          // 閬垮厤娴佸紡浼犺緭涓悓姝?setState 瀵艰嚧鏃犻檺閲嶆覆鏌揬n
          updatedMsg = { ...msg, blocks: blockBuilder.getBlocks() };

