              toolResultsByCallId.has(block.toolCall.id)
            ) {
              const fullResult = toolResultsByCallId.get(block.toolCall.id)!;
              hasMergedResult = true;
              // 鍙敞鍏ユ埅鏂憳瑕佸埌 block锛屽叏閲忕粨鏋滈€氳繃 getToolResultFull() 鎸夐渶鑾峰彇
              block.toolCall = {
                ...block.toolCall,
                result: truncateResult(fullResult),
                _hasFullResult:
                  fullResult.length > MAX_INLINE_RESULT_LENGTH || undefined,
              };
            }
            return block;
          });

          if (hasMergedResult) {
            return { ...msg, blocks: mergedBlocks };
          }

          // 鏃犲尮閰嶅伐鍏风粨鏋滄椂锛屾墽琛?groupId 杩佺Щ锛堟棫 blocks 鍏煎锛塡n          const oldBlocksHaveGroupId = msg.blocks.some((b) => b.groupId);
          if (oldBlocksHaveGroupId) {
            return {
              ...msg,
              blocks: msg.blocks.map((b) => ({ ...b, isStreaming: false })),
            };
          }
          const lastToolCallId = findLastToolCallId(msg);
          const enhancedBlocks = msg.blocks.map((b) => {
            if (b.groupId) return { ...b, isStreaming: false };
            const id =
              b.toolCallId ||
              b.toolCall?.id ||
              lastToolCallId ||
              generateGroupId();
            return { ...b, isStreaming: false, groupId: "migrate_" + id }; // "migrate_" 鍓嶇紑鏍囪鍘嗗彶鏁版嵁锛屼笌娴佸紡 "grp_" 鍖哄垎
          });
          return { ...msg, blocks: enhancedBlocks };
        }

        const newBlocks = rebuildBlocksFromContent(msg);
        return { ...msg, blocks: newBlocks, tool_calls: undefined };
      });
      const outBlocks = enhancedMessages.reduce(
        (c, m) => c + (Array.isArray(m.blocks) ? m.blocks.length : 0),
        0,
      );
      console.info("[Diag:setMsg] Phase3 閲嶅缓blocks+鍚堝苟宸ュ叿缁撴灉", {
        ms: (performance.now() - tP3).toFixed(1),
        outputBlocks: outBlocks,
      });

      // Phase 4: 浠庡巻鍙叉秷鎭腑鐨?tool_call 鍧椾腑鎻愬彇鏂囦欢璺緞锛堜粎鍚屾鏀堕泦锛屼笉鍋氬紓姝ヨ矾寰勮В鏋愶級
      const tP4 = performance.now();
      const sessionFilesList: FilePreview[] = [];
      const addedPaths = new Set<string>();

      for (const msg of enhancedMessages) {
        if (msg.role === "assistant" && msg.blocks) {
          addFilePathsFromBlocks(
            msg.blocks,
            (file) => {
              if (!addedPaths.has(file.path)) {
                addedPaths.add(file.path);
                sessionFilesList.push(file);
              }
            },
            () => get().sessionFiles,
            // 涓嶈Е鍙戝紓姝?setState锛氭枃浠惰矾寰勮В鏋愮暀鍒伴瑙堟椂鎸夐渶鎵ц
            () => {},
          );
        }
      }
      console.info("[Diag:setMsg] Phase4 鎻愬彇鏂囦欢璺緞", {
        ms: (performance.now() - tP4).toFixed(1),
        filesFound: sessionFilesList.length,
      });

      // 妫€娴嬫槸鍚︽湁寰呯敤鎴峰洖绛旂殑 question 鍧梊n      const hasQuestion = enhancedMessages.some((m) =>
        m.blocks?.some((b) => b.type === "question"),
      );

      if (sessionFilesList.length > 0) {
        const currentFiles = get().sessionFiles;
        const merged = [...currentFiles];
        for (const file of sessionFilesList) {
          if (!merged.some((f) => f.path === file.path)) {
            merged.push(file);
          }
        }
        set({
          messages: enhancedMessages,
          sessionFiles: merged,
          hasPendingQuestion: hasQuestion,
          streamingStatus: "",
          executionPhase: null,
        });
      } else {
        set({
          messages: enhancedMessages,
          hasPendingQuestion: hasQuestion,
          streamingStatus: "",
          executionPhase: null,
        });
      }

      // 閲婃斁浼氳瘽鍒囨崲閿佸悗鍒锋柊鏆傚瓨鐨勬祦寮?chunk
      _sessionSwitchLock = false;
      if (_pendingSwitchChunks.length > 0) {
        // 鏆傚瓨 chunk 鐨?sessionId 鍙兘涓庡綋鍓嶄細璇濅笉涓€鑷达紙璺ㄤ細璇濆垏鎹級锛屽彧鏍囪寰呬繚瀛榎n        const lastChunk = _pendingSwitchChunks[_pendingSwitchChunks.length - 1];
        setPendingSave(
          lastChunk.sessionId,
          lastChunk.assistantId,
          lastChunk.blocks,
        );
        setHasPendingSave(true);
        _pendingSwitchChunks = [];
      }
      console.info("[Diag:setMsg] 鉁?澶勭悊瀹屾垚", {
        totalMs: (performance.now() - t0).toFixed(1),
      });
    } catch (e) {
      console.error("[Diag:setMsg] 鉂?澶勭悊澶辫触", {
        error: String(e),
        totalMs: (performance.now() - t0).toFixed(1),
      });
      // 纭繚浼氳瘽鍒囨崲閿佷竴瀹氶噴鏀撅紝闃叉閿佹硠婕忓鑷村悗缁祦寮忚緭鍑烘案涔呴樆濉瀄n      _sessionSwitchLock = false;
      _pendingSwitchChunks = [];
      handleClientError(
        e,
        { module: "stores:chat:message", action: "setMessages" },
        "error",
      );
      // 璁剧疆绌烘秷鎭垪琛ㄤ綔涓洪檷绾э紝閬垮厤鐣岄潰鍗″湪鏃ф暟鎹笂
      set({ messages: [], streamingStatus: "", executionPhase: null });
    }
  },
});

