/**
 * Cron Store 鈥?鐙珛 Zustand Store
 *
 * 绠＄悊瀹氭椂浠诲姟鐨?CRUD銆佽皟搴﹀櫒鐘舵€佹煡璇㈢瓑鎿嶄綔銆俓n */
import { create } from "zustand";
import { cronService } from "../services/cronService";
import { handleClientError } from "@/utils/handleError";
import type { CronTask, ScheduleMode } from "../types";

export type { CronTask, ScheduleMode };

interface CronStore {
  tasks: CronTask[];
  isLoading: boolean;
  error: string | null;
  saving: boolean;
  schedulerStatus: {
    running: boolean;
    lastTickAt?: number;
    activeJobs: number;
    totalJobs: number;
    uptimeMs: number;
  } | null;
  statusLoading: boolean;

  loadTasks: () => Promise<void>;
  loadStatus: () => Promise<void>;
  createTask: (task: {
    name: string;
    expression: string;
    prompt?: string;
    description?: string;
    enabled?: boolean;
    scheduleMode?: ScheduleMode;
    silent?: boolean;
    everyValue?: number;
    everyUnit?: string;
    atHour?: string;
    atMinute?: string;
    deliver?: string;
    deliverTo?: string;
  }) => Promise<void>;
  updateTask: (id: string, updates: Partial<CronTask>) => Promise<void>;
  deleteTask: (id: string) => Promise<void>;
  toggleTask: (id: string, enabled: boolean) => Promise<void>;
  runTaskNow: (id: string) => Promise<void>;
}

export const useCronStore = create<CronStore>()((set) => ({
  tasks: [],
  isLoading: false,
  error: null,
  saving: false,
  schedulerStatus: null,
  statusLoading: false,

  loadTasks: async () => {
    set({ isLoading: true, error: null });
    try {
      const tasks = await cronService.list();
      set({ tasks, isLoading: false });
    } catch (e) {
      handleClientError(
        e,
        { module: "stores:cronStore", action: "loadTasks" },
        "warn",
      );
      set({ error: String(e), isLoading: false });
    }
  },

  loadStatus: async () => {
    set({ statusLoading: true });
    try {
      const status = await cronService.getStatus();
      set({ schedulerStatus: status, statusLoading: false });
    } catch (e) {
      handleClientError(
        e,
        { module: "stores:cronStore", action: "loadStatus" },
        "warn",
      );
      set({ schedulerStatus: null, statusLoading: false });
    }
  },

  createTask: async (task) => {
    set({ saving: true });
    try {
      const created = await cronService.create(task as any);
      set((state) => ({ tasks: [...state.tasks, created] }));
    } catch (e) {
      handleClientError(
        e,
        { module: "stores:cronStore", action: "createTask" },
        "warn",
      );
      set({ error: String(e) });
    } finally {
      set({ saving: false });
    }
  },

  updateTask: async (id, updates) => {
    set({ saving: true });
    try {
      const updated = await cronService.update(id, updates);
      set((state) => ({
        tasks: state.tasks.map((t) => (t.id === id ? updated : t)),
      }));
    } catch (e) {
      handleClientError(
        e,
        { module: "stores:cronStore", action: "updateTask" },
        "warn",
      );
      set({ error: String(e) });
    } finally {
      set({ saving: false });
    }
  },

  deleteTask: async (id) => {
    set({ saving: true });
    try {
      await cronService.delete(id);
      set((state) => ({ tasks: state.tasks.filter((t) => t.id !== id) }));
    } catch (e) {
      handleClientError(
        e,
        { module: "stores:cronStore", action: "deleteTask" },
        "warn",
      );
      set({ error: String(e) });
    } finally {
      set({ saving: false });
    }
  },

  toggleTask: async (id, enabled) => {
    set({ saving: true });
    try {
      const updated = await cronService.toggle(id, enabled);
      set((state) => ({
        tasks: state.tasks.map((t) => (t.id === id ? updated : t)),
      }));
    } catch (e) {
      handleClientError(
        e,
        { module: "stores:cronStore", action: "toggleTask" },
        "warn",
      );
      set({ error: String(e) });
    } finally {
      set({ saving: false });
    }
  },

  runTaskNow: async (id) => {
    set({ saving: true });
    try {
      await cronService.runNow(id);
    } catch (e) {
      handleClientError(
        e,
        { module: "stores:cronStore", action: "runTaskNow" },
        "warn",
      );
      set({ error: String(e) });
    } finally {
      set({ saving: false });
    }
  },
}));

/**
 * Zustand 鏃ュ織涓棿浠禱n *
 * 鎷︽埅鎵€鏈?set() 璋冪敤锛岃嚜鍔ㄦ娴嬪叧閿姸鎬佸彉鏇村苟璁板綍缁撴瀯鍖栨棩蹇椼€俓n * 浠呰褰曞叧閿簨浠讹紙Worktree 鍒囨崲銆丼ession 鍒囨崲銆乄orkItems 鍙樻洿锛夛紝
 * 閬垮厤楂橀鏇存柊浜х敓鏃ュ織鍣煶銆俓n *
 * 浣跨敤鏂瑰紡锛歕n *   export const useRootStore = create<RootState>()(
 *     ...loggingMiddleware,
 *     subscribeWithSelector(persist(...))
 *   );
 */

import type { StateCreator } from "zustand";
import type { RootState } from "../root-store";
import { createLogger } from "@/utils/logger";

const storeLogger = createLogger("stores:root");

/**
 * 鏃ュ織涓棿浠?鈥?鍖呰 StateCreator锛屽湪 set 鍓嶅悗姣旇緝骞惰褰曞叧閿彉鏇淬€俓n */
export const loggingMiddleware =
  <T extends RootState>(
    config: StateCreator<T, [], []>,
  ): StateCreator<T, [], []> =>
  (set, get, api) => {
    return config(
      (partial, replace) => {
        const prev = get() as unknown as RootState;
        set(partial, replace as any);
        const next = get() as unknown as RootState;

        if (prev.currentWorktreeId !== next.currentWorktreeId) {
          storeLogger.info("Worktree 鍒囨崲", {
            from: prev.currentWorktreeId,
            to: next.currentWorktreeId,
            transition: next.transition?.status,
          });
        }

        if (prev.currentSessionId !== next.currentSessionId) {
          storeLogger.info("Session 鍒囨崲", {
            from: prev.currentSessionId,
            to: next.currentSessionId,
          });
        }

        const wtId = next.currentWorktreeId;
        if (wtId && wtId === prev.currentWorktreeId) {
          const nextWt = next.worktrees[wtId];
          const prevWt = prev.worktrees[wtId];
          if (
            nextWt &&
            prevWt &&
            nextWt.workItems?.length !== prevWt.workItems?.length
          ) {
            storeLogger.debug("WorkItems 鍙樻洿", {
              worktreeId: wtId,
              prevCount: prevWt.workItems?.length,
              nextCount: nextWt.workItems?.length,
            });
          }
        }

        if (!prev.error && next.error) {
          storeLogger.warn("Store 閿欒", { error: next.error });
        }
      },
      get,
      api,
    );
  };

/**
 * Session Slice 鈥?缁熶竴浼氳瘽绠＄悊锛圫essionHub锛? 鏃?sessionStore 鐘舵€乗n *
 * 涓ゅ鏁版嵁骞跺瓨浜?rootStore锛岀敱 sessionStore.ts 钖勫皝瑁呭眰瀵瑰鏆撮湶鏃?API銆俓n * 鎵€鏈夊姛鑳芥ā鍧楋紙chat/media/office/calendar/translation/knowledge锛夌殑浜や簰璁板綍
 * 缁熶竴瀛樺偍锛屾寜 worktree 闅旂銆俓n */

import type { StateCreator } from "zustand";
import type { SessionRecord, SessionContext } from "./types";
import type { RootState } from "./index";
import type { Session } from "@/types";
import { createLogger } from "@/utils/logger";
import { useModelSwitchStore } from "../modelSwitchStore";

const logger = createLogger("root-store:sessionSlice");

// 鈹€鈹€鈹€ Slice 鎺ュ彛 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

export interface SessionSlice {
  // 鈹€鈹€ 鏂?SessionHub 瀛楁 鈹€鈹€
  /** 鎵€鏈変細璇濊褰曪紙Record 淇濊瘉 O(1) 鎸?ID 鏌ユ壘锛孞SON 鎸佷箙鍖栧吋瀹癸級 */
  sessions: Record<string, SessionRecord>;

  /** 褰撳墠娲昏穬浼氳瘽 ID */
  currentSessionId: string | null;

  /** 鐢ㄦ埛鑷畾涔夌殑妯″潡鎺掑簭锛堟ā鍧?type 鏁扮粍锛?*/
  moduleOrder: string[];

  /** 鍥哄畾鐨勪細璇?ID 鍒楄〃 */
  pinnedSessionIds: string[];

  /** 鍔犺浇/鎿嶄綔閿欒 */
  error: string | null;

  /** 鏄惁姝ｅ湪鍔犺浇 */
  isLoading: boolean;

  // 鈹€鈹€ 鏃?sessionStore 鍏煎瀛楁 鈹€鈹€
  /** 鏃?Session[] 鏍煎紡锛坰essionStore 闀滃儚婧愶紝鏉ヨ嚜 sessionService.list()锛?*/
  chatSessions: Session[];

  /** 浼氳瘽鍒囨崲涓紙UI loading 鎸囩ず鍣級 */
  switching: boolean;

  // 鈹€鈹€鈹€ SessionHub 鍔ㄤ綔 鈹€鈹€鈹€
  createSession: (moduleType: string, title?: string, id?: string) => string;
  switchSession: (sessionId: string) => void;
  deleteSession: (sessionId: string) => void;
  renameSession: (id: string, title: string) => void;
  updateSessionContext: (id: string, updates: Partial<SessionContext>) => void;
  getOrCreateSession: (moduleType: string, title?: string) => string;
  getSessionsByWorktree: (worktreeId: string) => SessionRecord[];
  getSessionsByModule: (moduleType: string) => SessionRecord[];
  togglePin: (id: string) => void;
  isPinned: (id: string) => boolean;

  // 鈹€鈹€鈹€ 鏃?sessionStore 鍏煎鍔ㄤ綔锛堝紓姝ワ紝璋冪敤 sessionService锛夆攢鈹€鈹€
  /** 浠庡悗绔姞杞戒細璇濆垪琛?+ 褰撳墠浼氳瘽 */
  loadChatSessions: () => Promise<void>;
  /** 鍒涘缓鏂颁細璇濓紙璋冪敤 sessionService.create锛岃仈鍔?chatStore锛?*/
  createChatSession: (title: string) => Promise<Session>;
  /** 鍒囨崲浼氳瘽锛堝仠姝㈡祦銆乫lush銆佸姞杞芥秷鎭€佹仮澶嶆ā鍨嬨€佽仈鍔ㄥ伐浣滅┖闂达級 */
  switchChatSession: (id: string) => Promise<void>;
  /** 鍒犻櫎浼氳瘽 */
  deleteChatSession: (id: string) => Promise<void>;
  /** 閲嶅懡鍚嶄細璇?*/
  renameChatSession: (id: string, title: string) => Promise<void>;
  /** 娓呯┖鎵€鏈変細璇?*/
  clearAllChatSessions: () => Promise<void>;
}

// 鈹€鈹€鈹€ Slice 瀹炵幇 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

export const createSessionSlice: StateCreator<
  RootState,
  [],
  [],
  SessionSlice
> = (set, get) => ({
  // 鈹€鈹€ 鍒濆鐘舵€?鈹€鈹€
  sessions: {},
  currentSessionId: null,
  moduleOrder: [
    "chat",
    "media",
    "office",
    "calendar",
    "translation",
    "knowledge",
  ],
  pinnedSessionIds: [],
  error: null,
  isLoading: false,
  chatSessions: [],
  switching: false,

  // 鈹€鈹€鈹€ SessionHub 鍔ㄤ綔 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

  createSession: (moduleType, title, overrideId) => {
    const wtId = get().currentWorktreeId;
    const id =
      overrideId ??
      `sess-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const now = Date.now();

    let context: SessionContext;
    switch (moduleType) {
      case "media":
        context = { moduleType: "media", prompt: "" };
        break;
      case "office":
        context = { moduleType: "office", fileRef: "" };
        break;
      case "calendar":
        context = { moduleType: "calendar" };
        break;
      case "translation":
        context = { moduleType: "translation", sourceLang: "", targetLang: "" };
        break;
      case "knowledge":
        context = { moduleType: "knowledge" };
        break;
      default:
        context = { moduleType: "chat" };
    }

    const session: SessionRecord = {
      id,
      moduleType,
      worktreeId: wtId ?? "",
      title: title ?? `鏂?{getNameByModuleType(moduleType)}`,
      createdAt: now,
      updatedAt: now,
      context,
    };

    set((state) => ({
      sessions: { ...state.sessions, [id]: session },
      currentSessionId: overrideId ? state.currentSessionId : id,
    }));

    logger.info("浼氳瘽鍒涘缓", { sessionId: id, moduleType, worktreeId: wtId });
    return id;
  },

  switchSession: (sessionId) => {
    if (!get().sessions[sessionId]) {
      logger.warn("鍒囨崲浼氳瘽澶辫触锛氫細璇濅笉瀛樺湪", { sessionId });
      return;
    }
    set({ currentSessionId: sessionId });
    logger.info("浼氳瘽鍒囨崲", { sessionId });
  },

  deleteSession: (sessionId) => {
    const { [sessionId]: _removed, ...rest } = get().sessions;
    set((state) => ({
      sessions: rest,
      currentSessionId:
        state.currentSessionId === sessionId ? null : state.currentSessionId,
      pinnedSessionIds: state.pinnedSessionIds.filter((id) => id !== sessionId),
    }));
    logger.info("浼氳瘽鍒犻櫎", { sessionId });
  },

  renameSession: (id, title) => {
    set((state) => {
      const sess = state.sessions[id];
      if (!sess) return state;
      return {
        sessions: {
          ...state.sessions,
          [id]: { ...sess, title, updatedAt: Date.now() },
        },
      };
    });
  },

  updateSessionContext: (id, updates) => {
    set((state) => {
      const sess = state.sessions[id];
      if (!sess) return state;
      return {
        sessions: {
          ...state.sessions,
          [id]: {
            ...sess,
            context: { ...sess.context, ...updates } as SessionContext,
            updatedAt: Date.now(),
          },
        },
      };
    });
  },

  getOrCreateSession: (moduleType, title) => {
    const wtId = get().currentWorktreeId;
    const existing = Object.values(get().sessions).find(
      (s) => s.worktreeId === wtId && s.moduleType === moduleType,
    );
    if (existing) {
      set({ currentSessionId: existing.id });
      return existing.id;
    }
    return get().createSession(moduleType, title);
  },

  getSessionsByWorktree: (worktreeId) =>
