/**
 * 鍓嶇缁熶竴閿欒澶勭悊
 *
 * 涓庡悗绔?error/handleError.ts 鍔熻兘瀵归綈锛歕n * - 閿欒鏍囧噯鍖栵紙杞?AppError锛塡n * - OTEL Span 杩借釜
 * - 鍒嗙骇鏃ュ織璁板綍
 * - 鍚庣閿欒涓婃姤锛堝紓姝ワ紝涓嶉樆濉烇級
 * - 鍐呭瓨閿欒缁熻锛堜緵浠〃鐩樺睍绀猴級
 */

import { AppError, ErrorCategory, ErrorSeverity } from "../error/types";
import { getOTelTracing } from "../monitoring/otel/OTelTracing";
import { getBackendBaseUrl, getApiSecret } from "../services/backendUrl";

/**
 * 缁熶竴閿欒澶勭悊閫夐」
 */
export interface HandleErrorOptions {
  /** 蹇呬紶锛氬摢涓ā鍧?*/
  module: string;
  /** 褰撴椂鍦ㄥ仛浠€涔?*/
  action?: string;
  /** 闄勫姞涓婁笅鏂?*/
  meta?: Record<string, unknown>;
}

// ---------------------------------------------------------------------------
// 鍐呭瓨閿欒缁熻
// ---------------------------------------------------------------------------

interface TrackedEntry {
  id: string;
  message: string;
  category: ErrorCategory;
  severity: ErrorSeverity;
  code?: string;
  module: string;
  action?: string;
  timestamp: number;
  stack?: string;
}

const MAX_TRACKED = 500;
const MAX_RECENT = 50;

/** 鍐呭瓨涓殑閿欒缁熻 */
export const errorStats = {
  total: 0,
  byCategory: {} as Record<string, number>,
  bySeverity: {} as Record<string, number>,
  recent: [] as TrackedEntry[],
};

/** 宸茶拷韪殑閿欒鍒楄〃锛堜緵浠〃鐩?UI 灞曠ず锛?*/
let trackedErrors: TrackedEntry[] = [];

function recordToMemory(entry: TrackedEntry): void {
  errorStats.total++;
  errorStats.byCategory[entry.category] =
    (errorStats.byCategory[entry.category] || 0) + 1;
  errorStats.bySeverity[entry.severity] =
    (errorStats.bySeverity[entry.severity] || 0) + 1;

  errorStats.recent.unshift(entry);
  if (errorStats.recent.length > MAX_RECENT) {
    errorStats.recent = errorStats.recent.slice(0, MAX_RECENT);
  }

  trackedErrors.push(entry);
  if (trackedErrors.length > MAX_TRACKED) {
    trackedErrors = trackedErrors.slice(-MAX_TRACKED);
  }
}

/** 鑾峰彇宸茶拷韪敊璇垪琛紙娓呯┖鍚庤繑鍥烇紝渚涗华琛ㄧ洏杞锛?*/
export function drainTrackedErrors(): TrackedEntry[] {
  const drained = trackedErrors;
  trackedErrors = [];
  return drained;
}

// ---------------------------------------------------------------------------
// 鍚庣涓婃姤
// ---------------------------------------------------------------------------

const REPORT_THROTTLE_MS = 5000;
const PENDING_ERRORS: TrackedEntry[] = [];

let reportTimer: ReturnType<typeof setTimeout> | null = null;

function scheduleReport(): void {
  if (reportTimer) return;
  reportTimer = setTimeout(async () => {
    reportTimer = null;
    if (PENDING_ERRORS.length === 0) return;

    const batch = PENDING_ERRORS.splice(0);
    try {
      const baseUrl = getBackendBaseUrl();
      const body = JSON.stringify({
        errors: batch.map((e) => ({
          message: e.message,
          category: e.category,
          severity: e.severity,
          code: e.code,
          module: e.module,
          action: e.action,
          timestamp: e.timestamp,
          stack: e.stack?.split("\n").slice(0, 3).join("\n"),
        })),
      });

      const headers: Record<string, string> = {
        "Content-Type": "application/json",
      };
      const secret = getApiSecret();
      if (secret) headers["X-API-Key"] = secret;

      await fetch(`${baseUrl}/v1/errors/report`, {
        method: "POST",
        headers,
        body,
        // 涓嶉樆濉烇紝闈欓粯澶辫触
      }).catch(() => {});
    } catch {
      // 闈欓粯澶辫触
    }
  }, REPORT_THROTTLE_MS);
}

function reportToBackend(entry: TrackedEntry): void {
  PENDING_ERRORS.push(entry);
  scheduleReport();
}

// ---------------------------------------------------------------------------
// 缁熶竴閿欒澶勭悊鍏ュ彛
// ---------------------------------------------------------------------------

/**
 * 缁熶竴鐨勯敊璇鐞嗗叆鍙ｅ嚱鏁癨n *
 * 鎵€鏈?catch 鍧楃殑鏍囧噯妯″紡锛歕n * 1. 杞负 AppError锛堟爣鍑嗗寲锛塡n * 2. 璁板綍鍒?OTEL Span
 * 3. 鍒嗙骇鏃ュ織杈撳嚭
 * 4. 鍐呭瓨缁熻锛堜緵浠〃鐩橈級
 * 5. 鍚庣寮傛涓婃姤
 *
 * @param error 鎹曡幏鍒扮殑閿欒瀵硅薄
 * @param options 澶勭悊閫夐」
 * @returns 鏍囧噯鍖栧悗鐨?AppError 瀹炰緥
 */
export function handleClientError(
  error: unknown,
  options: HandleErrorOptions,
  _severity?: "warn" | "error", // 淇濈暀绛惧悕鍏煎鎬n): AppError {
  // 1. 杞负 AppError锛堟爣鍑嗗寲锛塡n  const appError =
    error instanceof AppError
      ? error
      : new AppError(
          (error as Error)?.message || String(error),
          ErrorCategory.UNKNOWN,
          ErrorSeverity.MEDIUM,
          "UNHANDLED_ERROR",
        );

  const { module, action, meta } = options;

  // 2. OTEL Span 杩借釜
  const otel = getOTelTracing();
  const span = otel.getActiveSpan();
  if (span) {
    otel.recordError(span, error);
    span.setAttribute("error.module", module);
    if (action) span.setAttribute("error.action", action);
    if (meta) {
      Object.entries(meta).forEach(([k, v]) => {
        if (typeof v === "string" || typeof v === "number") {
          span.setAttribute(`meta.${k}`, v);
        }
      });
    }
  }

  // 3. 鍒嗙骇鏃ュ織杈撳嚭
  const logMeta = {
    category: appError.category,
    severity: appError.severity,
    code: appError.code,
    module,
    action,
    ...meta,
  };

  if (appError.severity === ErrorSeverity.CRITICAL) {
    console.error(`[${module}] ${appError.message}`, logMeta, appError.stack);
  } else if (appError.severity === ErrorSeverity.HIGH) {
    console.warn(`[${module}] ${appError.message}`, logMeta);
  } else {
    console.log(`[${module}] ${appError.message}`, logMeta);
  }

  // 4. 鍐呭瓨缁熻
  const entry: TrackedEntry = {
    id: `client_${Date.now()}_${Math.random().toString(36).substring(2, 8)}`,
    message: appError.message,
    category: appError.category,
    severity: appError.severity,
    code: appError.code,
    module,
    action,
    timestamp: Date.now(),
    stack: (error as Error)?.stack,
  };
  recordToMemory(entry);

  // 5. 鍚庣寮傛涓婃姤
  reportToBackend(entry);

  return appError;
}

/**
 * 鍓嶇 Logger
 *
 * 缁熶竴鏃ュ織鏍煎紡锛岀敓浜х幆澧冨彲鎶戝埗 DEBUG 绾у埆鏃ュ織銆俓n * 鏃ュ織鍚屾椂杈撳嚭鍒?console 鍜?localStorage锛堟寔涔呭寲锛夈€俓n */

import { logStore } from "./logStore";

type LogLevel = "debug" | "info" | "warn" | "error";

const LOG_LEVEL_PRIORITY: Record<LogLevel, number> = {
  debug: 0,
  info: 1,
  warn: 2,
  error: 3,
};

const currentLevel: LogLevel =
  (import.meta.env.VITE_LOG_LEVEL as LogLevel) || "debug";

function shouldLog(level: LogLevel): boolean {
  return LOG_LEVEL_PRIORITY[level] >= LOG_LEVEL_PRIORITY[currentLevel];
}

export function createLogger(module: string) {
  const prefix = `[${module}]`;

  return {
    debug: (msg: string, data?: unknown) => {
      if (!shouldLog("debug")) return;
      console.debug(prefix, msg, data ?? "");
      logStore.add("debug", module, msg, data);
    },

    info: (msg: string, data?: unknown) => {
      if (!shouldLog("info")) return;
      console.info(prefix, msg, data ?? "");
      logStore.add("info", module, msg, data);
    },

    warn: (msg: string, data?: unknown) => {
      if (!shouldLog("warn")) return;
      console.warn(prefix, msg, data ?? "");
      logStore.add("warn", module, msg, data);
    },

    error: (msg: string, data?: unknown) => {
      if (!shouldLog("error")) return;
      console.error(prefix, msg, data ?? "");
      logStore.add("error", module, msg, data);
    },
  };
}

/**
 * Store 鐘舵€佸彉鏇存棩蹇楀伐鍏穃n *
 * 涓?Zustand Store 娣诲姞寮€鍙戠幆澧冪殑鐘舵€佸彉鏇存棩蹇楋紝鐢ㄤ簬璋冭瘯銆俓n * 浠呭湪 import.meta.env.DEV 鏃剁敓鏁堛€俓n *
 * 浣跨敤鏂瑰紡锛歕n *   import { withStoreLogging } from "../utils/storeLogger";
 *   withStoreLogging(useChatStore, "chatStore", ["sendMessage"]);
 */

import type { StoreApi } from "zustand";

/**
 * 涓烘寚瀹?Store 璁㈤槄鐘舵€佸彉鏇存棩蹇梊n *
 * @param store - Zustand store锛坲seXxxStore 鏈韩锛塡n * @param name  - Store 鍚嶇О锛岀敤浜庢棩蹇楀墠缂€
 * @param ignore - 蹇界暐鐨?key 鍒楄〃锛堥珮棰戝彉鍖栧瓧娈碉紝濡?_navigate銆乴oading 绛夛級
 */
export function withStoreLogging<T extends Record<string, any>>(
  store: StoreApi<T>,
  name: string,
  ignore: string[] = [],
): void {
  if (!import.meta.env.DEV) return;

  const ignored = new Set<string>(ignore);

  store.subscribe((state, prev) => {
    const changed: string[] = [];

    for (const key of Object.keys(state)) {
      if (ignored.has(key)) continue;
      if (state[key as keyof T] !== prev[key as keyof T]) {
        changed.push(key);
      }
    }

    if (changed.length > 0) {
      console.log(
        `%c[${name}] %c${changed.join(", ")}`,
        "color:#8b5cf6;font-weight:bold",
        "color:#a78bfa",
      );
    }
  });
}
